window.HI_DATA = {"tracks":{"_meta":{"version":"1.0","note":"BPM, clés Camelot et listes de machines (gear) sont des valeurs éditoriales indicatives, établies pour le jeu de transitions. Elles doivent être vérifiées sur pressage original avant toute publication définitive."},"eras":[{"id":"era-1","name":"I · Les Fondations","range":"1973–1989","desc":"Du Loft au Paradise Garage, de la Music Box à l'Haçienda : la disco survit dans les clubs noirs, latinos et gays, puis se reprogramme sur des boîtes à rythmes bon marché.","name_en":"I · Foundations","range_en":"1973–1989","desc_en":"From the Loft to the Paradise Garage, from the Music Box to the Haçienda: disco survives in Black, Latino and gay clubs, then gets reprogrammed on cheap drum machines."},{"id":"era-2","name":"II · Mutations & Diasporas","range":"1990–2004","desc":"La house traverse l'Atlantique et se fragmente : tribal new-yorkais, filtres parisiens, 2-step londonien, tech house des warehouses.","name_en":"II · Mutations & Diasporas","range_en":"1990–2004","desc_en":"House crosses the Atlantic and splinters: New York tribal, Parisian filters, London 2-step, warehouse tech house."},{"id":"era-3a","name":"III-a · Berlin, bass & blogs","name_en":"III-a · Berlin, bass & blogs","range":"2005–2012","range_en":"2005–2012","desc":"Berghain et la minimale, le dubstep de Croydon, la seconde vague French Touch, la house sud-africaine qui s'organise en labels : la house se fragmente entre clubs, blogs et forums.","desc_en":"Berghain and minimal, Croydon's dubstep, the French Touch's second wave, South African house organising into labels: house splinters between clubs, blogs and forums."},{"id":"era-3b","name":"III-b · Crossover & revivals","name_en":"III-b · Crossover & revivals","range":"2013–2019","range_en":"2013–2019","desc":"La house revient en tête des charts, le footwork de Chicago s'exporte, le gqom de Durban arrive en Europe, la lo-fi naît sur YouTube et la ballroom devient une référence mondiale.","desc_en":"House returns to the top of the charts, Chicago footwork goes global, Durban's gqom reaches Europe, lo-fi is born on YouTube and ballroom becomes a worldwide reference."},{"id":"era-3c","name":"III-c · Sud global & réappropriation","name_en":"III-c · Global South & reclamation","range":"2020–","range_en":"2020–","desc":"Pandémie, amapiano mondial, retour du dubstep, house noire et queer au cœur de la pop : la house se raconte depuis ses communautés d'origine et depuis le Sud global.","desc_en":"Pandemic, global amapiano, dubstep's return, Black and queer house at the heart of pop: house is told from its original communities and from the Global South."}],"genres":[{"id":"chicago","name":"Chicago House","era":"era-1","color":"#ff6b35","groove":"jack","swing":0.04,"style":"Boîtes à rythmes brutes, basses rebondissantes, pianos et voix gospel : le jack, la danse comme injonction.","style_en":"Raw drum machines, bouncing basslines, pianos and gospel voices: jack, dancing as a command."},{"id":"acid","name":"Acid House","era":"era-1","color":"#d4ff3a","groove":"acid","swing":0,"style":"La TB-303 qui couine et mute sur un kick sec : la basse devient voix, la piste entre en transe.","style_en":"The TB-303 squealing and mutating over a dry kick: the bass becomes a voice, the floor goes into trance."},{"id":"garage-nyc","name":"Garage House NYC","era":"era-1","color":"#ff3e9a","groove":"garage","swing":0.1,"style":"Soul, gospel et dub : des voix de divas, des grooves souples et une piste pensée comme une église.","style_en":"Soul, gospel and dub: diva vocals, loose grooves and a dancefloor conceived as a church."},{"id":"hip-house","name":"Hip-House","era":"era-1","color":"#ffb627","groove":"hiphouse","swing":0.12,"style":"Le kick house rencontre le flow rap : le MC remplace la diva.","style_en":"The house kick meets the rap flow: the MC replaces the diva."},{"id":"detroit","name":"Detroit","era":"era-1","color":"#5ad2ff","groove":"four","swing":0,"style":"Futurisme machine, nappes orchestrales et 909 implacable : la techno née de la ville post-industrielle.","style_en":"Machine futurism, orchestral pads and a relentless 909: techno born of the post-industrial city."},{"id":"deep","name":"Deep House","era":"era-1","color":"#7b8cff","groove":"deep","swing":0.08,"style":"Accords jazz, nappes chaudes et tempo retenu : l'émotion par l'harmonie plutôt que par l'effet.","style_en":"Jazz chords, warm pads and a held-back tempo: emotion through harmony rather than effects."},{"id":"balearic","name":"Balearic House","era":"era-1","color":"#ffd28a","groove":"deep","swing":0.05,"style":"Tempo lent, guitares, sons de mer et éclectisme : la house comme paysage de lever de soleil.","style_en":"Slow tempo, guitars, ocean sounds and eclecticism: house as a sunrise landscape."},{"id":"tribal-nyc","name":"Tribal House NYC","era":"era-2","color":"#e94bff","groove":"tribal","swing":0.06,"style":"Toms et percussions en cascade, longues montées et divas : la cathédrale des grands clubs gays new-yorkais.","style_en":"Cascading toms and percussion, long builds and divas: the cathedral of New York's big gay clubs."},{"id":"french-touch","name":"French Touch","era":"era-2","color":"#4dffc3","groove":"filter","swing":0.02,"style":"Boucles disco filtrées, compression qui pompe, ou techno et jazz côté F Communications.","style_en":"Filtered disco loops and pumping compression, or the techno and jazz of F Communications."},{"id":"tech-house","name":"Tech House","era":"era-2","color":"#a3a3a3","groove":"four","swing":0.03,"style":"Basse roulante, percussions sèches et sobriété techno : une musique de longues nuits de DJ.","style_en":"Rolling bass, dry percussion and techno restraint: music for long DJ nights."},{"id":"ukg","name":"UK Garage","era":"era-2","color":"#3affc0","groove":"twostep","swing":0.22,"style":"2-step : le kick saute, les charlestons swinguent, la voix R&B danse sur la syncope.","style_en":"Two-step: the kick skips, the hats swing, the R&B vocal dances on the syncopation."},{"id":"afro","name":"Afro House","era":"era-3a","color":"#ff9f1c","groove":"afro","swing":0.1,"style":"Percussions boisées et polyrythmies, nappes mélancoliques : la house réécrite depuis l'Afrique du Sud.","style_en":"Woody percussion and polyrhythms, melancholic pads: house rewritten from South Africa."},{"id":"lofi","name":"Lo-Fi House","era":"era-3b","color":"#c9a0ff","groove":"lofi","swing":0.14,"style":"Saturation, souffle et samples voilés : la house comme souvenir granuleux.","style_en":"Saturation, hiss and veiled samples: house as a grainy memory."},{"id":"amapiano","name":"Amapiano","era":"era-3c","color":"#ffe14d","groove":"amapiano","swing":0.18,"style":"Log drum qui glisse, shakers continus et tempo lent : un groove qui balance plus qu'il ne pousse.","style_en":"Gliding log drum, constant shakers and a slow tempo: a groove that sways more than it pushes."},{"id":"disco","name":"Disco & proto-house","era":"era-1","color":"#ffa3c7","groove":"disco","swing":0.03,"family":"cousin","style":"Orchestres, basses en octaves, puis synthés séquencés : la matrice sociale et technique de la house.","style_en":"Orchestras, octave basslines, then sequenced synths: the social and technical matrix of house.","name_en":"Disco & proto-house"},{"id":"electro","name":"Électro & synth-pop","name_en":"Electro & synth-pop","era":"era-1","color":"#cbd5e1","groove":"breakbeat","swing":0.02,"family":"cousin","style":"Boîtes à rythmes programmées, séquences et synthés froids, de Tokyo au Bronx et à Manchester : la machine avant la house.","style_en":"Programmed drum machines, sequences and cold synths, from Tokyo to the Bronx and Manchester: the machine before house."},{"id":"rave-jungle","name":"Rave, Hardcore & Jungle","era":"era-2","color":"#ff4040","groove":"breakbeat","swing":0.06,"family":"cousin","style":"Breakbeats accélérés, stabs rave, basses reggae : la lignée hardcore britannique jusqu'à 170 BPM.","style_en":"Sped-up breakbeats, rave stabs, reggae basslines: the British hardcore lineage up to 170 BPM."},{"id":"trance","name":"Trance","era":"era-2","color":"#9b5cff","groove":"trance","swing":0,"family":"cousin","style":"Arpèges en spirale, montées et breaks euphoriques : la ramification européenne de la house.","style_en":"Spiralling arpeggios, builds and euphoric breakdowns: house's European offshoot."},{"id":"uk-bass","name":"Bleep, sound system & dubstep","name_en":"Bleep, sound system & dubstep","era":"era-1","color":"#facc15","groove":"breakbeat","swing":0.08,"family":"cousin","style":"Sound systems jamaïcains, sub-bass, tonalités pures puis wobble : la lignée bass britannique, de Soul II Soul à Skream.","style_en":"Jamaican sound systems, sub-bass, pure tones then wobble: the British bass lineage, from Soul II Soul to Skream."},{"id":"techno","name":"Techno européenne (Francfort → Berlin)","name_en":"European techno (Frankfurt → Berlin)","era":"era-3a","color":"#94a3b8","groove":"four","swing":0,"family":"cousin","style":"Kick sec, basses sourdes et nuits sans fin : la techno de Detroit réécrite à Francfort puis à Berlin.","style_en":"Dry kick, muffled basslines and endless nights: Detroit techno rewritten in Frankfurt, then Berlin."},{"id":"footwork","name":"Footwork & ghetto house","name_en":"Footwork & ghetto house","era":"era-3b","color":"#fb923c","groove":"breakbeat","swing":0.04,"family":"cousin","style":"La ghetto house de Chicago accélérée autour de 160 BPM : samples hachés, kicks en triolets, danse en battles.","style_en":"Chicago ghetto house sped up to around 160 BPM: chopped samples, triplet kicks, dance battles."},{"id":"gqom","name":"Gqom (Durban)","name_en":"Gqom (Durban)","era":"era-3b","color":"#84cc16","groove":"afro","swing":0.06,"family":"cousin","style":"Kicks lourds et brisés, percussions sèches, sans ligne de basse classique : la house brute des townships de Durban.","style_en":"Heavy, broken kicks, dry percussion, no conventional bassline: the raw house of Durban's townships."},{"id":"ballroom","name":"Ballroom & Qween Beat","name_en":"Ballroom & Qween Beat","era":"era-3a","color":"#f9a8d4","groove":"tribal","swing":0.04,"family":"cousin","style":"Le « ha », le crash et les chants des commentateurs : la musique faite pour les catégories et le vogue.","style_en":"The \"ha\", the crash and the commentators' chants: music made for the categories and for vogue."},{"id":"chart-house","name":"House dans les charts (2013–)","name_en":"Chart house (2013–)","era":"era-3b","color":"#38bdf8","groove":"four","swing":0.03,"family":"cousin","style":"Basses rondes, voix pop et radio : la deep house et le garage reviennent en tête des classements.","style_en":"Round basslines, pop vocals and radio: deep house and garage return to the top of the charts."}],"tracks":[{"id":"on-and-on","title":"On and On","artist":"Jesse Saunders","year":1984,"label":"Jes Say Records","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-1","bpm":120,"camelot_key":"5A","energy":6,"gear":["tr-808"],"construction":"Une TR-808 programmée en boucle, une basse synthétique qui rebondit et une voix réduite à un mantra. Saunders recrée de mémoire un edit bootleg qu'il jouait en club et qu'on lui avait volé : la house commence comme une copie domestique d'un disque disparu.","producer_origins":"DJ du club The Playground, Saunders travaille avec Vince Lawrence et fait presser le disque à l'usine Musical Products de Larry Sherman, future maison de Trax Records. Le modèle est posé : un DJ, une machine d'occasion, un pressage indépendant et une sortie directe vers les bacs locaux.","club_sociology":"Chicago sort du « Disco Demolition Night » de 1979, quand la radio rock a déclaré la disco morte. Elle survit pourtant dans les clubs du South Side et sur WBMX, où les Hot Mix 5 diffusent des mixes que les ados enregistrent sur cassette. Le 12\" auto-produit répond à une pénurie : il n'y a plus assez de disco neuve pour nourrir les pistes.","queer_ballroom_axis":"Selon la version la plus répandue, le mot « house » viendrait du Warehouse, club fréquenté majoritairement par des hommes gays noirs où Frankie Knuckles mixe de 1977 à 1982 (l'étymologie reste disputée). Saunders appartient à une scène plus mixte et plus jeune : le son a quitté très tôt son berceau queer pour circuler dans toute la ville.","archive_ref":{"source":"history-of-house","note":"Débats sur le « premier disque house » et rôle des pressages indépendants de Chicago.","note_en":"Debates over the \"first house record\" and the role of Chicago's independent pressings."},"why_this_record":"C'est le disque le plus souvent cité comme premier 12\" house pressé. Il est moins important pour sa musique que pour le geste qu'il incarne : n'importe qui avec une 808 peut désormais faire un disque.","tags":["roots","diy","us"],"further_reading":["do-you-remember-house","energy-never-dies","real-story-saunders"],"youtube":["Z-sspvjxMo0","Be7o_ym2dNc","NQ7ISClDz3U"],"construction_en":"A looped TR-808, a bouncing synth bass and a vocal pared down to a mantra. Saunders rebuilt from memory a bootleg edit he used to play out and that had been stolen from him: house begins as a home-made copy of a vanished record.","producer_origins_en":"A DJ at The Playground, Saunders worked with Vince Lawrence and had the record pressed at Larry Sherman's Musical Products plant, the future home of Trax Records. The template was set: a DJ, a second-hand machine, an independent pressing and a straight line to the local record shops.","club_sociology_en":"Chicago was coming out of the 1979 \"Disco Demolition Night\", when rock radio declared disco dead. Yet disco survived in South Side clubs and on WBMX, where the Hot Mix 5 broadcast mixes that teenagers taped off the radio. The self-released 12\" answered a shortage: there simply wasn't enough new disco left to feed the dancefloors.","queer_ballroom_axis_en":"According to the most common version, the word \"house\" comes from the Warehouse, a club whose crowd was mostly Black gay men and where Frankie Knuckles played from 1977 to 1982 (the etymology is disputed). Saunders belonged to a younger, more mixed scene: the sound left its queer cradle very early and spread across the city.","why_this_record_en":"It is the record most often cited as the first house 12\" ever pressed. It matters less for its music than for the gesture it embodies: from now on, anyone with an 808 can make a record.","verified":false},{"id":"move-your-body","title":"Move Your Body (The House Music Anthem)","artist":"Marshall Jefferson","year":1986,"label":"Trax Records","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-1","bpm":121,"camelot_key":"8B","energy":8,"gear":["tr-707","Piano acoustique (overdub)"],"construction":"Des accords de piano martelés sur un pattern de boîte à rythmes rigide, une basse en octaves et un chant d'église porté par Curtis McClain. C'est l'acte de naissance du piano house : la ferveur gospel posée sur une grille mécanique.","producer_origins":"Jefferson travaille à la poste et découvre le matériel en autodidacte, en achetant des machines à crédit. Il ne vient pas du conservatoire : il compose en enregistrant des pistes une à une et assume une approche « non-musicien » qui deviendra la norme de la house.","club_sociology":"Ron Hardy le joue à la Music Box, le club le plus brut de Chicago ; Frankie Knuckles, depuis le Power Plant, en fait lui aussi un incontournable. Le sous-titre « The House Music Anthem » est une revendication : une scène qui se nomme et se donne un hymne.","queer_ballroom_axis":"La Music Box rassemble un public noir, gay et ouvrier pour qui la piste fonctionne comme une église séculière. Les paroles (« gotta have house music, all night long ») ritualisent cette communauté réunie par la danse.","archive_ref":{"source":"last-night-dj","note":"Chapitre Chicago : Ron Hardy, Music Box et la rivalité avec Frankie Knuckles.","note_en":"Chicago chapter: Ron Hardy, the Music Box and the rivalry with Frankie Knuckles."},"why_this_record":"Il prouve que la house peut être euphorique et mélodique sans rien perdre de sa rudesse rythmique.","tags":["roots","gospel","piano","queer","us"],"further_reading":["do-you-remember-house","energy-never-dies","musique-house-bidder","real-story-saunders"],"spotify":{"id":"5eAymAmVU6CyejjFJxvcMI"},"youtube":["QAR8cq5Bl94","yFdbueklpwY","RhKMMh4qOL8"],"construction_en":"Hammered piano chords over a rigid drum-machine pattern, an octave bassline and a church-born vocal from Curtis McClain. This is the birth certificate of piano house: gospel fervour laid over a mechanical grid.","producer_origins_en":"Jefferson worked at the post office and taught himself the gear, buying machines on credit. No conservatory background: he built tracks part by part and embraced a \"non-musician\" approach that would become house's default.","club_sociology_en":"Ron Hardy played it at the Music Box, Chicago's rawest club; Frankie Knuckles, at the Power Plant, made it a staple too. The subtitle \"The House Music Anthem\" is a statement: a scene naming itself and giving itself an anthem.","queer_ballroom_axis_en":"The Music Box drew a Black, gay, working-class crowd for whom the dancefloor worked like a secular church. The lyrics (\"gotta have house music, all night long\") turn that dance-bound community into ritual.","why_this_record_en":"It proves house can be euphoric and melodic without losing any of its rhythmic grit.","gear_en":["tr-707","Acoustic piano (overdub)"],"verified":false},{"id":"acid-tracks","title":"Acid Tracks","artist":"Phuture","year":1987,"label":"Trax Records","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"acid","era":"era-1","bpm":120,"camelot_key":"10A","energy":7,"gear":["tb-303","tr-707"],"construction":"Douze minutes de TB-303 dont on tourne en continu les potards de cutoff, de résonance et d'enveloppe sur une 707 sèche. La mélodie compte peu : tout se joue dans la mutation du timbre, une basse qui « parle », couine et s'étrangle.","producer_origins":"DJ Pierre, Earl « Spanky » Smith Jr. et Herb J. bricolent une 303 achetée d'occasion sans savoir s'en servir. L'accident devient méthode : Spanky programme, Pierre triture les réglages jusqu'à trouver ce son.","club_sociology":"Ron Hardy joue la cassette plusieurs fois dans la même nuit à la Music Box. Le public la rejette d'abord, puis la réclame. Le nom « acid » naît de la rumeur selon laquelle le DJ mettait du LSD dans l'eau. La légende précède le disque.","queer_ballroom_axis":"L'acide naît dans l'espace noir et gay de la Music Box. Lorsqu'il traverse l'Atlantique, il est réapproprié par la jeunesse blanche britannique de la rave. Le smiley efface en partie ses origines : c'est un cas d'école de déracinement culturel.","archive_ref":{"source":"modulations","note":"Segment Chicago/acid : la TB-303 comme machine « ratée » réinventée.","note_en":"Chicago/acid segment: the TB-303 as a \"failed\" machine reinvented."},"why_this_record":"Il montre de la manière la plus pure comment un instrument conçu pour un usage devient tout autre chose dans les mains de jeunes DJs.","tags":["roots","machine","queer","us"],"further_reading":["class-of-88","do-you-remember-house","energy-flash","energy-never-dies","rave-art","real-story-saunders"],"spotify":{"id":"2aLXJJ2zOsBJlGTxiG0yMi"},"youtube":["yKHGv6Es610","igNBeo3QSqc","PJJ5FxpVGUY"],"construction_en":"Twelve minutes of TB-303 whose cutoff, resonance and envelope knobs are twisted non-stop over a bone-dry 707. The melody barely matters: everything happens in the mutating timbre, a bassline that \"talks\", squeals and chokes.","producer_origins_en":"DJ Pierre, Earl \"Spanky\" Smith Jr. and Herb J tinkered with a second-hand 303 without knowing how to use it. The accident became the method: Spanky programmed, Pierre tweaked the settings until that sound appeared.","club_sociology_en":"Ron Hardy played the tape several times in one night at the Music Box. The crowd rejected it at first, then demanded it. The name \"acid\" came from a rumour that the DJ was spiking the water with LSD. The legend arrived before the record.","queer_ballroom_axis_en":"Acid was born in the Black and gay space of the Music Box. Once it crossed the Atlantic, it was re-appropriated by Britain's white rave youth, and the smiley partly erased its origins: a textbook case of cultural uprooting.","why_this_record_en":"It shows, in its purest form, how an instrument designed for one job becomes something else entirely in the hands of young DJs.","verified":false},{"id":"voodoo-ray","title":"Voodoo Ray","artist":"A Guy Called Gerald","year":1988,"label":"Rham! Records (Wallasey)","city":"Manchester","country":"Royaume-Uni","continent":"Europe","genre":"acid","era":"era-1","bpm":122,"camelot_key":"9A","energy":6,"gear":["tb-303","tr-808","Roland SH-101"],"construction":"Une 303 plus mélodique que chez Phuture, un groove 808 léger et une voix samplée découpée jusqu'à l'abstraction. Le morceau est réenregistré en deux jours aux Moonraker Studios de Manchester en juin 1988.","producer_origins":"Gerald Simpson, jeune Mancunien noir passé par 808 State, produit dans sa chambre avec du matériel d'occasion. Son approche est britannique : il absorbe la house de Chicago par les imports et les cassettes, puis la mélange avec le dub et l'électro.","club_sociology":"Hymne du Second Summer of Love en 1988 : l'Haçienda, les warehouse parties, puis les raves orbitales autour de la M25. La culture club britannique devient un mouvement de masse et un problème politique qui mène au Criminal Justice Act de 1994.","queer_ballroom_axis":"L'Haçienda lancera Flesh (1991-1995), sa grande soirée gay, ce qui rappelle que la scène acid de Manchester n'était pas que laddish. Garratt documente la coexistence tendue entre clubs gays londoniens et raves hétéros.","archive_ref":{"source":"adventures-wonderland","note":"Récit du Second Summer of Love et de l'Haçienda.","note_en":"Account of the Second Summer of Love and the Haçienda."},"why_this_record":"C'est le premier grand classique acid produit hors des États-Unis, la preuve que la house devenait une langue que d'autres pouvaient parler.","tags":["uk","rave","machine"],"further_reading":["electrochoc","energy-flash","hacienda-hook","rave-art","second-summer","sonic-youth-floor"],"spotify":{"id":"3RTnNwz2gBvPdEaGQluT2Y"},"youtube":["j7vxHOCeiQ4","NgRRxUlt3zc","5LiFdvTzZOY"],"construction_en":"A more melodic 303 than Phuture's, a light 808 groove and a sampled voice chopped into abstraction. The track was re-recorded in two days at Manchester's Moonraker Studios in June 1988.","producer_origins_en":"Gerald Simpson, a young Black Mancunian who passed through 808 State, produced it in his bedroom on second-hand gear. His approach is British: he absorbed Chicago house through imports and tapes, then mixed it with dub and electro.","club_sociology_en":"An anthem of 1988's Second Summer of Love: the Haçienda, warehouse parties, then the orbital raves around the M25. British club culture became a mass movement and a political problem that led to the 1994 Criminal Justice Act.","queer_ballroom_axis_en":"The Haçienda would launch Flesh (1991–1995), its big gay night, a reminder that Manchester's acid scene wasn't only laddish. Garratt documents the uneasy coexistence of London's gay clubs and straight raves.","why_this_record_en":"The first great acid classic made outside the United States, proof that house had become a language others could speak.","country_en":"United Kingdom","verified":false,"story":"Gerald Simpson, né à Moss Side, a commencé le morceau en démo alors qu'il était dans 808 State. Il le réenregistre en juin 1988, en deux jours, aux Moonraker Studios de Manchester, avec l'aide du duo Chapter (Aniff Akinola et Colin Thorpe) et de l'ingénieur Lee Monteverde. Le label Rham!, basé à Wallasey, presse 500 exemplaires, vendus en une journée. Le disque s'impose à l'Haçienda puis dans les clubs underground. Il entre au classement britannique en 1989 (n°12) et passe pour le premier morceau d'acid house produit au Royaume-Uni. Warlock le sort aux États-Unis en 1989.","story_en":"Gerald Simpson, from Moss Side, began the track as a demo while still in 808 State. He re-recorded it in June 1988 over two days at Manchester's Moonraker Studios, with help from the duo Chapter (Aniff Akinola and Colin Thorpe) and engineer Lee Monteverde. Rham!, based in Wallasey, pressed 500 copies, which sold out in a day. The record took hold at the Haçienda and then in underground clubs. It entered the UK chart in 1989 (no. 12) and is regarded as the first acid house track made in Britain. Warlock released it in the US in 1989.","timeline":[{"date":"1988","fr":"Démo pendant la période 808 State.","en":"Demo made during the 808 State period."},{"date":"1988-06","fr":"Enregistrement de deux jours aux Moonraker Studios.","en":"Two-day session at Moonraker Studios."},{"date":"1988-11","fr":"Sortie sur Rham! (500 exemplaires, épuisés en un jour).","en":"Released on Rham! (500 copies, sold out in a day)."},{"date":"1989","fr":"Entrée au classement britannique, n°12 ; sortie US sur Warlock.","en":"UK chart entry, no. 12; US release on Warlock."},{"date":"1990 / 1995","fr":"« Voodoo Ray Americas » (Automanikk, 1990) puis « Voodoo Rage » (Black Secret Technology, 1995).","en":"\"Voodoo Ray Americas\" (Automanikk, 1990), then \"Voodoo Rage\" (Black Secret Technology, 1995)."}],"credits":[{"k":"auteur","v":"Gerald Simpson","k_en":"Writer","v_en":"Gerald Simpson"},{"k":"production","v":"Gerald Simpson, Chapter","k_en":"Production","v_en":"Gerald Simpson, Chapter"},{"k":"ingénieur","v":"Lee Monteverde","k_en":"Engineer","v_en":"Lee Monteverde"},{"k":"studio","v":"Moonraker Studios, Manchester","k_en":"Studio","v_en":"Moonraker Studios, Manchester"},{"k":"label","v":"Rham! (UK) ; Warlock (US)","k_en":"Label","v_en":"Rham! (UK); Warlock (US)"}],"book_refs":[{"source":"adventures-wonderland","where":"Chapitres Manchester / acid house 1988 (Garratt)","where_en":"Manchester / acid house 1988 chapters (Garratt)"},{"source":"hacienda-hook","where":"1988 : l'explosion acid à l'Haçienda","where_en":"1988: the acid explosion at the Haçienda"}],"references":["https://en.wikipedia.org/wiki/Voodoo_Ray","https://en.wikipedia.org/wiki/A_Guy_Called_Gerald","https://en.wikipedia.org/wiki/The_Dance_Years"],"verify":["Anecdote du titre (à retrouver dans l'entretien DJhistory cité par Wikipedia)","Date de sortie exacte en novembre 1988"],"pilot":true},{"id":"dont-make-me-wait","title":"Don't Make Me Wait","artist":"Peech Boys","year":1982,"label":"West End Records","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-1","bpm":108,"camelot_key":"3A","energy":5,"gear":["tr-808"],"construction":"Des claps de boîte à rythmes noyés dans l'écho, une basse ronde et la voix de Bernard Fowler qui supplie. Le mix est pensé comme du dub : les éléments disparaissent et reviennent, l'espace fait partie de la musique.","producer_origins":"Larry Levan coproduit avec Michael de Benedictus. Levan pense le studio comme une extension de sa cabine : il mixe pour le système son du Paradise Garage, pas pour la radio.","club_sociology":"Le Paradise Garage, au 84 King Street (1977-1987), fonctionne sur adhésion, sans alcool, et ouvre jusqu'au dimanche matin. Le son de Richard Long et les sets marathon de Levan en font un lieu de culte : on y parle de « Saturday Mass ».","queer_ballroom_axis":"Le Garage est l'un des espaces fondateurs de la sociabilité gay noire et latino de New York. L'épidémie de sida y frappe de plein fouet ; Levan meurt en 1992. Le « garage » est avant tout une archive de cette communauté.","archive_ref":{"source":"you-better-work","note":"Analyse ethnographique de la piste new-yorkaise et du DJ comme officiant.","note_en":"An ethnography of the New York dancefloor and of the DJ as officiant."},"why_this_record":"Il fait entendre la « garage » avant la house : une esthétique du dub, de l'espace et de la ferveur qui irrigue tout ce qui suit.","tags":["roots","queer","gospel","dub","us"],"further_reading":["disco-files","hot-stuff","how-music-works","love-saves-the-day","turn-the-beat-around"],"spotify":{"id":"7mXVDv3vFhJzfFaMT2AAay","version":"MAW Main (remaster 2016)"},"youtube":["aLZdv0BrSZE","dZIgWY2HHjQ","v2Q2F-1toiI"],"construction_en":"Drum-machine claps drowned in echo, a round bassline and Bernard Fowler's pleading vocal. The mix is conceived as dub: elements drop out and return, and space becomes part of the music.","producer_origins_en":"Larry Levan co-produced with Michael de Benedictus. Levan treated the studio as an extension of his booth: he mixed for the Paradise Garage sound system, not for radio.","club_sociology_en":"The Paradise Garage at 84 King Street (1977–1987) was members-only, served no alcohol and ran until Sunday morning. Richard Long's sound and Levan's marathon sets made it a place of worship, people called it \"Saturday Mass\".","queer_ballroom_axis_en":"The Garage was one of the founding spaces of Black and Latino gay social life in New York. The AIDS epidemic hit it head-on; Levan died in 1992. \"Garage\" is first and foremost an archive of that community.","why_this_record_en":"It lets you hear garage before house: an aesthetic of dub, space and fervour that runs through everything that follows.","verified":false},{"id":"ha-dance","title":"The Ha Dance","artist":"Masters At Work","year":1991,"label":"Cutting Records","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-2","bpm":122,"camelot_key":"4A","energy":8,"gear":["sp-1200","mpc60"],"construction":"Un « ha! » samplé dans la scène du train du film « Trading Places » (1983), une cymbale crash et une rythmique nerveuse. Le beat est conçu comme une partition de mouvements : chaque « ha » appelle une pose, chaque crash un dip.","producer_origins":"Louie Vega (Bronx, famille portoricaine de la salsa) et Kenny « Dope » Gonzalez (Brooklyn, beatmaker hip-hop). Leur rencontre fusionne la culture du sampler hip-hop avec l'héritage latin et garage de New York.","club_sociology":"Né dans l'écosystème des clubs et des radios new-yorkaises du début des années 90, au moment où la house se professionnalise autour de remixeurs stars.","queer_ballroom_axis":"C'est le morceau ballroom par excellence : le crash sur le quatrième temps devient le signal du « dip » du vogue femme. Le « ha » vient d'une scène de Trading Places qui comporte du blackface et des insultes : la ballroom noire et latina, queer et trans, en a fait un détournement, réédité et remixé sans fin depuis plus de trente ans.","archive_ref":{"source":"paris-is-burning","note":"Le contexte ballroom (houses, catégories, vogue) que ce beat va structurer.","note_en":"The ballroom context (houses, categories, vogue) this beat would come to structure."},"why_this_record":"C'est le pont direct entre la house new-yorkaise et la ballroom. Un instrumental devenu chorégraphie collective.","tags":["ballroom","queer","sampler","us"],"further_reading":["beat-scene-sound","soul-underground","do-you-remember-house"],"spotify":{"id":"4x1E99Fe36e06M5YbLBgMC"},"youtube":["9WVxEdtOj48","_URFoqkwWLY","HOe2y9_4xx8"],"construction_en":"A \"ha!\" sampled from the train scene of the film Trading Places (1983), a crash cymbal and a nervy rhythm. The beat works as a movement score: every \"ha\" calls for a pose, every crash for a dip.","producer_origins_en":"Louie Vega (Bronx, from a Puerto Rican salsa family) and Kenny \"Dope\" Gonzalez (Brooklyn, hip-hop beatmaker). Their partnership fused hip-hop sampler culture with New York's Latin and garage heritage.","club_sociology_en":"Born in the early-90s ecosystem of New York clubs and radio, just as house was professionalising around star remixers.","queer_ballroom_axis_en":"The ballroom track par excellence: the crash on the fourth beat became the cue for vogue femme's dip. The \"ha\" comes from a Trading Places scene that includes blackface and slurs: Black and Latina, queer and trans ballroom turned it around, reissuing and remixing it endlessly for more than thirty years.","why_this_record_en":"The direct bridge between New York house and ballroom: an instrumental that became collective choreography.","verified":false,"story":"Little Louie Vega et Kenny « Dope » Gonzalez publient « The Ha Dance » en 1991 sur Cutting Records ; il paraît d'abord en face B du 12 pouces « Blood Vibes ». Dope tire le « ha » de la scène du train de Trading Places (1983, Eddie Murphy et Dan Aykroyd) et, d'après sa conférence à la Red Bull Music Academy en 2012, voulait en faire quelque chose de plus dur. Le crash métallique sur le quatrième temps devient le signal du « dip » du vogue femme, style qui émerge au même moment. Le disque passe d'abord dans les clubs (Sound Factory) puis devient la base sonore des balls. Vjuan produit en 2000 le premier remix pensé pour le ballroom ; MikeQ estime avoir réalisé environ 400 titres qui samplent le « ha ».","story_en":"Little Louie Vega and Kenny \"Dope\" Gonzalez released \"The Ha Dance\" in 1991 on Cutting Records; it first appeared as the B-side of the \"Blood Vibes\" 12-inch. Dope lifted the \"ha\" from the train scene in Trading Places (1983, Eddie Murphy and Dan Aykroyd) and, according to his 2012 Red Bull Music Academy lecture, wanted to turn it into something harder. The metallic crash on the fourth beat became the cue for the vogue femme \"dip\", a style emerging at the same time. The record played first in clubs (Sound Factory) and then became the sonic foundation of ballroom. Vjuan made the first remix designed for ballroom in 2000; MikeQ estimates he has produced about 400 tracks sampling the \"ha\".","timeline":[{"date":"1983","fr":"Sortie de Trading Places (source du « ha »).","en":"Trading Places released (source of the \"ha\")."},{"date":"1990","fr":"Sortie de Paris Is Burning.","en":"Paris Is Burning released."},{"date":"1991","fr":"Sortie de « The Ha Dance » (Cutting), face B de « Blood Vibes ».","en":"\"The Ha Dance\" released (Cutting), B-side of \"Blood Vibes\"."},{"date":"2000","fr":"Premier remix ballroom par Vjuan (« The Allure Ha »).","en":"First ballroom remix by Vjuan (\"The Allure Ha\")."},{"date":"2012","fr":"Kenny Dope explique son choix de sample à la RBMA.","en":"Kenny Dope explains his sample choice at RBMA."}],"credits":[{"k":"auteurs","v":"Louie Vega, Kenny Gonzalez","k_en":"Writers","v_en":"Louie Vega, Kenny Gonzalez"},{"k":"label","v":"Cutting Records","k_en":"Label","v_en":"Cutting Records"},{"k":"sample","v":"Trading Places (1983), scène du train","k_en":"Sample","v_en":"Trading Places (1983), train scene"},{"k":"versions","v":"Ken/Lou Mixx, Pumpin' Dubb","k_en":"Versions","v_en":"Ken/Lou Mixx, Pumpin' Dubb"}],"book_refs":[{"source":"paris-is-burning","where":"Film (1990), scènes de bal et de vogue ; le disque lui est postérieur de quelques mois","where_en":"Film (1990), ball and vogue scenes; the record postdates it by months"},{"source":"do-you-remember-house","where":"Chapitres sur la scène queer noire de Chicago et ses liens avec New York (Salkind)","where_en":"Chapters on Chicago's Black queer scene and its New York ties (Salkind)"}],"references":["https://daily.bandcamp.com/scene-report/ballroom-vogue-kiki-music","https://pitchfork.com/features/lists-and-guides/the-best-house-tracks-of-the-90s/","https://daily.redbullmusicacademy.com/2019/02/key-tracks-ha-dance/","https://daily.redbullmusicacademy.com/2012/02/vogue-ballroom-vivian-host/","https://www.vulture.com/2018/07/20-tracks-that-defined-the-sound-of-ballroom.html"],"verify":["Titre exact de la face A du 12 pouces (« Blood Vibes »)"],"pilot":true},{"id":"yo-yo-get-funky","title":"Yo Yo Get Funky!","artist":"Fast Eddie","year":1988,"label":"DJ International","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"hip-house","era":"era-1","bpm":123,"camelot_key":"11A","energy":8,"gear":["tr-808"],"construction":"Un kick house à quatre temps, des stabs de cuivres samplés et un flow rap qui exhorte la piste. Le MC remplace la diva, l'injonction remplace la supplique.","producer_origins":"Fast Eddie Smith, DJ de la Hot Mix 5 de WBMX, vient de la radio et du mix. Le hip-house est une tentative de faire dialoguer les deux cultures noires dominantes de Chicago.","club_sociology":"Fin des années 80, les labels de Chicago (DJ International, Trax) cherchent un second souffle commercial. Le hip-house est un format crossover destiné aux charts et aux clubs hétéros.","queer_ballroom_axis":"Le hip-house s'appuie sur la masculinité du rap pour élargir l'audience de la house au-delà de ses publics queer. On peut y lire une tentative de « dé-queeriser » le son de Chicago, même si la frontière reste poreuse.","archive_ref":{"source":"history-of-house","note":"Querelles de paternité du hip-house (Fast Eddie, Tyree Cooper, Jungle Brothers).","note_en":"Who invented hip-house? (Fast Eddie, Tyree Cooper, Jungle Brothers)."},"why_this_record":"C'est un document précieux sur la manière dont la house a négocié son identité face au hip-hop.","tags":["crossover","us","rap"],"further_reading":["energy-never-dies","soul-underground"],"spotify":{"id":"6VOensh57XWBQHZhOnvbuT","version":"Club Mix"},"youtube":["KMHJxUC1iMI","7v7UiDd7wBA","idwn9fp5SHQ"],"construction_en":"A four-to-the-floor house kick, sampled horn stabs and a rap flow that exhorts the floor. The MC replaces the diva; command replaces supplication.","producer_origins_en":"Fast Eddie Smith, a DJ in WBMX's Hot Mix 5, came from radio and mixing. Hip-house was an attempt to put Chicago's two dominant Black musics in dialogue.","club_sociology_en":"In the late 80s Chicago labels (DJ International, Trax) were looking for a second commercial wind. Hip-house was a crossover format aimed at the charts and straight clubs.","queer_ballroom_axis_en":"Hip-house leaned on rap's masculinity to widen house's audience beyond its queer crowds. You can read it as an attempt to \"de-queer\" the Chicago sound, even if the border stayed porous.","why_this_record_en":"A precious document of how house negotiated its identity in the face of hip-hop.","verified":false},{"id":"ill-house-you","title":"I'll House You","artist":"Jungle Brothers","year":1988,"label":"Warlock Records","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"hip-house","era":"era-1","bpm":120,"camelot_key":"2A","energy":7,"gear":["sp-1200"],"construction":"Le groupe rappe sur l'instrumental de « Can You Party » de Royal House, produit par Todd Terry. C'est un collage sampler typique de Terry : des boucles brutes et du kick, sans ornement.","producer_origins":"Les Jungle Brothers, membres du collectif Native Tongues, ont une approche afrocentrée et ludique du rap. Todd Terry, venu du hip-hop, applique la logique du sampler à la house.","club_sociology":"Le morceau passe dans les clubs house comme sur les radios rap new-yorkaises, preuve que les deux scènes partageaient les mêmes quartiers et les mêmes DJs avant que l'industrie ne les sépare.","queer_ballroom_axis":"Venus du hip-hop « conscient », les Native Tongues se montrent plus ouverts que le mainstream rap de l'époque. Le morceau reste toutefois adressé à un public hétéro et marque l'entrée du rap dans les clubs.","archive_ref":{"source":"last-night-dj","note":"Sur Todd Terry et la culture du sampler dans la house new-yorkaise.","note_en":"On Todd Terry and sampler culture in New York house."},"why_this_record":"C'est la version new-yorkaise du hip-house, plus sampler que machine.","tags":["crossover","sampler","us","rap"],"spotify":{"id":"51GEHfWZuwIg5XHY50XSyS"},"youtube":["R7_1Xb5Uc8U","AFGhQSiGHWM","xvJwiXXgVm8"],"further_reading":["soul-underground"],"construction_en":"The group raps over the instrumental of Royal House's \"Can You Party\", produced by Todd Terry. A typical Terry sampler collage: raw loops and kick, no ornament.","producer_origins_en":"The Jungle Brothers, members of the Native Tongues collective, took an Afrocentric, playful approach to rap. Todd Terry, who came up through hip-hop, applied sampler logic to house.","club_sociology_en":"The track played in house clubs and on New York rap radio alike, proof that both scenes shared the same neighbourhoods and DJs before the industry pulled them apart.","queer_ballroom_axis_en":"Coming from \"conscious\" hip-hop, the Native Tongues were more open than the rap mainstream of the time. Still, the record speaks to a straight audience and marks rap's entry into the clubs.","why_this_record_en":"New York's take on hip-house: more sampler than drum machine.","verified":false},{"id":"strings-of-life","title":"Strings of Life","artist":"Rhythim Is Rhythim","year":1987,"label":"Transmat","city":"Detroit","country":"USA","continent":"Amérique du Nord","genre":"detroit","era":"era-1","bpm":125,"camelot_key":"4B","energy":9,"gear":["tr-909","Ensoniq Mirage (sampler)"],"construction":"Des cordes et un piano samplés (le piano vient d'une improvisation de Michael James) sont découpés en riffs syncopés sur une 909 sans répit. L'absence de ligne de basse classique crée une tension permanente, comme un orchestre en chute libre.","producer_origins":"Derrick May, l'un des « Belleville Three » avec Juan Atkins et Kevin Saunderson, vient d'une banlieue noire de Detroit. Il pense la machine comme une sortie de la ville post-industrielle et un moyen de se projeter dans le futur.","club_sociology":"Detroit s'effondre après le départ de l'industrie automobile. Le Music Institute (1988-1989) et les fêtes de lycéens de la classe moyenne noire forment la scène. En Europe, le disque devient un hymne rave.","queer_ballroom_axis":"Le récit techno a souvent effacé ses dettes queer, en particulier envers Ken Collier, DJ gay noir de Detroit dont les sets ont formé toute une génération. La « futurité » de Detroit repose aussi sur cette mémoire.","archive_ref":{"source":"modulations","note":"Segment Detroit et Belleville Three.","note_en":"Detroit and the Belleville Three segment."},"why_this_record":"Le pont entre la house et la techno : une émotion orchestrale portée par la machine.","tags":["roots","futurism","us"],"further_reading":["electrochoc","energy-flash","musique-house-bidder","techno-rebels","underground-massive"],"spotify":{"id":"0vBg4JYmBIyNgk1R3R0cX6"},"youtube":["vGFw2qeUp0s","rFQZndywOR4","8e5aWNpU_b8"],"construction_en":"Sampled strings and piano (the piano comes from an improvisation by Michael James) cut into syncopated riffs over a relentless 909. The absence of a conventional bassline creates constant tension, like an orchestra in free fall.","producer_origins_en":"Derrick May, one of the \"Belleville Three\" with Juan Atkins and Kevin Saunderson, came from a Black suburb of Detroit. He saw the machine as a way out of the post-industrial city and a means of projecting himself into the future.","club_sociology_en":"Detroit collapsed as the car industry left. The Music Institute (1988–1989) and parties thrown by Black middle-class high-schoolers formed the scene. In Europe, the record became a rave anthem.","queer_ballroom_axis_en":"The techno narrative has often erased its queer debts, especially to Ken Collier, the Black gay Detroit DJ whose sets schooled a whole generation. Detroit's \"futurity\" also rests on that memory.","why_this_record_en":"The bridge between house and techno: orchestral emotion carried by the machine.","verified":false},{"id":"big-fun","title":"Big Fun","artist":"Inner City","year":1988,"label":"KMS / 10 Records","city":"Detroit","country":"USA","continent":"Amérique du Nord","genre":"detroit","era":"era-1","bpm":120,"camelot_key":"9B","energy":7,"gear":["tr-909","dx100"],"construction":"Une basse synthétique joyeuse, des nappes en accords et la voix de Paris Grey, chanteuse de Chicago. Saunderson construit une techno pop et lumineuse, pensée pour l'euphorie collective.","producer_origins":"Kevin Saunderson, ancien sportif de Belleville, a la fibre la plus commerciale des trois. Le duo avec Paris Grey réunit officiellement Detroit et Chicago.","club_sociology":"Le single entre dans le top 10 britannique et fait de Detroit une marque en Europe. Le Royaume-Uni devient le premier marché de musiques nées dans des villes noires américaines, qui y restent pourtant marginales.","queer_ballroom_axis":"La voix de Paris Grey prolonge la tradition des divas de club, figure centrale de l'imaginaire queer de la house, au cœur d'un projet « techno ».","archive_ref":{"source":"join-the-future","note":"Réception britannique de Detroit et naissance de la bleep/bass music.","note_en":"Britain's reception of Detroit and the birth of bleep/bass music."},"why_this_record":"Il montre que Detroit a aussi produit de la pop. L'export britannique a façonné l'histoire de ces genres.","tags":["crossover","uk-link","us","diva"],"further_reading":["techno-rebels"],"spotify":{"id":"2flF4TMjmhIWKWEdSNK3U8","version":"version remixée (Yamagucci)"},"youtube":["Gr-zG-IXDyo","ZZpC30e4ehg","WpMD4j04RUM"],"construction_en":"A joyful synth bass, chordal pads and the voice of Paris Grey, a Chicago singer. Saunderson builds a bright, pop techno designed for collective euphoria.","producer_origins_en":"Kevin Saunderson, a former Belleville athlete, had the most commercial instincts of the three. The duo with Paris Grey formally united Detroit and Chicago.","club_sociology_en":"The single made the UK top 10 and turned Detroit into a brand in Europe. Britain became the first big market for music born in Black American cities that remained marginal at home.","queer_ballroom_axis_en":"Paris Grey's voice extends the tradition of the club diva, a central figure of house's queer imagination, at the heart of a \"techno\" project.","why_this_record_en":"It shows Detroit also made pop, and that British export shaped the history of these genres.","verified":false},{"id":"can-you-feel-it","title":"Can You Feel It","artist":"Mr. Fingers","year":1986,"label":"Trax Records","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"deep","era":"era-1","bpm":120,"camelot_key":"6A","energy":4,"gear":["tr-909","Roland Juno-60"],"construction":"Des nappes chaudes, une ligne de basse ronde et presque aucune variation pendant sept minutes. La profondeur naît de la retenue. Des versions ultérieures superposent le sermon de Chuck Roberts (« In the beginning there was Jack »).","producer_origins":"Larry Heard est un ancien batteur de jazz-fusion. Il compose en harmoniste, avec des accords de septième et de neuvième, ce qui donne à la house un vocabulaire jazz et soul.","club_sociology":"La deep house offre un contrepoint à la frénésie jack : une piste où l'on peut fermer les yeux. Elle inaugure l'idée que la house peut aussi s'écouter chez soi.","queer_ballroom_axis":"Le texte de Chuck Roberts, souvent mixé dessus, fait de la house un espace d'appartenance universelle (« house is a feeling »). C'est une théologie de l'inclusion née dans les clubs gays noirs.","archive_ref":{"source":"history-of-house","note":"Larry Heard et la naissance de la deep house.","note_en":"Larry Heard and the birth of deep house."},"why_this_record":"C'est la matrice de toute la deep house : l'émotion par l'accord, pas par l'effet.","tags":["roots","jazz","deep","us"],"further_reading":["do-you-remember-house","musique-house-bidder","real-story-saunders","soul-underground"],"spotify":{"id":"4mNwbj8hTUjbyZSHdQVIuL"},"youtube":["1N9Wnqz8Rh8","tFuujExs03A","DrxPFBEr5Bo"],"construction_en":"Warm pads, a round bassline and almost no variation for seven minutes. Depth comes from restraint. Later versions lay Chuck Roberts's sermon on top (\"In the beginning there was Jack\").","producer_origins_en":"Larry Heard is a former jazz-fusion drummer. He composes as a harmonist, with seventh and ninth chords, giving house a jazz and soul vocabulary.","club_sociology_en":"Deep house offered a counterpoint to jack frenzy: a floor where you could close your eyes. It also introduced the idea that house could be listened to at home.","queer_ballroom_axis_en":"Chuck Roberts's text, often mixed over it, makes house a space of universal belonging (\"house is a feeling\"): a theology of inclusion born in Black gay clubs.","why_this_record_en":"The template for all deep house: emotion through chords, not effects.","verified":false},{"id":"frozen-calderone","title":"Frozen (Victor Calderone Extended Club Mix)","artist":"Madonna · Victor Calderone","year":1998,"label":"Maverick / Warner Bros.","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"tribal-nyc","era":"era-2","bpm":128,"camelot_key":"5A","energy":7,"gear":["tr-909","Percussions & toms samplés"],"construction":"Calderone transforme une ballade sombre en cathédrale tribale : toms en cascade, percussions roulantes, longues montées et breaks dramatiques. La voix de Madonna devient une incantation au-dessus d'un tapis de batterie.","producer_origins":"Victor Calderone, DJ new-yorkais d'origine italienne, s'impose à la fin des années 90 comme le remixeur des divas pop pour les clubs gays. Son tribal est pensé pour les grands systèmes son et les pistes de plusieurs milliers de danseurs.","club_sociology":"Fin des années 90 à Manhattan : soirées géantes (Twilo, Roxy, Sound Factory) et circuit parties. Le remix club devient une industrie où les majors financent des versions de dix minutes pour un public qu'elles savent prescripteur.","queer_ballroom_axis":"Le tribal new-yorkais est la bande-son des circuit parties gays post-sida. La musique accompagne une culture du corps, de la nuit et de la survie collective. Madonna, qui avait emprunté le vogue à la ballroom en 1990, boucle ici la boucle.","archive_ref":{"source":"you-better-work","note":"Les clubs new-yorkais des années 90 et la piste comme espace de communauté gay.","note_en":"1990s New York clubs and the dancefloor as gay community space."},"why_this_record":"C'est le tribal à son apogée : le moment où la pop mondiale s'est mise au service de la piste queer new-yorkaise.","tags":["queer","diva","tribal","us","ballroom"],"further_reading":["beat-scene-sound","underground-massive"],"spotify":{"id":"1Nv7PAfgcKwzqOqb0hKEYP","version":"Extended Club Mix Edit (remaster 2022)"},"youtube":["tgVPmOdjmbs","2k2AV548nC8","FNdnnN4dj78"],"construction_en":"Calderone turns a dark ballad into a tribal cathedral: cascading toms, rolling percussion, long builds and dramatic breakdowns. Madonna's voice becomes an incantation above a carpet of drums.","producer_origins_en":"Victor Calderone, an Italian-American New York DJ, emerged in the late 90s as the go-to remixer of pop divas for gay clubs. His tribal sound was built for big rigs and floors of several thousand dancers.","club_sociology_en":"Late-90s Manhattan: giant parties (Twilo, Roxy, Sound Factory) and circuit parties. The club remix became an industry, with majors funding ten-minute versions for an audience they knew to be a tastemaker.","queer_ballroom_axis_en":"New York tribal was the soundtrack of post-AIDS gay circuit parties, a culture of the body, the night and collective survival. Madonna, who had borrowed vogue from ballroom in 1990, closes the loop here.","why_this_record_en":"Tribal at its peak: the moment global pop put itself at the service of the New York queer dancefloor.","gear_en":["tr-909","Sampled percussion & toms"],"verified":false},{"id":"music-is-the-answer","title":"Music Is the Answer","artist":"Danny Tenaglia & Celeda","year":1998,"label":"Twisted America","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"tribal-nyc","era":"era-2","bpm":127,"camelot_key":"10A","energy":8,"gear":["tr-909","Percussions samplées"],"construction":"Une rythmique tribale sombre et hypnotique, une basse grondante et le spoken word de Celeda : « Music is the answer to your problems ». Le morceau se construit en tension continue, sans refrain.","producer_origins":"Danny Tenaglia, de Queens, a grandi en écoutant Larry Levan. Il hérite de la culture garage du marathon : ses sets dépassent souvent les dix heures.","club_sociology":"Les soirées « Be Yourself » de Tenaglia au club Vinyl et ses nuits au Twilo forment l'une des dernières grandes communautés du clubbing new-yorkais, avant que la politique de « qualité de vie » de la mairie Giuliani ne ferme les clubs un à un.","queer_ballroom_axis":"Celeda (Victoria Sharpe), chanteuse et drag performer née à Chicago, porte le texte : sa voix transforme une piste tribale en sermon, ce qui place la drag au cœur même de la production.","archive_ref":{"source":"last-night-dj","note":"Héritage de Larry Levan chez les DJs new-yorkais des années 90.","note_en":"Larry Levan's legacy among 1990s New York DJs."},"why_this_record":"Ici, la drag est le texte même du morceau, pas un décor.","tags":["queer","tribal","drag","us"],"further_reading":["beat-scene-sound"],"spotify":{"id":"4n8YdXETqQ3NvWs5XNpvar","version":"Original Extended 12\" Mix"},"youtube":["GPqD_bpA72U","por1m1gg1Rk","ZkPhIIESof8"],"construction_en":"A dark, hypnotic tribal groove, a growling bass and Celeda's spoken word: \"Music is the answer to your problems\". The track builds as continuous tension, with no chorus.","producer_origins_en":"Danny Tenaglia, from Queens, grew up listening to Larry Levan. He inherited garage's marathon culture: his sets often ran past ten hours.","club_sociology_en":"Tenaglia's \"Be Yourself\" parties at Vinyl and his nights at Twilo formed one of the last great communities of New York clubbing, before the Giuliani administration's \"quality of life\" policy closed clubs one by one.","queer_ballroom_axis_en":"Celeda (Victoria Sharpe), a Chicago-born singer and drag performer, carries the text: her voice turns a tribal track into a sermon, placing drag at the very heart of the production.","why_this_record_en":"Here drag is not décor, it is the text of the track itself.","gear_en":["tr-909","Sampled percussion"],"verified":false},{"id":"sueno-latino","title":"Sueño Latino","artist":"Sueño Latino","year":1989,"label":"DFC","city":"Ibiza / Italie","country":"Italie","continent":"Europe","genre":"balearic","era":"era-1","bpm":117,"camelot_key":"9A","energy":3,"gear":["Samples de « E2-E4 » (Manuel Göttsching)","Delay"],"construction":"Le morceau reprend la boucle de guitare de « E2-E4 » de Manuel Göttsching (1984), y pose une voix féminine soupirante et des sons de vagues. Le tempo est lent et la texture aquatique : un lever de soleil mis en musique.","producer_origins":"Production de studio italienne de la scène « Italo House » : les producteurs italiens recyclent la musique cosmique allemande et la mélodie méditerranéenne pour le marché européen.","club_sociology":"L'éclectisme balearic vient d'Alfredo Fiorito à l'Amnesia (Ibiza), qui mélange pop, house et rock indé en plein air. En 1987, Paul Oakenfold, Danny Rampling et leurs amis y vivent une révélation qu'ils rapportent à Londres (Shoom, Spectrum).","queer_ballroom_axis":"Ibiza est depuis les années 70 une enclave de liberté sexuelle sous et après le franquisme. Le balearic hérite de cette atmosphère d'hédonisme mixte que le tourisme de masse va ensuite standardiser.","archive_ref":{"source":"adventures-wonderland","note":"Ibiza 1987 et la naissance de la scène acid/balearic londonienne.","note_en":"Ibiza 1987 and the birth of London's acid/balearic scene."},"why_this_record":"Il montre que la house peut être un paysage plutôt qu'une injonction.","tags":["europe","chill","sunrise"],"further_reading":["carl-cox-oh-yes","hypnotised","rave-on","second-summer"],"spotify":{"id":"5rMkhxZVe5rpUBwGuTb29Y","version":"Paradise Version"},"youtube":["DXhqDeTSEl4","LI7OsqXuB-k"],"construction_en":"The track borrows the guitar loop of Manuel Göttsching's \"E2-E4\" (1984) and lays a sighing female voice and ocean sounds over it. Slow tempo, aquatic texture: a sunrise set to music.","producer_origins_en":"An Italian studio production from the Italo house scene: Italian producers recycled German cosmic music and Mediterranean melody for the European market.","club_sociology_en":"Balearic eclecticism came from Alfredo Fiorito at Amnesia (Ibiza), who mixed pop, house and indie rock under the open sky. In 1987 Paul Oakenfold, Danny Rampling and friends had a revelation there that they brought back to London (Shoom, Spectrum).","queer_ballroom_axis_en":"Since the 1970s Ibiza had been an enclave of sexual freedom under and after Franco. Balearic inherited that atmosphere of mixed hedonism, which mass tourism would later standardise.","why_this_record_en":"It shows house can be a landscape rather than a command.","city_en":"Ibiza / Italy","country_en":"Italy","gear_en":["Samples of \"E2-E4\" (Manuel Göttsching)","Delay"],"verified":false},{"id":"da-funk","title":"Da Funk","artist":"Daft Punk","year":1995,"label":"Soma Quality Recordings","city":"Paris","country":"France","continent":"Europe","genre":"french-touch","era":"era-2","bpm":111,"camelot_key":"6A","energy":6,"gear":["tb-303","tr-909"],"construction":"Un riff de synthé basse saturé et filtré, à mi-chemin du funk et de l'acid, sur une 909 compressée. Le tempo lent et la distorsion donnent un groove lourd, presque hip-hop, plus proche du G-funk que de Chicago.","producer_origins":"Thomas Bangalter et Guy-Manuel de Homem-Christo viennent du rock indé (Darlin'). Ils découvrent la house par les raves et les disques de Chicago, qu'ils citent dans « Teachers ». C'est une approche de fans érudits, pas de DJs de club.","club_sociology":"Le disque sort d'abord sur Soma, le label de Slam à Glasgow, avant que Virgin ne signe le duo. La French Touch se construit sur l'export : elle est reconnue à Londres avant de l'être à Paris.","queer_ballroom_axis":"La scène parisienne se cristallise aux soirées Respect au Queen, club gay des Champs-Élysées. Leur tournée s'appellera « Respect Is Burning », en hommage direct à « Paris Is Burning ». Les codes queer sont cités comme une référence culturelle plus que vécus.","archive_ref":{"source":"modulations","note":"La house européenne des années 90 et la culture de l'export.","note_en":"1990s European house and the culture of export."},"why_this_record":"C'est la preuve que la house se transforme en voyageant : ralentie, saturée, pop.","tags":["europe","filter","machine"],"further_reading":["brickwork-arches","electrochoc","musique-house-bidder"],"spotify":{"id":"0MyY4WcN7DIfbSmp5yej5z"},"youtube":["PwILkY9gRrc","9xxH_qL5dls","mmi60Bd4jSs"],"construction_en":"A distorted, filtered synth-bass riff halfway between funk and acid, over a compressed 909. The slow tempo and distortion give a heavy, almost hip-hop groove, closer to G-funk than to Chicago.","producer_origins_en":"Thomas Bangalter and Guy-Manuel de Homem-Christo came from indie rock (Darlin'). They discovered house through raves and Chicago records, which they name-check in \"Teachers\". A scholarly fans' approach, not that of club DJs.","club_sociology_en":"The record first came out on Soma, Slam's Glasgow label, before Virgin signed the duo. The French Touch was built on export: it was recognised in London before Paris.","queer_ballroom_axis_en":"The Paris scene crystallised at the Respect nights at Queen, a gay club on the Champs-Élysées. Their tour was called \"Respect Is Burning\", a direct nod to Paris Is Burning. Queer codes were cited as cultural reference more than lived.","why_this_record_en":"Proof that house changes as it travels: slowed down, saturated, pop.","verified":false},{"id":"music-sounds-better","title":"Music Sounds Better With You","artist":"Stardust","year":1998,"label":"Roulé","city":"Paris","country":"France","continent":"Europe","genre":"french-touch","era":"era-2","bpm":124,"camelot_key":"11B","energy":7,"gear":["Sampler","Filtre passe-bas automatisé"],"construction":"Une boucle de « Fate » de Chaka Khan (1981) passe dans un filtre qui s'ouvre et se referme sur un kick à quatre temps, avec la voix de Benjamin Diamond par-dessus. Tout le morceau tient sur une respiration du filtre.","producer_origins":"Thomas Bangalter, Alan Braxe et Benjamin Diamond n'ont sorti qu'un seul disque sous ce nom. Ce projet de studio presque accidentel devient un tube mondial.","club_sociology":"La filter house fait de la disco un matériau : on extrait quelques secondes d'un disque des années 70-80 et on les répète. Le crate digging devient une esthétique et une économie, avec ses questions de droits.","queer_ballroom_axis":"Cette disco samplée est l'archive sonore des pistes noires et gays des années 70. La filter house la recontextualise pour un public plus large et souvent hétéro. On peut y entendre un hommage ou une forme d'appropriation.","archive_ref":{"source":"last-night-dj","note":"La disco comme matrice et le statut du sample.","note_en":"Disco as matrix and the status of the sample."},"why_this_record":"C'est l'archétype du filtre français : un seul geste technique, répété jusqu'à l'extase.","tags":["europe","filter","disco","sample"],"further_reading":["decade-house-bleakman","hot-stuff","musique-house-bidder"],"spotify":{"id":"303ccTay2FiDTZ9fZ2AdBt"},"youtube":["FQlAEiCb8m0","Hf244LCkkLc","JfFBstmwdg0"],"construction_en":"A loop from Chaka Khan's \"Fate\" (1981) runs through a filter that opens and closes over a four-to-the-floor kick, with Benjamin Diamond's vocal on top. The whole track rests on the filter's breathing.","producer_origins_en":"Thomas Bangalter, Alan Braxe and Benjamin Diamond released only one record under this name. An almost accidental studio project became a global hit.","club_sociology_en":"Filter house turns disco into raw material: lift a few seconds from a 70s or 80s record and loop them. Crate digging becomes both an aesthetic and an economy, with all its rights issues.","queer_ballroom_axis_en":"This sampled disco is the sound archive of 1970s Black and gay dancefloors. Filter house recontextualises it for a wider, often straight audience: homage or appropriation, depending on how you hear it.","why_this_record_en":"The archetype of the French filter: one technical gesture, repeated to ecstasy.","gear_en":["Sampler","Automated low-pass filter"],"verified":false},{"id":"right-on","title":"Right On, Right On","artist":"Silicone Soul","year":2000,"label":"Soma Quality Recordings","city":"Glasgow","country":"Royaume-Uni","continent":"Europe","genre":"tech-house","era":"era-2","bpm":124,"camelot_key":"8A","energy":6,"gear":["tr-909","Sampler"],"construction":"Une basse roulante, des percussions sèches et un sample vocal funk répété en boucle. On y trouve la rigueur de la techno et la chaleur de la house, sans mélodie envahissante.","producer_origins":"Graeme Reedie et Craig Morrison viennent de la scène écossaise du Sub Club et de Soma : une culture de la discothèque de quartier très ancrée.","club_sociology":"La tech house naît dans les warehouses et after-hours londoniens à partir de 1994 (soirées Wiggle de Terry Francis, Nathan Coles et Eddie Richards, Heart & Soul, club The End de Mr C et Layo). C'est une musique de nuit longue, pensée pour les DJs.","queer_ballroom_axis":"La tech house britannique se développe dans des scènes majoritairement blanches et hétéros. Elle illustre la manière dont la house s'est détachée de son origine queer noire en se « technicisant ».","archive_ref":{"source":"brickwork-arches","note":"Glasgow, Soma et la scène des Arches.","note_en":"Glasgow, Soma and the Arches scene."},"why_this_record":"C'est la jonction réussie entre Detroit et Chicago, vue depuis Glasgow.","tags":["uk","europe","warehouse"],"further_reading":["decade-house-bleakman","full-on"],"spotify":{"id":"2sHmb1cLhLY0m9qyNnZkGO"},"youtube":["xJbxi9RWRj0","jbxKWtxXvdc","NshM87okEv0"],"construction_en":"A rolling bassline, dry percussion and a looped funk vocal sample. The rigour of techno meets the warmth of house, with no intrusive melody.","producer_origins_en":"Graeme Reedie and Craig Morrison came out of Glasgow's Sub Club and Soma scene: a deeply rooted local club culture.","club_sociology_en":"Tech house was born in London's warehouses and after-hours from 1994 onwards (the Wiggle parties of Terry Francis, Nathan Coles and Eddie Richards, Heart & Soul, Mr C and Layo's club The End). Long-night music, made for DJs.","queer_ballroom_axis_en":"British tech house grew up in mostly white, straight scenes. It illustrates how house drifted away from its Black queer origins as it became more \"technical\".","why_this_record_en":"A successful junction of Detroit and Chicago, seen from Glasgow.","country_en":"United Kingdom","verified":false},{"id":"losing-it","title":"Losing It","artist":"FISHER","year":2018,"label":"Catch & Release","city":"Gold Coast","country":"Australie","continent":"Océanie","genre":"tech-house","era":"era-3b","bpm":125,"camelot_key":"1A","energy":9,"gear":["DAW","Basse roulante (sound design)"],"construction":"Une basse roulante minimale, une voix qui monte en boucle (« losing it ») puis un drop. La structure est pensée pour l'explosion collective et pour les vidéos virales de festival.","producer_origins":"Paul Fisher, ancien surfeur professionnel australien, a une approche décomplexée et humoristique : le DJ-showman des réseaux sociaux.","club_sociology":"Nommé au Grammy de la meilleure production dance, le morceau marque le moment où la tech house remplace l'EDM comme son dominant des festivals et des mégaclubs d'Ibiza.","queer_ballroom_axis":"L'antithèse du Warehouse : la tech house de festival est souvent décrite comme « bro », masculine et hétéro. On mesure ici la distance parcourue par la house depuis ses origines.","archive_ref":{"source":"underground-massive","note":"La dance music devenue industrie de festival.","note_en":"Dance music turned festival industry."},"why_this_record":"On le choisit pour ce qu'il révèle : la house devenue industrie de masse globale.","tags":["festival","mainstream"],"youtube":["u31thuMehjM","oUbpmjOgmmU","xYLH8lHFs6A"],"construction_en":"A minimal rolling bassline, a looped vocal that rises (\"losing it\"), then a drop. The structure is built for collective explosion and viral festival clips.","producer_origins_en":"Paul Fisher, a former Australian pro surfer, has a carefree, humorous approach: the social-media DJ-showman.","club_sociology_en":"Nominated for the Grammy for Best Dance Recording, the track marks the moment tech house replaced EDM as the dominant sound of festivals and Ibiza's megaclubs.","queer_ballroom_axis_en":"The antithesis of the Warehouse: festival tech house is often described as \"bro\", masculine and straight. It measures how far house has travelled from its origins.","why_this_record_en":"Chosen for what it reveals: house turned into a global mass industry.","country_en":"Australia","gear_en":["DAW","Rolling bass (sound design)"],"verified":false},{"id":"re-rewind","title":"Re-Rewind (The Crowd Say Bo Selecta)","artist":"Artful Dodger feat. Craig David","year":1999,"label":"Relentless Records","city":"Southampton","country":"Royaume-Uni","continent":"Europe","genre":"ukg","era":"era-2","bpm":132,"camelot_key":"2A","energy":8,"gear":["Sampler","Time-stretch vocal"],"construction":"Un 2-step : le kick saute des temps, la caisse claire est syncopée, les charlestons sont shufflés et les basses rebondissent. La voix R&B de Craig David danse sur le rythme. Le tempo élevé n'empêche pas un groove souple.","producer_origins":"Mark Hill et Pete Devereux (Artful Dodger) viennent de la scène garage du sud de l'Angleterre. Ils héritent du speed garage et des voix découpées de Todd Edwards (New Jersey).","club_sociology":"L'UK garage est la musique des Sunday sessions, des radios pirates et des MCs, avec un dress code chic (Moschino, champagne). C'est une culture noire britannique de la classe ouvrière, d'où sortiront le grime et le dubstep, et que la police ciblera via le formulaire 696.","queer_ballroom_axis":"L'UK garage hérite du garage new-yorkais, des voix gospel et de la soul, sans en reprendre les espaces queer. La mémoire queer y est musicale plus que sociale.","archive_ref":{"source":"join-the-future","note":"Lignée des musiques bass britanniques (bleep → garage → dubstep).","note_en":"The lineage of British bass music (bleep → garage → dubstep)."},"why_this_record":"On sent le décalage dès qu'on l'enchaîne avec un morceau de Chicago à 121 BPM : plus rapide, mais plus souple.","tags":["uk","twostep","black-british"],"further_reading":["decade-house-bleakman","energy-flash","full-on","state-of-bass"],"spotify":{"id":"4xXRTJXGxt7UBAVVOTV6ZN","version":"Radio Edit"},"youtube":["M0wv_cQv8As"],"construction_en":"Two-step: the kick skips beats, the snare is syncopated, the hi-hats shuffle and the bass bounces. Craig David's R&B vocal dances over the rhythm. The high tempo never stops the groove from feeling loose.","producer_origins_en":"Mark Hill and Pete Devereux (Artful Dodger) came from the southern English garage scene. They inherited speed garage and the chopped vocals of Todd Edwards (New Jersey).","club_sociology_en":"UK garage was the music of Sunday sessions, pirate radio and MCs, with a sharp dress code (Moschino, champagne). A Black British working-class culture that would give birth to grime and dubstep, and that police would target through Form 696.","queer_ballroom_axis_en":"UK garage inherited New York garage, gospel vocals and soul, without taking on its queer spaces. Its queer memory is musical rather than social.","why_this_record_en":"You feel the shift as soon as you mix it after a 121 BPM Chicago track: faster, yet looser.","country_en":"United Kingdom","gear_en":["Sampler","Time-stretched vocal"],"verified":false},{"id":"superman","title":"Superman","artist":"Black Coffee feat. Bucie","year":2009,"label":"Soulistic Music","city":"Durban / Johannesburg","country":"Afrique du Sud","continent":"Afrique","genre":"afro","era":"era-3a","bpm":120,"camelot_key":"3A","energy":5,"gear":["DAW","Percussions"],"construction":"Des percussions boisées et polyrythmiques, des nappes mélancoliques et la voix de Bucie. Le groove est retenu, presque deep, mais la rythmique respire autrement que le four-on-the-floor américain.","producer_origins":"Nathi « Black Coffee » Maphumulo a grandi à Umlazi (Durban). En février 1990, une voiture fonce dans la foule qui célèbre à Mthatha la libération de Mandela : il en garde une lésion du plexus brachial et un bras gauche en grande partie paralysé. Il apprend à mixer d'une main, avec une approche très économe.","club_sociology":"L'Afrique du Sud est l'un des plus grands marchés house au monde depuis les années 90, via le kwaito et la radio. La house y est une musique populaire de masse, pas une niche, comme le montre ce morceau qui a été le succès de toute une génération.","queer_ballroom_axis":"La house sud-africaine compte aussi ses scènes queer, notamment à Johannesburg. Leur visibilité publique reste moindre que celle des stars, mais elles revendiquent leur part de la généalogie.","archive_ref":{"source":"rave-on","note":"Les scènes électroniques hors d'Europe et des États-Unis, dont l'Afrique du Sud.","note_en":"Electronic scenes beyond Europe and the US, including South Africa."},"why_this_record":"Il montre la house revenue en Afrique et réécrite, pas importée.","tags":["africa","deep","diaspora"],"youtube":["ulN3QkamJUU","W_72j4UqOSM","w6-tR3PKCHA"],"construction_en":"Woody, polyrhythmic percussion, melancholic pads and Bucie's voice. The groove is restrained, almost deep, but the rhythm breathes differently from American four-to-the-floor.","producer_origins_en":"Nathi \"Black Coffee\" Maphumulo grew up in Umlazi (Durban). In February 1990 a car ploughed into a crowd celebrating Mandela's release in Mthatha: he was left with a brachial plexus injury and a largely paralysed left arm. He learned to mix one-handed, with a very economical approach.","club_sociology_en":"South Africa has been one of the world's biggest house markets since the 90s, through kwaito and radio. House there is mass popular music, not a niche, as this track, the hit of a whole generation, shows.","queer_ballroom_axis_en":"South African house also has its queer scenes, notably in Johannesburg. Their public visibility is lower than the stars', but they claim their share of the lineage.","why_this_record_en":"It shows house returning to Africa and being rewritten, not imported.","country_en":"South Africa","gear_en":["DAW","Percussion"],"verified":false},{"id":"township-funk","title":"Township Funk","artist":"DJ Mujava","year":2008,"label":"Warp Records","city":"Pretoria (Atteridgeville)","country":"Afrique du Sud","continent":"Afrique","genre":"afro","era":"era-3a","bpm":126,"camelot_key":"12A","energy":8,"gear":["FL Studio","Synthé lead « marimba »"],"construction":"Un riff de synthé obsédant en boucle, des percussions de township et des ruptures qui jouent sur l'attente. Le style est brut, presque minimaliste, produit sur logiciel.","producer_origins":"Elvis Maswanganyi, d'Atteridgeville, produit sur FL Studio comme beaucoup de jeunes du township. Le morceau circule d'abord localement avant d'être repéré et signé par Warp, le label britannique.","club_sociology":"Le titre illustre les circuits de la « bass music » mondiale des années 2000 : des blogs et des DJs occidentaux découvrent des scènes africaines qui existaient déjà, ce qui pose des questions de rémunération et de crédit.","queer_ballroom_axis":"Pas d'ancrage queer explicite. L'intérêt est ailleurs : il montre comment la house des townships se réapproprie la machine (le logiciel) comme Chicago l'avait fait avec la 808.","archive_ref":{"source":"join-the-future","note":"Logique de l'export des musiques bass et du filtre britannique.","note_en":"How bass music is exported and filtered through Britain."},"why_this_record":"C'est le chaînon entre kwaito, house de township et amapiano.","tags":["africa","software","diaspora"],"spotify":{"id":"0EN8KF256ZGQOctxVVwA20"},"youtube":["_l1bjtjzZFo","xpPeAafarOM","HRIw9RPbJK0"],"construction_en":"A hypnotic looped synth riff, township percussion and breaks that play with anticipation. Raw, almost minimalist, made in software.","producer_origins_en":"Elvis Maswanganyi, from Atteridgeville, produced on FL Studio like many township kids. The track circulated locally before being spotted and signed by the British label Warp.","club_sociology_en":"It illustrates the circuits of 2000s global \"bass music\": Western blogs and DJs \"discovering\" African scenes that already existed, raising questions of payment and credit.","queer_ballroom_axis_en":"No explicit queer anchoring. The interest lies elsewhere: it shows township house reclaiming the machine (software) the way Chicago did with the 808.","why_this_record_en":"The missing link between kwaito, township house and amapiano.","country_en":"South Africa","gear_en":["FL Studio","\"Marimba\" lead synth"],"verified":false},{"id":"winona","title":"Winona","artist":"DJ Boring","year":2016,"label":"E-Beamz","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"lofi","era":"era-3b","bpm":118,"camelot_key":"4A","energy":4,"gear":["Saturation tape / bitcrusher","Sampler"],"construction":"Des accords deep house saturés comme une vieille VHS, un kick étouffé, un sample vocal d'interview de Winona Ryder. La dégradation sonore est volontaire : elle fabrique de la nostalgie.","producer_origins":"DJ Boring (Tristan Hallis), producteur né en Australie et installé à Londres, appartient à une génération de producteurs de chambre qui apprend la house sur YouTube et fabrique, avec des plug-ins, l'imperfection que leurs aînés subissaient avec le matériel.","club_sociology":"La lo-fi house se diffuse en 2016-2017 par des chaînes YouTube et l'algorithme plus que par les clubs. Elle a d'abord été écoutée au casque, avant d'être jouée sur une piste.","queer_ballroom_axis":"L'esthétique de la mémoire sans le contexte : la lo-fi house cite la deep house de Chicago comme une texture, sans en hériter les communautés.","archive_ref":{"source":"how-music-works","note":"Le son façonné par son lieu d'écoute : casque, YouTube, chambre.","note_en":"Sound shaped by where it is heard: headphones, YouTube, the bedroom."},"why_this_record":"La house devient sa propre archive et s'écoute comme un souvenir qu'on n'a pas vécu.","tags":["internet","nostalgia","europe"],"spotify":{"id":"4rvnBqTmx66LlCJZLbLAOY"},"youtube":["ar9qA3WJInk","PyPs2pgogQk","kuggtL-bQzc"],"construction_en":"Deep house chords saturated like an old VHS tape, a muffled kick and a vocal sample from a Winona Ryder interview. The degradation is deliberate: it manufactures nostalgia.","producer_origins_en":"DJ Boring (Tristan Hallis), an Australian-born, London-based producer, belongs to a generation of bedroom producers who learned house on YouTube and use plug-ins to fake the imperfections their elders endured with hardware.","club_sociology_en":"Lo-fi house spread in 2016–2017 through YouTube channels and the algorithm more than through clubs. It was first heard on headphones, only later on a dancefloor.","queer_ballroom_axis_en":"The aesthetics of memory without the context: lo-fi house quotes Chicago deep house as a texture, without inheriting its communities.","why_this_record_en":"House becomes its own archive, heard like a memory you never lived.","city_en":"London","country_en":"United Kingdom","gear_en":["Tape saturation / bitcrusher","Sampler"],"verified":false},{"id":"talk-to-me","title":"Talk to Me You'll Understand","artist":"Ross From Friends","year":2015,"label":"Lobster Theremin","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"lofi","era":"era-3b","bpm":121,"camelot_key":"7B","energy":5,"gear":["Sampler","Saturation"],"construction":"Un sample vocal pitché et en boucle, des accords baignés de souffle et un groove légèrement décalé. Les imperfections de timing et de son sont des choix de production.","producer_origins":"Felix Clary Weatherall choisit un pseudonyme qui est une blague sur la série « Friends ». La dérision fait partie de l'esthétique, à l'opposé du sérieux techno.","club_sociology":"Lobster Theremin, label londonien indépendant, structure cette scène entre vinyle limité et viralité numérique. Le disque devient un objet de collection pour une génération post-streaming.","queer_ballroom_axis":"Comme une grande partie de la lo-fi house, le morceau hérite d'une texture sans revendiquer de lien avec les scènes queer d'origine.","archive_ref":{"source":"how-music-works","note":"Le son pensé pour l'écoute domestique et les plateformes.","note_en":"Sound designed for home listening and platforms."},"why_this_record":"Il fait le lien entre la culture du sample et l'ironie internet.","tags":["internet","nostalgia","europe","sample"],"spotify":{"id":"4Z4i631BesV0P6LTvfLAdL"},"youtube":["s93kHQe8Upc","8tKKNV5sXUs","TDcYUcX5aHk"],"construction_en":"A pitched, looped vocal sample, chords bathed in hiss and a slightly off-grid groove. The timing and sonic imperfections are production choices.","producer_origins_en":"Felix Clary Weatherall picked an alias that jokes about the TV show Friends. Self-mockery is part of the aesthetic, the opposite of techno seriousness.","club_sociology_en":"Lobster Theremin, an independent London label, structured this scene between limited vinyl and digital virality. The record became a collector's item for a post-streaming generation.","queer_ballroom_axis_en":"Like much lo-fi house, the track inherits a texture without claiming any link to the original queer scenes.","why_this_record_en":"It connects sample culture with internet irony.","city_en":"London","country_en":"United Kingdom","verified":false,"verify":["Année de sortie : 2015 (site) ou 2016 (Resident Advisor)"]},{"id":"ke-star","title":"Ke Star","artist":"Focalistic & Vigro Deep","year":2020,"label":"Pitori Music","city":"Pretoria","country":"Afrique du Sud","continent":"Afrique","genre":"amapiano","era":"era-3c","bpm":113,"camelot_key":"5A","energy":6,"gear":["log-drum","FL Studio","Shakers"],"construction":"Le log drum, une basse percussive au glissando caractéristique, joue la mélodie. Les shakers sont continus, le kick discret et le tempo lent (environ 113 BPM). Le flow en sepitori de Focalistic flotte au-dessus. Le groove est horizontal, il se balance plus qu'il ne pousse.","producer_origins":"Vigro Deep, producteur adolescent de Mabopane, appartient à la génération qui a façonné l'amapiano sur FL Studio dans les townships du Gauteng. Focalistic rappe en argot de Pretoria.","club_sociology":"L'amapiano naît au milieu des années 2010 dans les fêtes de quartier, les taxis et les tavernes du Gauteng. Le confinement de 2020 le propulse via les réseaux sociaux et les lives. Le remix avec Davido l'ouvre au marché panafricain.","queer_ballroom_axis":"Les scènes queer de Johannesburg ont adopté l'amapiano. Le genre, porté par les townships, réouvre la question de qui a la main sur la house : la jeunesse noire, cette fois en Afrique.","archive_ref":{"source":"rave-on","note":"La géographie mondiale des musiques électroniques au XXIe siècle.","note_en":"The global geography of electronic music in the 21st century."},"why_this_record":"À 113 BPM, on sent immédiatement que la house peut ralentir sans perdre son pouvoir de faire danser.","tags":["africa","diaspora","log-drum"],"further_reading":["how-music-works"],"spotify":{"id":"7uhOIYLVWbBZ6ISBoyiMrl"},"youtube":["a9_da2P5JjQ","oQKKCXXRcKE","_WcA7WpI-9c"],"construction_en":"The log drum, a percussive bass with a signature glide, carries the melody. Constant shakers, a discreet kick and a slow tempo (around 113 BPM), with Focalistic's Sepitori flow floating on top. The groove is horizontal: it sways more than it pushes.","producer_origins_en":"Vigro Deep, a teenage producer from Mabopane, belongs to the generation that shaped amapiano on FL Studio in Gauteng's townships. Focalistic raps in Pretoria slang.","club_sociology_en":"Amapiano emerged in the mid-2010s at neighbourhood parties, in taxis and taverns across Gauteng. The 2020 lockdown propelled it through social media and livestreams; the Davido remix opened the pan-African market.","queer_ballroom_axis_en":"Johannesburg's queer scenes have embraced amapiano. Carried by the townships, the genre reopens the question of who holds the keys to house: Black youth, this time in Africa.","why_this_record_en":"At 113 BPM you instantly feel that house can slow down without losing its power to move a floor.","country_en":"South Africa","verified":false},{"id":"water-tyla","title":"Water","artist":"Tyla","year":2023,"label":"FAX Records / Epic","city":"Johannesburg","country":"Afrique du Sud","continent":"Afrique","genre":"amapiano","era":"era-3c","bpm":117,"camelot_key":"10A","energy":6,"gear":["log-drum","DAW"],"construction":"Une production pop R&B construite sur les codes amapiano : log drum, shakers, espaces aérés. Le refrain est calibré pour une chorégraphie virale.","producer_origins":"Tyla, chanteuse de Johannesburg, porte l'amapiano sur la scène pop mondiale avec une équipe de production mixte, sud-africaine et internationale.","club_sociology":"Le morceau remporte le premier Grammy de la meilleure performance musicale africaine (2024). Viralisé par une danse sur TikTok, il montre que l'amapiano est passé du township au marché mondial en moins de dix ans.","queer_ballroom_axis":"La chorégraphie virale prolonge, consciemment ou non, la logique ballroom du « beat qui appelle le mouvement » : la danse devient le véritable vecteur de diffusion.","archive_ref":{"source":"rave-on","note":"Circulation mondiale des scènes électroniques locales.","note_en":"Global circulation of local electronic scenes."},"why_this_record":"C'est le point d'arrivée provisoire : la house sud-africaine devenue pop mondiale.","tags":["africa","pop","log-drum","diaspora"],"spotify":{"id":"5aIVCx5tnk0ntmdiinnYvw"},"youtube":["XoiOOiuH8iI","g5va6Ue0GM4","88a7rr8KXcE"],"construction_en":"A pop-R&B production built on amapiano codes: log drum, shakers, airy space. The hook is engineered for a viral dance routine.","producer_origins_en":"Tyla, a Johannesburg singer, carries amapiano onto the global pop stage with a mixed South African and international production team.","club_sociology_en":"The track won the first Grammy for Best African Music Performance (2024). Spread by a TikTok dance, it shows amapiano travelling from township to global market in under ten years.","queer_ballroom_axis_en":"The viral choreography extends, knowingly or not, ballroom's logic of \"the beat that calls the move\": dance becomes the real vehicle of circulation.","why_this_record_en":"The provisional end of the line: South African house turned global pop.","country_en":"South Africa","verified":false},{"id":"love-is-the-message","title":"Love Is the Message","artist":"MFSB","year":1973,"label":"Philadelphia International","city":"Philadelphie","country":"USA","continent":"Amérique du Nord","genre":"disco","era":"era-1","bpm":118,"camelot_key":"4A","energy":6,"gear":["Section rythmique live","Cordes & cuivres (orchestre)"],"construction":"Un orchestre de studio de Philadelphie, avec cordes soyeuses, cuivres et un groove de basse et batterie qui tient tout seul. Le long pont instrumental devient la matière première des DJs, qui le bouclent à deux platines pendant des minutes.","producer_origins":"MFSB (« Mother Father Sister Brother ») regroupe les musiciens de studio de Gamble & Huff, la machine à tubes de la soul de Philadelphie. Ce sont des professionnels du studio, pas des musiciens de club.","club_sociology":"C'est un hymne du Loft de David Mancuso et des premières discothèques underground new-yorkaises. Vince Aletti le suit semaine après semaine dans sa colonne de Record World, où il note ce que jouent les DJs avant que l'industrie ne s'en aperçoive.","queer_ballroom_axis":"C'est l'un des disques-matrices de la piste gay noire et latino du New York des années 70. Le message d'amour universel devient littéralement la promesse du dancefloor.","archive_ref":{"source":"love-saves-the-day","note":"Le Loft de David Mancuso et la culture des DJs new-yorkais des années 70.","note_en":"David Mancuso's Loft and 1970s New York DJ culture."},"why_this_record":"Toute la house descend de ce break : la boucle instrumentale comme lieu de transe collective.","tags":["roots","disco","queer","us"],"further_reading":["disco-files","hot-stuff","last-night-dj","love-saves-the-day","turn-the-beat-around"],"spotify":{"id":"1GbBfA4tgiCpNXHIEogoJP"},"youtube":["M3wpG6Rw-tE","AbsZC257JP8","7b1umcmfaXY"],"construction_en":"A Philadelphia studio orchestra: silky strings, horns and a bass-and-drums groove that stands on its own. The long instrumental break became DJs' raw material, looped on two decks for minutes on end.","producer_origins_en":"MFSB (\"Mother Father Sister Brother\") gathered Gamble & Huff's session players, the hit machine of Philadelphia soul: studio pros, not club musicians.","club_sociology_en":"An anthem of David Mancuso's Loft and New York's first underground discotheques. Vince Aletti tracked it week after week in his Record World column, logging what DJs played before the industry noticed.","queer_ballroom_axis_en":"One of the founding records of 1970s New York's Black and Latino gay dancefloor. Its message of universal love literally becomes the dancefloor's promise.","why_this_record_en":"All of house descends from this break: the instrumental loop as a site of collective trance.","city_en":"Philadelphia","gear_en":["Live rhythm section","Strings & horns (orchestra)"],"verified":false,"story":"Écrit par Kenneth Gamble et Leon Huff et enregistré en 1973 au Sigma Sound de Philadelphie par MFSB, l'orchestre maison de Philadelphia International, avec les Three Degrees. Il figure sur l'album du même nom (1973), dont « TSOP » (thème de Soul Train) devient numéro 1 américain en 1974. Le single sort le 7 juin 1974 : n°85 au Billboard, n°42 R&B, 6'37 sur l'album, 11'30 en 12 pouces. C'est un favori des DJs depuis sa sortie. Au début des années 80, il est un hymne des balls new-yorkais : le morceau du vogue « old school », avant « The Ha Dance ».","story_en":"Written by Kenneth Gamble and Leon Huff and recorded in 1973 at Sigma Sound in Philadelphia by MFSB, Philadelphia International's house band, with The Three Degrees. It appears on the album of the same name (1973), whose \"TSOP\" (the Soul Train theme) hit US no. 1 in 1974. The single came out on 7 June 1974: no. 85 on Billboard, no. 42 R&B, 6:37 on the album, 11:30 on the 12-inch. It has been a DJ favourite since its release. By the early 1980s it was an anthem at New York balls: the \"old school\" vogue track, before \"The Ha Dance\".","timeline":[{"date":"1970-02-14","fr":"Premier « Love Saves the Day » au Loft de David Mancuso.","en":"David Mancuso's first \"Love Saves the Day\" party at the Loft."},{"date":"1973","fr":"Enregistrement et album Love Is the Message (Sigma Sound).","en":"Recording and album Love Is the Message (Sigma Sound)."},{"date":"1974-02","fr":"« TSOP » devient n°1 au Billboard Hot 100.","en":"\"TSOP\" reaches no. 1 on the Billboard Hot 100."},{"date":"1974-06-07","fr":"Sortie du single « Love Is the Message ».","en":"\"Love Is the Message\" single released."},{"date":"début 1980s","fr":"Hymne des balls new-yorkais (Red Bull Music Academy).","en":"Anthem at New York balls (Red Bull Music Academy)."}],"credits":[{"k":"auteurs","v":"Kenneth Gamble, Leon Huff","k_en":"Writers","v_en":"Kenneth Gamble, Leon Huff"},{"k":"interprètes","v":"MFSB, The Three Degrees","k_en":"Performers","v_en":"MFSB, The Three Degrees"},{"k":"studio","v":"Sigma Sound Studios, Philadelphie","k_en":"Studio","v_en":"Sigma Sound Studios, Philadelphia"},{"k":"label","v":"Philadelphia International","k_en":"Label","v_en":"Philadelphia International"},{"k":"versions","v":"2'39 (single), 6'37 (album), 11'30 (12\")","k_en":"Versions","v_en":"2'39 (single), 6'37 (album), 11'30 (12\")"}],"book_refs":[{"source":"disco-files","where":"Colonnes de Vince Aletti (Record World) : mentions du disque dans les listes de DJs (1973-1975)","where_en":"Vince Aletti's Record World columns: mentions in DJ charts (1973–75)"},{"source":"love-saves-the-day","where":"Chapitres sur le Loft et la naissance du disco (Lawrence)","where_en":"Chapters on the Loft and disco's birth (Lawrence)"},{"source":"hot-stuff","where":"Chapitre sur les débuts du disco et la scène noire","where_en":"Chapter on early disco and the Black scene"}],"references":["https://en.wikipedia.org/wiki/Love_Is_the_Message_(MFSB_song)","https://en.wikipedia.org/wiki/Love_Is_the_Message_(MFSB_album)","https://en.wikipedia.org/wiki/MFSB","https://en.wikipedia.org/wiki/Sigma_Sound_Studios","https://en.wikipedia.org/wiki/TSOP_(The_Sound_of_Philadelphia)","https://daily.redbullmusicacademy.com/2019/02/key-tracks-ha-dance/","https://www.vulture.com/2018/07/20-tracks-that-defined-the-sound-of-ballroom.html"],"verify":["Lien Aletti : à retrouver dans les colonnes datées (Disco Files)","BPM et clé : à mesurer sur la version retenue (single, album ou 12\")"],"pilot":true},{"id":"i-feel-love","title":"I Feel Love","artist":"Donna Summer","year":1977,"label":"Casablanca / GTO","city":"Munich","country":"Allemagne","continent":"Europe","genre":"disco","era":"era-1","bpm":128,"camelot_key":"5A","energy":8,"gear":["moog-modular","Séquenceur analogique"],"construction":"Tout est synthétique sauf le kick et la voix : une basse séquencée en arpège au Moog modulaire, des doubles croches qui pulsent, la voix de Summer qui flotte en apesanteur. C'est la première fois que la machine porte entièrement une chanson disco.","producer_origins":"Giorgio Moroder et Pete Bellotte travaillent depuis Munich, loin de la soul américaine. Ils imaginent un disque « du futur » pour clore un album-concept qui traverse les décennies.","club_sociology":"Le disque fait le lien entre la disco orchestrale et la musique électronique de danse. On raconte que Brian Eno y a entendu « le son du futur » des clubs.","queer_ballroom_axis":"Donna Summer est l'icône absolue des pistes gays de la fin des années 70. « I Feel Love » prépare le hi-NRG, la disco électronique des clubs gays des années 80, et via Patrick Cowley tout un pan de la musique queer.","archive_ref":{"source":"hot-stuff","note":"Disco, technologie et culture gay américaine.","note_en":"Disco, technology and American gay culture."},"why_this_record":"C'est le chaînon direct entre la disco et la house machinique.","tags":["roots","disco","machine","queer","diva"],"further_reading":["last-night-dj","turn-the-beat-around"],"youtube":["yEbaeLv-aOo","9ZqqvrWCs3Q","ufGLhImwnYg"],"construction_en":"Everything is synthetic except the kick and the vocal: an arpeggiated bass sequenced on a Moog modular, pulsing sixteenth notes, Summer's voice floating weightless. For the first time a machine carries an entire disco song.","producer_origins_en":"Giorgio Moroder and Pete Bellotte worked out of Munich, far from American soul. They imagined a record \"from the future\" to close a concept album travelling through the decades.","club_sociology_en":"The record links orchestral disco and electronic dance music. Brian Eno reportedly heard in it \"the sound of the future\" of clubbing.","queer_ballroom_axis_en":"Donna Summer was the absolute icon of late-70s gay dancefloors. \"I Feel Love\" paved the way for hi-NRG, the electronic disco of 1980s gay clubs, and, via Patrick Cowley, for a whole strand of queer music.","why_this_record_en":"The direct link between disco and machine house.","country_en":"Germany","gear_en":["moog-modular","Analogue sequencer"],"verified":false},{"id":"mighty-real","title":"You Make Me Feel (Mighty Real)","artist":"Sylvester","year":1978,"label":"Fantasy","city":"San Francisco","country":"USA","continent":"Amérique du Nord","genre":"disco","era":"era-1","bpm":130,"camelot_key":"10B","energy":9,"gear":["Synthétiseurs (Patrick Cowley)","Section rythmique"],"construction":"Un kick insistant, des synthés stridents ajoutés par Patrick Cowley et la voix de fausset gospel de Sylvester au sommet. L'énergie est hi-NRG avant la lettre : plus rapide, plus électronique, plus extatique que la disco new-yorkaise.","producer_origins":"Sylvester James, formé à l'église pentecôtiste de Los Angeles, débarque à San Francisco dans la scène drag et contre-culturelle (les Cockettes). Patrick Cowley, ingénieur et synthésiste, devient son alter ego technique.","club_sociology":"Le morceau domine les clubs de Castro et devient un tube international. San Francisco construit un circuit gay de la disco électronique, parallèle à New York.","queer_ballroom_axis":"Sylvester, ouvertement gay, noir et gender-nonconforming, est la figure la plus explicitement queer de la disco. Cowley meurt du sida en 1982, Sylvester en 1988 : leur histoire est aussi celle de l'épidémie.","archive_ref":{"source":"hot-stuff","note":"Le chapitre sur Sylvester et la disco gay de San Francisco.","note_en":"The chapter on Sylvester and San Francisco gay disco."},"why_this_record":"« Mighty Real » est un manifeste : la ferveur queer comme moteur de la piste.","tags":["roots","disco","queer","drag","gospel","us"],"further_reading":["last-night-dj","love-saves-the-day","turn-the-beat-around"],"spotify":{"id":"6wVKjL4QV4Q23eQWkJNYyQ"},"youtube":["c3vtOEiO6TY","gD6cPE2BHic","VgFk-tLr6eo"],"construction_en":"A relentless kick, piercing synths added by Patrick Cowley and Sylvester's gospel falsetto on top. Hi-NRG before the name: faster, more electronic and more ecstatic than New York disco.","producer_origins_en":"Sylvester James, raised in a Los Angeles Pentecostal church, landed in San Francisco's drag and countercultural scene (the Cockettes). Patrick Cowley, engineer and synthesist, became his technical alter ego.","club_sociology_en":"The track ruled the Castro's clubs and became an international hit. San Francisco built its own gay circuit of electronic disco, parallel to New York.","queer_ballroom_axis_en":"Openly gay, Black and gender-nonconforming, Sylvester is disco's most explicitly queer figure. Cowley died of AIDS in 1982, Sylvester in 1988: their story is also the epidemic's.","why_this_record_en":"\"Mighty Real\" is a manifesto: queer fervour as the engine of the dancefloor.","gear_en":["Synthesizers (Patrick Cowley)","Rhythm section"],"verified":false},{"id":"love-sensation","title":"Love Sensation","artist":"Loleatta Holloway","year":1980,"label":"Gold Mind / Salsoul","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"disco","era":"era-1","bpm":124,"camelot_key":"7A","energy":8,"gear":["Orchestre disco","Section rythmique live"],"construction":"Une production disco de Dan Hartman au service d'une voix gospel monumentale. Les cris de Loleatta Holloway deviendront l'un des samples vocaux les plus utilisés de la house.","producer_origins":"Holloway, chanteuse de gospel de Chicago, enregistre pour Salsoul, le label new-yorkais dont les mixes 12\" (Walter Gibbons, Tom Moulton) inventent le remix de club.","club_sociology":"En 1989, Black Box sample sa voix sans la créditer pour « Ride on Time », numéro 1 au Royaume-Uni. L'affaire devient un cas d'école des droits du sample et du sort réservé aux chanteuses noires.","queer_ballroom_axis":"C'est la diva gospel, figure centrale de l'imaginaire queer de la piste. Sa voix, découpée par d'autres, raconte aussi l'effacement des femmes noires dans la dance music.","archive_ref":{"source":"disco-files","note":"Salsoul et la culture du mix 12\".","note_en":"Salsoul and 12\" mix culture."},"why_this_record":"Le pont direct entre la disco de Salsoul et l'italo-house samplée.","tags":["disco","diva","gospel","sample","queer","us"],"further_reading":["last-night-dj","love-saves-the-day","turn-the-beat-around"],"spotify":{"id":"3su8VunluUL4Oj7UTTEREt"},"youtube":["1h6Su3t5Lqs","Kr5zQZq33-c","v-S5jD2fP2Y"],"construction_en":"A Dan Hartman disco production in service of a monumental gospel voice. Loleatta Holloway's wails would become one of the most sampled vocals in house.","producer_origins_en":"Holloway, a Chicago gospel singer, recorded for Salsoul, the New York label whose 12\" mixes (Walter Gibbons, Tom Moulton) invented the club remix.","club_sociology_en":"In 1989 Black Box sampled her voice uncredited for \"Ride on Time\", a UK number one. The affair became a textbook case of sample rights and of how Black women singers were treated.","queer_ballroom_axis_en":"The gospel diva, a central figure of the dancefloor's queer imagination. Her voice, chopped up by others, also tells of the erasure of Black women in dance music.","why_this_record_en":"The direct bridge between Salsoul disco and sample-based Italo house.","gear_en":["Disco orchestra","Live rhythm section"],"verified":false},{"id":"your-love","title":"Your Love","artist":"Frankie Knuckles presents Jamie Principle","year":1987,"label":"Trax Records","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-1","bpm":120,"camelot_key":"1A","energy":6,"gear":["Synthétiseur (arpège)","Boîte à rythmes"],"construction":"Un arpège de synthé qui tourne sans fin, une basse minimale et la voix sensuelle, presque murmurée, de Jamie Principle. C'est un disque de nuit et de désir, l'opposé du jack frénétique.","producer_origins":"Jamie Principle compose chez lui une chanson d'amour électronique. Frankie Knuckles la joue d'abord en cassette au Power Plant pendant des années avant sa sortie officielle.","club_sociology":"La cassette exclusive, jouée seulement par un DJ, est un modèle de l'économie des clubs de Chicago : le DJ est le premier diffuseur, le disque vient après.","queer_ballroom_axis":"Knuckles, « parrain de la house », est un DJ gay noir venu du Bronx et de la Continental Baths. « Your Love » est l'une des chansons d'amour fondatrices de la house queer.","archive_ref":{"source":"do-you-remember-house","note":"Frankie Knuckles et les undergrounds queer of color de Chicago.","note_en":"Frankie Knuckles and Chicago's queer-of-color undergrounds."},"why_this_record":"On entend ici que la house de Chicago peut être tendre et sensuelle.","tags":["roots","queer","us"],"further_reading":["do-you-remember-house","energy-never-dies","last-night-dj","real-story-saunders"],"spotify":{"id":"0vryyKyxCFXT0gg670yNEw"},"youtube":["hPrGnh7QUDo","LOLE1YE_oFQ","rB8tFzTG3Xo"],"construction_en":"An endlessly cycling synth arpeggio, a minimal bassline and Jamie Principle's sensual, almost whispered vocal. A record of night and desire, the opposite of frantic jack.","producer_origins_en":"Jamie Principle wrote an electronic love song at home. Frankie Knuckles played it from a reel-to-reel tape at the Power Plant for years before its official release.","club_sociology_en":"The exclusive tape, played by one DJ only, is a model of Chicago club economics: the DJ is the first broadcaster, the record comes later.","queer_ballroom_axis_en":"Knuckles, the \"Godfather of House\", was a Black gay DJ from the Bronx and the Continental Baths. \"Your Love\" is one of the founding love songs of queer house.","why_this_record_en":"Proof that Chicago house could be tender and sensual.","gear_en":["Synthesizer (arpeggio)","Drum machine"],"verified":false},{"id":"love-cant-turn-around","title":"Love Can't Turn Around","artist":"Farley \"Jackmaster\" Funk feat. Darryl Pandy","year":1986,"label":"DJ International","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-1","bpm":122,"camelot_key":"11B","energy":8,"gear":["tr-808","Piano"],"construction":"Une ligne de basse rebondissante et des stabs de piano. Surtout, la voix d'opéra-gospel de Darryl Pandy, qui pousse la chanson jusqu'au cri.","producer_origins":"Farley Keith Williams est un DJ des Hot Mix 5 sur WBMX : la radio est sa scène. Le morceau reprend une idée d'Isaac Hayes, ce qui alimente les querelles de crédit typiques de Chicago.","club_sociology":"Il entre dans le top 10 britannique en 1986. C'est l'une des premières fois que la house de Chicago s'impose dans les charts européens, avant même l'explosion acid.","queer_ballroom_axis":"Lecture éditoriale, à sourcer : la voix flamboyante de Darryl Pandy prolonge la tradition des chanteurs gospel de la house. Sa place dans l'histoire queer du genre reste à documenter par des entretiens.","archive_ref":{"source":"real-story-saunders","note":"Les labels de Chicago (Trax, DJ International) et les querelles de crédit.","note_en":"Chicago labels (Trax, DJ International) and credit disputes."},"why_this_record":"Le premier « crossover » de la house vers l'Europe.","tags":["roots","crossover","queer","gospel","us"],"further_reading":["do-you-remember-house","energy-never-dies","history-of-house","soul-underground"],"spotify":{"id":"247Vl4QClTBN8lzSJRTSpK"},"youtube":["UzqhRicKCLM","LDtbXxemnPw","RB6puxjzU9k"],"construction_en":"A bouncing bassline and piano stabs. Above all, Darryl Pandy's operatic gospel voice, pushing the song all the way to a scream.","producer_origins_en":"Farley Keith Williams was a DJ in WBMX's Hot Mix 5: radio was his stage. The track reworks an Isaac Hayes idea, fuelling the credit disputes typical of Chicago.","club_sociology_en":"It made the UK top 10 in 1986, one of the first times Chicago house broke into the European charts, even before the acid explosion.","queer_ballroom_axis_en":"Editorial reading, to be sourced: Darryl Pandy's flamboyant voice extends house's tradition of gospel singers. His place in the genre's queer history still needs documenting through interviews.","why_this_record_en":"House's first crossover into Europe.","verified":false},{"id":"jack-your-body","title":"Jack Your Body","artist":"Steve \"Silk\" Hurley","year":1986,"label":"DJ International","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-1","bpm":123,"camelot_key":"8A","energy":8,"gear":["Boîte à rythmes","Sampler"],"construction":"Une basse martelée, un kick mécanique et une voix samplée et bégayée (« jack-jack-jack your body »). C'est le jack dans sa forme la plus pure : un ordre adressé au corps.","producer_origins":"Steve Hurley est DJ de radio et de club. Le morceau naît de bandes éditées pour ses sets avant d'être pressé.","club_sociology":"C'est le premier numéro 1 house au Royaume-Uni, en janvier 1987, presque sans paroles. L'Angleterre découvre que la house est un phénomène massif.","queer_ballroom_axis":"Le « jack » est une danse et une sexualité de la piste : un vocabulaire né des clubs gays noirs de Chicago que les charts britanniques importent sans le savoir.","archive_ref":{"source":"rave-on","note":"La house de Chicago comme langage mondial.","note_en":"Chicago house as a global language."},"why_this_record":"C'est le moment où le jack conquiert les charts.","tags":["roots","crossover","us"],"further_reading":["do-you-remember-house","history-of-house","second-summer","soul-underground"],"spotify":{"id":"10QGhgqQm0I2Y9maxrM7T6","version":"1986 Club Mix"},"youtube":["ZaHUK5GnDgE","tn0CnTOobl8","_eDf8IGSh0Q"],"construction_en":"A hammering bassline, a mechanical kick and a sampled, stuttering voice (\"jack-jack-jack your body\"). Jack in its purest form: an order addressed to the body.","producer_origins_en":"Steve Hurley was a radio and club DJ. The track grew out of tape edits made for his sets before it was pressed.","club_sociology_en":"The first house number one in the UK, in January 1987, with barely any lyrics. Britain discovered house was a mass phenomenon.","queer_ballroom_axis_en":"\"Jack\" is a dance and a sexuality of the dancefloor: a vocabulary born in Chicago's Black gay clubs that the British charts imported without knowing it.","why_this_record_en":"The moment jack conquered the charts.","gear_en":["Drum machine","Sampler"],"verified":false},{"id":"promised-land","title":"Promised Land","artist":"Joe Smooth","year":1987,"label":"DJ International","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-1","bpm":120,"camelot_key":"3B","energy":7,"gear":["Boîte à rythmes","Piano & orgue"],"construction":"Des accords de piano lumineux, une progression gospel et un texte d'espérance (« brothers, sisters, one day we will be free »). C'est la house comme chant de lutte pour les droits civiques.","producer_origins":"Joe Smooth est DJ et producteur de Chicago, formé à la soul et au gospel. Il écrit un hymne politique dans un genre réputé apolitique.","club_sociology":"Sorti en 1987 aux États-Unis, le disque ne paraît officiellement au Royaume-Uni qu'en février 1989, le jour même où The Style Council publie sa reprise. Sa circulation en import pendant l'été 1988, dans les soirées dont Wayne Anthony fait le récit dans Class of '88, reste à confirmer dans le livre.","queer_ballroom_axis":"La « terre promise » d'un collectif noir et queer devient l'utopie d'une jeunesse britannique blanche, un transfert de sens au cœur de l'histoire de la house.","archive_ref":{"source":"energy-never-dies","note":"L'afro-optimisme de Chicago : la house comme chant d'espérance noire.","note_en":"Chicago Afro-optimism: house as a hymn of Black hope."},"why_this_record":"Il montre que la house a toujours porté un message d'émancipation.","tags":["roots","gospel","piano","us","rave"],"further_reading":["adventures-wonderland","carl-cox-oh-yes","class-of-88","do-you-remember-house","electrochoc","rave-art","second-summer","soul-underground"],"spotify":{"id":"796T2ROxTNibXRjVhjSzCa"},"youtube":["BJyD_TPeJAI","QtTBMBcuweE","5T6wGShMow8"],"construction_en":"Luminous piano chords, a gospel progression and a lyric of hope (\"brothers, sisters, one day we will be free\"). House as a civil-rights hymn.","producer_origins_en":"Joe Smooth, a Chicago DJ and producer schooled in soul and gospel, wrote a political anthem in a genre reputed to be apolitical.","club_sociology_en":"Released in the US in 1987, the record only came out officially in the UK in February 1989, the same day The Style Council released their cover. Its circulation on import during summer 1988, at the parties Wayne Anthony describes in Class of '88, still needs confirming in the book.","queer_ballroom_axis_en":"The \"promised land\" of a Black and queer collective became the utopia of white British youth, a transfer of meaning at the heart of house history.","why_this_record_en":"It shows house has always carried a message of emancipation.","gear_en":["Drum machine","Piano & organ"],"verified":false,"story":"Joe Smooth (Joseph Welbon Jr.) est DJ au Smart Bar de Chicago de 1983 à 1985. Il dit avoir eu l'idée du morceau pendant une tournée européenne avec Farley « Jackmaster » Funk. Le disque sort sur DJ International en 1987, avec Anthony Thomas au chant et Don Connolly. Au Royaume-Uni, il sort officiellement en 1989 ; le jour même, The Style Council publie sa reprise (13 février 1989), qui atteint le n°27, tandis que l'original culmine à la 56e place. Juan Atkins remixe la reprise. Elle annonce l'album Modernism: A New Decade, que Polydor refusera de publier.","story_en":"Joe Smooth (Joseph Welbon Jr.) was a DJ at Chicago's Smart Bar from 1983 to 1985. He says the idea came during a European tour with Farley \"Jackmaster\" Funk. The record came out on DJ International in 1987, with Anthony Thomas on vocals and Don Connolly. In the UK it was officially released in 1989; the same day The Style Council put out their cover (13 February 1989), which reached no. 27 while the original peaked at 56. Juan Atkins remixed the cover. It previewed the album Modernism: A New Decade, which Polydor refused to release.","timeline":[{"date":"1983-1985","fr":"Smooth DJ au Smart Bar.","en":"Smooth DJs at Smart Bar."},{"date":"1987","fr":"Sortie américaine sur DJ International.","en":"US release on DJ International."},{"date":"1988","fr":"Album Promised Land.","en":"Album Promised Land."},{"date":"1989-02-13","fr":"Sortie britannique de l'original et de la reprise de The Style Council, le même jour.","en":"UK release of the original and The Style Council's cover on the same day."},{"date":"1989","fr":"Remix de la reprise par Juan Atkins.","en":"Juan Atkins remixes the cover."}],"credits":[{"k":"auteur/producteur","v":"Joe Smooth","k_en":"Writer/producer","v_en":"Joe Smooth"},{"k":"voix","v":"Anthony Thomas, Don Connolly","k_en":"Vocals","v_en":"Anthony Thomas, Don Connolly"},{"k":"label","v":"DJ International","k_en":"Label","v_en":"DJ International"},{"k":"reprise","v":"The Style Council (Polydor, 1989)","k_en":"Cover","v_en":"The Style Council (Polydor, 1989)"}],"book_refs":[{"source":"class-of-88","where":"Passages sur les soirées de 1988-1989 à Londres (Shoom, warehouses)","where_en":"Passages on 1988–89 London nights (Shoom, warehouses)"},{"source":"adventures-wonderland","where":"Arrivée de la house de Chicago au Royaume-Uni","where_en":"Arrival of Chicago house in the UK"}],"references":["https://en.wikipedia.org/wiki/Promised_Land_(Joe_Smooth_song)","https://en.wikipedia.org/wiki/Joe_Smooth","https://en.wikipedia.org/wiki/The_Style_Council","https://en.wikipedia.org/wiki/Juan_Atkins","https://en.wikipedia.org/wiki/DJ_International_Records"],"verify":["Passage de Class of '88 sur Promised Land","Date exacte de la sortie britannique de l'original"],"pilot":true},{"id":"french-kiss","title":"French Kiss","artist":"Lil Louis","year":1989,"label":"Diamond Records / FFRR","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-1","bpm":122,"camelot_key":"6A","energy":7,"gear":["Boîte à rythmes","Synthétiseur"],"construction":"Un riff de synthé obsédant, une voix féminine qui gémit et surtout un tempo qui ralentit jusqu'à s'arrêter presque, puis repart. C'est l'un des rares tubes de club bâtis sur un ralentissement du BPM.","producer_origins":"Marvin Louis Burns, fils de musicien de blues, est un DJ qui organise de grandes soirées à Chicago. Il construit le morceau comme une montée dramatique, pensée pour la piste.","club_sociology":"Il est interdit sur de nombreuses radios à cause de ses gémissements, ce qui en fait un tube européen. Il est emblématique de la culture du club comme espace d'érotisme assumé.","queer_ballroom_axis":"L'érotisme explicite du morceau prolonge l'héritage des pistes gays de Chicago, pour lesquelles la danse et le sexe ne sont pas séparés.","archive_ref":{"source":"last-night-dj","note":"Chicago, fin des années 80 : la house devient internationale.","note_en":"Late-80s Chicago: house goes international."},"why_this_record":"Lancez le pulse : le tempo réel du disque est une manipulation du BPM.","tags":["roots","crossover","us"],"further_reading":["do-you-remember-house"],"spotify":{"id":"7hnqJYCKZFW7vMoykaraZG","version":"Original Underground Mix"},"youtube":["3Y8w2W1uy2A","cH-ikdYOZhM","rmOAVfEDyhA"],"construction_en":"A haunting synth riff, a moaning female voice and, above all, a tempo that slows almost to a halt before starting up again. One of the rare club hits built on a BPM slowdown.","producer_origins_en":"Marvin Louis Burns, son of a blues musician, was a DJ who threw big parties in Chicago. He built the track as a dramatic build designed for the floor.","club_sociology_en":"Banned by many radio stations for its moans, it became a European hit. It epitomises the club as a space of open eroticism.","queer_ballroom_axis_en":"Its explicit eroticism extends the legacy of Chicago's gay dancefloors, where dancing and sex were never separate.","why_this_record_en":"Start the Pulse: the record's real tempo is itself a BPM manipulation.","gear_en":["Drum machine","Synthesizer"],"verified":false},{"id":"pacific-state","title":"Pacific State","artist":"808 State","year":1989,"label":"Creed / ZTT","city":"Manchester","country":"Royaume-Uni","continent":"Europe","genre":"acid","era":"era-1","bpm":116,"camelot_key":"2A","energy":5,"gear":["tr-808","tb-303","Saxophone"],"construction":"Des chants d'oiseaux, une rythmique 808 souple, une basse acid discrète et un saxophone jazz. C'est l'acid version balearic, pensée pour l'aube de l'Haçienda.","producer_origins":"Graham Massey, Martin Price et Gerald Simpson (avant son départ) se rencontrent autour du magasin de disques Eastern Bloc à Manchester. Le groupe est un collectif de fans de disques devenus producteurs.","club_sociology":"La version originale paraît sur le mini-album Quadrastate (Creed) en juillet 1989, avant le single ZTT de novembre (n°10 britannique). C'est un hymne de la fin des nuits Hot de l'Haçienda. Gerald Simpson, parti entre-temps, en conteste les crédits. Peter Hook raconte aussi le revers de l'époque : la violence des gangs, la drogue et la faillite d'un club adoré mais ingérable.","queer_ballroom_axis":"L'Haçienda abritera Flesh, sa nuit gay, mais 808 State reste ancré dans une culture mancunienne surtout masculine et hétéro, celle du « Madchester ».","archive_ref":{"source":"hacienda-hook","note":"L'Haçienda vue de l'intérieur par l'un de ses propriétaires.","note_en":"The Haçienda seen from inside by one of its owners."},"why_this_record":"C'est la bande-son de Manchester en 1989.","tags":["uk","rave","machine","chill"],"further_reading":["adventures-wonderland","electrochoc","hypnotised","second-summer","sonic-youth-floor"],"spotify":{"id":"2edMCBeBu2kYUHi3mBp5uO"},"youtube":["tLxDRePUwEY","7rtIN9dWHsw","Tv0UiQ5n7SM"],"construction_en":"Birdsong, a supple 808 rhythm, a discreet acid bass and a jazz saxophone: balearic acid, made for dawn at the Haçienda.","producer_origins_en":"Graham Massey, Martin Price and Gerald Simpson (before he left) met around Manchester's Eastern Bloc record shop: a collective of record fans turned producers.","club_sociology_en":"The original version came out on the mini-album Quadrastate (Creed) in July 1989, before the ZTT single in November (UK number 10). It was an end-of-night anthem at the Haçienda's Hot nights. Gerald Simpson, who had left by then, disputed the credits. Peter Hook also tells the flip side of the era: gang violence, drugs and the bankruptcy of a beloved but unmanageable club.","queer_ballroom_axis_en":"The Haçienda would host Flesh, its gay night, but 808 State stayed rooted in a mostly male, straight Mancunian culture, that of \"Madchester\".","why_this_record_en":"The soundtrack of Manchester in 1989.","country_en":"United Kingdom","verified":false,"story":"Le morceau commence chez Gerald Simpson, alors membre d'808 State. Selon Simpson, il visait une session pour John Peel ; selon Graham Massey, le groupe cherchait un morceau dans l'esprit de « Open Your Eyes » de Marshall Jefferson, puis ajoute oiseaux et saxophone (Massey joue la partie). Une version circule en white label en mai 1989 et paraît le 31 juillet sur le mini-album Quadrastate (Creed), avec Simpson crédité. Elle est jouée à la fin des nuits Hot à l'Haçienda, puis Gary Davies l'entend à Ibiza et la passe en journée sur Radio 1. ZTT signe le groupe, le single sort le 21 novembre 1989 et atteint le n°10 britannique. Simpson, parti entre-temps, conteste les crédits.","story_en":"The track starts with Gerald Simpson, then a member of 808 State. Simpson says it was meant for a John Peel session; Graham Massey says the group was aiming for something in the vein of Marshall Jefferson's \"Open Your Eyes\", then added birdsong and saxophone (Massey plays the part). A version circulated on white label in May 1989 and appeared on 31 July on the Quadrastate mini-album (Creed), with Simpson credited. It closed Hot nights at the Haçienda, then Gary Davies heard it in Ibiza and played it on daytime Radio 1. ZTT signed the group, the single came out on 21 November 1989 and reached UK no. 10. Simpson, by then gone, disputed the credits.","timeline":[{"date":"1988-11→1989-03","fr":"Enregistrement de Quadrastate.","en":"Quadrastate recorded."},{"date":"1989-05","fr":"White label ; Massey la porte à Mike Pickering, Graeme Park, Jon Da Silva (Haçienda).","en":"White label; Massey takes it to Mike Pickering, Graeme Park, Jon Da Silva (Haçienda)."},{"date":"1989-07-31","fr":"Sortie sur Quadrastate (Creed).","en":"Released on Quadrastate (Creed)."},{"date":"1989-11-21","fr":"Single ZTT ; n°10 au Royaume-Uni, 11 semaines au classement.","en":"ZTT single; UK no. 10, 11 weeks on chart."},{"date":"1989","fr":"Simpson quitte le groupe et conteste les crédits ; accord de publication discuté.","en":"Simpson leaves and disputes credits."}],"credits":[{"k":"auteurs","v":"Gerald Simpson, 808 State","k_en":"Writers","v_en":"Gerald Simpson, 808 State"},{"k":"saxophone","v":"Graham Massey","k_en":"Saxophone","v_en":"Graham Massey"},{"k":"label","v":"Creed (version originale, Quadrastate) ; ZTT (single)","k_en":"Label","v_en":"Creed (original version, Quadrastate); ZTT (single)"},{"k":"versions","v":"Pacific 707 (7\"), Pacific 202, Pacific State (Quadrastate)","k_en":"Versions","v_en":"Pacific 707 (7\"), Pacific 202, Pacific State (Quadrastate)"}],"book_refs":[{"source":"hacienda-hook","where":"Chapitres sur la nuit Hot et l'été 1989 à l'Haçienda","where_en":"Chapters on the Hot night and summer 1989 at the Haçienda"},{"source":"sonic-youth-floor","where":"Passages de Haslam sur Manchester 1988-1989 (DJs, Pickering)","where_en":"Haslam on Manchester 1988–89 (DJs, Pickering)"}],"references":["https://en.wikipedia.org/wiki/Pacific_State_(song)","https://en.wikipedia.org/wiki/808_State","https://en.wikipedia.org/wiki/Andy_Barker_(musician)","https://en.wikipedia.org/wiki/Quadrastate","https://en.wikipedia.org/wiki/Techno"],"verify":["Chiffre « 11 semaines » au classement (Wikipedia 808 State)","Version qui a joué à l'Haçienda (cassette Barker/Thunderdome vs white label)"],"pilot":true},{"id":"stakker-humanoid","title":"Stakker Humanoid","artist":"Humanoid","year":1988,"label":"Westside Records","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"acid","era":"era-1","bpm":126,"camelot_key":"7A","energy":9,"gear":["tb-303","Voix synthétique"],"construction":"Une 303 hurlante, un kick sec et une voix robotique. L'acid britannique devient plus agressif et plus rapide, avec un pied déjà dans le hardcore.","producer_origins":"Brian Dougans, futur Future Sound of London, rencontre à Manchester le collectif vidéo Stakker, qui cherche une musique pour ses images informatiques. Morgan Khan (Street Sounds) l'envoie enregistrer aux Dance Studios d'Ealing avec l'ingénieur John Laker ; le morceau est composé en deux jours.","club_sociology":"Il entre dans le top 20 britannique en 1988, en pleine panique morale sur l'acid house. Les flyers et cartes de membre de l'époque, archivés dans Rave Art, montrent l'esthétique smiley et futuriste de ces nuits.","queer_ballroom_axis":"Pas d'ancrage queer explicite : c'est un acid de rave, celui d'une jeunesse britannique qui se réapproprie le son de Chicago.","archive_ref":{"source":"rave-art","note":"L'iconographie des flyers et cartes de membre de 1988-1989.","note_en":"The iconography of 1988–1989 flyers and membership cards."},"why_this_record":"C'est la 303 qui passe du club à la rave.","tags":["uk","rave","machine"],"further_reading":["carl-cox-oh-yes","class-of-88","energy-flash","second-summer","adventures-wonderland"],"spotify":{"id":"78zB5GFOUsmkbvnFSiRvlR"},"youtube":["ifXN8ejTDTI","EOI1n8L-Z5E","6DnfjMbu-Pg"],"construction_en":"A screaming 303, a dry kick and a robotic voice. British acid gets faster and more aggressive, with one foot already in hardcore.","producer_origins_en":"Brian Dougans, later of Future Sound of London, met the Stakker video collective in Manchester as they looked for music for their computer graphics. Morgan Khan (Street Sounds) sent him to record at Ealing's Dance Studios with engineer John Laker; the track was written in two days.","club_sociology_en":"It reached the UK top 20 in 1988, at the height of the acid house moral panic. The flyers and membership cards of the period, archived in Rave Art, show the smiley, futurist aesthetic of those nights.","queer_ballroom_axis_en":"No explicit queer anchoring: this is rave acid, that of British youth reclaiming the Chicago sound.","why_this_record_en":"The 303 moving from club to rave.","city_en":"London","country_en":"United Kingdom","gear_en":["tb-303","Synthetic voice"],"verified":false,"story":"Brian Dougans rencontre Mark McLean et Colin Scott, du collectif vidéo Stakker, à Manchester (récits divergents, non tranchés : l'Haçienda, ou un cours à Salford). Les trois travaillent sur des images informatiques et cherchent une musique. Morgan Khan, patron de Street Sounds, invite Dougans à enregistrer au Dance Studios d'Ealing avec l'ingénieur John Laker. Le morceau est composé en deux jours et sort sur Westside en août 1988. Il entre au classement britannique le 26 novembre, culmine au n°17 et reste huit semaines ; Dougans passe à Top of the Pops le 1er décembre. Il est n°1 du classement dance pendant cinq semaines. Une source seulement évoque un sample du jeu vidéo Berzerk (« Humanoid », « Intruder alert ») : information non validée. Laker revendique un rôle d'arrangeur et de coauteur ; Dougans a dû engager une action contre Westside pour ses droits.","story_en":"Brian Dougans met Mark McLean and Colin Scott of the video collective Stakker in Manchester (accounts differ and are unresolved: the Haçienda, or a course at Salford). The three were working on computer graphics and looking for music. Morgan Khan, head of Street Sounds, invited Dougans to record at Dance Studios in Ealing with engineer John Laker. The track was made in two days and released on Westside in August 1988. It entered the UK chart on 26 November, peaked at no. 17 and stayed eight weeks; Dougans appeared on Top of the Pops on 1 December. It was no. 1 on the dance chart for five weeks. Only one source mentions a sample from the video game Berzerk (\"Humanoid\", \"Intruder alert\"): not validated. Laker claims an arranging and co-writing role; Dougans had to take legal action against Westside over his rights.","timeline":[{"date":"1988","fr":"Rencontre avec Stakker ; demo envoyée à Morgan Khan.","en":"Meeting with Stakker; demo sent to Morgan Khan."},{"date":"1988-08","fr":"Sortie sur Westside (WSR 12).","en":"Released on Westside (WSR 12)."},{"date":"1988-11-26","fr":"Entrée au classement ; n°17.","en":"Chart entry; peaks at no. 17."},{"date":"1988-12-01","fr":"Passage à Top of the Pops.","en":"Top of the Pops appearance."},{"date":"1992 / 2001","fr":"Rééditions : n°40 puis n°65.","en":"Reissues: no. 40 then no. 65."}],"credits":[{"k":"composition","v":"Brian Dougans","k_en":"Composition","v_en":"Brian Dougans"},{"k":"ingénieur","v":"John Laker","k_en":"Engineer","v_en":"John Laker"},{"k":"images","v":"Stakker (Mark McLean, Colin Scott)","k_en":"Visuals","v_en":"Stakker (Mark McLean, Colin Scott)"},{"k":"label","v":"Westside Records (WSR 12)","k_en":"Label","v_en":"Westside Records (WSR 12)"},{"k":"studio","v":"Dance Studios, Ealing","k_en":"Studio","v_en":"Dance Studios, Ealing"}],"book_refs":[{"source":"rave-art","where":"Iconographie de la fin 1988 (flyers, premières cartes de membre)","where_en":"Late 1988 imagery (flyers, early membership cards)"},{"source":"adventures-wonderland","where":"Panique morale autour de l'acid house, hiver 1988","where_en":"Moral panic around acid house, winter 1988"}],"references":["https://en.wikipedia.org/wiki/Stakker_Humanoid","https://www.officialcharts.com/songs/humanoid-stakker-humanoid/","https://fractionaldifference.wordpress.com/2021/04/11/humanoid-stakker-humanoid/","https://ghostdeep.substack.com/p/future-sound-of-london-accelerator"],"verify":["Lieu de la rencontre Dougans / Stakker (récits divergents)","Sample de Berzerk","Part de Laker dans l'écriture"],"pilot":true},{"id":"gypsy-woman","title":"Gypsy Woman (She's Homeless)","artist":"Crystal Waters","year":1991,"label":"Mercury","city":"Baltimore","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-2","bpm":122,"camelot_key":"11A","energy":7,"gear":["Orgue (preset)","Boîte à rythmes"],"construction":"Un orgue en riff, un kick sec et le célèbre « la da dee la dee da » scatté. C'est un tube de club au texte social : la chanson parle d'une femme sans abri.","producer_origins":"Crystal Waters, poétesse et fonctionnaire, écrit le texte. Les Basement Boys de Baltimore le produisent, dans le prolongement du garage new-yorkais.","club_sociology":"Le disque est un succès mondial. Il montre que la house américaine des années 90 peut raconter la pauvreté urbaine des années Reagan-Bush sur un groove euphorique.","queer_ballroom_axis":"Le « la da dee » est devenu un classique de ballroom et de vogue. La voix est réutilisée sans fin dans les remixes ballroom.","archive_ref":{"source":"underground-massive","note":"La house américaine au début des années 90.","note_en":"American house in the early 1990s."},"why_this_record":"Un tube de piste qui parle de la rue.","tags":["us","diva","ballroom"],"further_reading":["beat-scene-sound","decade-house-bleakman","last-night-dj"],"youtube":["_KztNIg4cvE","IF-Lz5roIWc","DZbtIjHtQU4"],"construction_en":"An organ riff, a dry kick and the famous scatted \"la da dee la dee da\". A club hit with a social lyric: the song is about a homeless woman.","producer_origins_en":"Crystal Waters, poet and civil servant, wrote the words. Baltimore's Basement Boys produced it, in the wake of New York garage.","club_sociology_en":"A worldwide hit, it showed 1990s American house could tell of urban poverty in the Reagan–Bush years over a euphoric groove.","queer_ballroom_axis_en":"The \"la da dee\" became a ballroom and vogue classic; the vocal is endlessly reused in ballroom remixes.","why_this_record_en":"A dancefloor hit that speaks about the street.","gear_en":["Organ (preset)","Drum machine"],"verified":false},{"id":"show-me-love","title":"Show Me Love (StoneBridge Club Mix)","artist":"Robin S","year":1992,"label":"Champion / Big Beat","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-2","bpm":122,"camelot_key":"10A","energy":8,"gear":["korg-m1"],"construction":"Le remix de StoneBridge remplace la production originale par une basse d'orgue tirée d'un preset du Korg M1, un kick sec et une voix gospel qui monte. Ce son d'orgue M1 devient l'une des signatures des années 90.","producer_origins":"Robin Stone est une chanteuse new-yorkaise. Le remixeur suédois StoneBridge transforme une ballade house en tube de club : la circulation transatlantique fonctionne à plein.","club_sociology":"Le remix, d'abord édité au Royaume-Uni, devient un hit mondial en 1993. Il sera samplé et remixé pendant trente ans, jusqu'à la vague « 90s revival » des années 2020.","queer_ballroom_axis":"C'est la voix de diva gospel par excellence pour les pistes gays et la ballroom.","archive_ref":{"source":"rave-on","note":"La circulation mondiale des tubes de club.","note_en":"The global circulation of club hits."},"why_this_record":"Une seule couleur de preset suffit à définir une décennie.","tags":["us","diva","gospel","queer","ballroom"],"further_reading":["decade-house-bleakman"],"spotify":{"id":"0zvlNfLqNLMoGmy5X9v5Iq","version":"StoneBridge Club Mix (remaster 2020)"},"youtube":["Jz9XM_Uu9w0","O7k81MF6ByA","Ps2Jc28tQrw"],"construction_en":"StoneBridge's remix replaces the original production with an organ bass from a Korg M1 preset, a dry kick and a soaring gospel vocal. That M1 organ sound became one of the signatures of the 90s.","producer_origins_en":"Robin Stone is a New York singer. Swedish remixer StoneBridge turned a house ballad into a club smash: transatlantic circulation at full throttle.","club_sociology_en":"First released in the UK, the remix became a global hit in 1993. It would be sampled and remixed for thirty years, up to the 2020s \"90s revival\".","queer_ballroom_axis_en":"The gospel diva voice par excellence for gay dancefloors and ballroom.","why_this_record_en":"A single preset colour is enough to define a decade.","verified":false},{"id":"thats-the-way-love-is","title":"That's the Way Love Is","artist":"Ten City","year":1989,"label":"Atlantic","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"deep","era":"era-1","bpm":118,"camelot_key":"4B","energy":6,"gear":["Boîte à rythmes","Cordes (synthétiseur)"],"construction":"Le chant de fausset de Byron Stingily, des cordes soul et une rythmique deep : la soul de Philadelphie relue par Chicago.","producer_origins":"Ten City, avec le producteur Marshall Jefferson, défend une house « musicale » faite de chanteurs, d'harmonies et de cordes, contre la sécheresse du jack.","club_sociology":"Le groupe signe chez Atlantic : une major mise sur la house soul. C'est le début de la « deep house vocale » qui inspirera le garage britannique.","queer_ballroom_axis":"Le fausset de Stingily prolonge la tradition des voix masculines aiguës de la soul (Sylvester, Curtis Mayfield), ce qui brouille les codes de genre.","archive_ref":{"source":"real-story-saunders","note":"La house de Chicago dans les majors à la fin des années 80.","note_en":"Chicago house on major labels in the late 1980s."},"why_this_record":"C'est l'héritage soul de la house, en pleine lumière.","tags":["us","gospel","deep"],"further_reading":["energy-never-dies","history-of-house","soul-underground"],"spotify":{"id":"3DcPu8U9kOstId0RYvkbgd"},"youtube":["9Wossf7w1o4","Y_edhEpE_YM","BTicH3hlTPM"],"construction_en":"Byron Stingily's falsetto, soul strings and a deep groove: Philadelphia soul reread by Chicago.","producer_origins_en":"Ten City, with producer Marshall Jefferson, championed a \"musical\" house of singers, harmonies and strings, against the dryness of jack.","club_sociology_en":"The group signed to Atlantic: a major betting on soulful house. The start of the \"vocal deep house\" that would inspire UK garage.","queer_ballroom_axis_en":"Stingily's falsetto extends soul's tradition of high male voices (Sylvester, Curtis Mayfield), blurring gender codes.","why_this_record_en":"House's soul heritage in full light.","gear_en":["Drum machine","Strings (synthesizer)"],"verified":false},{"id":"clear","title":"Clear","artist":"Cybotron","year":1983,"label":"Fantasy","city":"Detroit","country":"USA","continent":"Amérique du Nord","genre":"detroit","era":"era-1","bpm":130,"camelot_key":"12A","energy":7,"gear":["tr-808","Synthétiseurs"],"construction":"Une ligne de synthé glacée, une rythmique électro 808 et des stabs futuristes. C'est un pont entre Kraftwerk et le funk de Detroit.","producer_origins":"Juan Atkins, l'un des Belleville Three, et Rick Davis, vétéran du Vietnam passionné de futurisme. Atkins y pose les bases de ce qui deviendra la techno.","club_sociology":"À Detroit, la jeunesse noire de la classe moyenne écoute Kraftwerk à la radio (The Electrifying Mojo). Dan Sicko montre comment ce futurisme naît d'une ville en déclin industriel.","queer_ballroom_axis":"Le récit de la techno reste peu attentif aux scènes queer. Sicko rappelle cependant l'influence des DJs des clubs gays de Detroit sur la génération Belleville.","archive_ref":{"source":"techno-rebels","note":"Juan Atkins, Cybotron et l'électro de Detroit.","note_en":"Juan Atkins, Cybotron and Detroit electro."},"why_this_record":"Le futur de la house et de la techno s'entend déjà dès 1983.","tags":["roots","futurism","machine","us"],"further_reading":["modulations"],"spotify":{"id":"77g4mQWUcR3eF5sbFQPa8y","version":"remix Troy Pierce (original indisponible)"},"youtube":["YT4qqZHN8no","hsBv-dOXVXI","B3N9yioOibE"],"construction_en":"An icy synth line, an 808 electro rhythm and futurist stabs: a bridge between Kraftwerk and Detroit funk.","producer_origins_en":"Juan Atkins, one of the Belleville Three, and Rick Davis, a Vietnam veteran obsessed with futurism. Atkins lays the foundations of what would become techno.","club_sociology_en":"In Detroit, middle-class Black youth heard Kraftwerk on the radio (The Electrifying Mojo). Dan Sicko shows how this futurism grew out of a city in industrial decline.","queer_ballroom_axis_en":"The techno narrative pays little attention to queer scenes. Sicko nonetheless notes the influence of Detroit's gay-club DJs on the Belleville generation.","why_this_record_en":"The future of house and techno is already audible in 1983.","gear_en":["tr-808","Synthesizers"],"verified":false},{"id":"no-ufos","title":"No UFO's","artist":"Model 500","year":1985,"label":"Metroplex","city":"Detroit","country":"USA","continent":"Amérique du Nord","genre":"detroit","era":"era-1","bpm":132,"camelot_key":"2A","energy":7,"gear":["tr-808","Synthétiseurs"],"construction":"Une basse séquencée, des voix vocodées et une 808 électro. Le morceau est plus funk que house, mais il pose la grammaire machine de la techno.","producer_origins":"Juan Atkins fonde Metroplex, son label, pour contrôler sa production : l'indépendance est au cœur de l'éthique techno de Detroit.","club_sociology":"C'est l'une des premières sorties « techno » de Detroit. Elle est importée en Europe par les disquaires spécialisés avant même d'être connue localement.","queer_ballroom_axis":"Pas d'axe queer explicite. C'est l'afro-futurisme de Detroit : imaginer un ailleurs pour les corps noirs.","archive_ref":{"source":"techno-rebels","note":"Metroplex et l'indépendance de Detroit.","note_en":"Metroplex and Detroit's independence."},"why_this_record":"C'est l'acte d'indépendance de la techno.","tags":["roots","futurism","us"],"further_reading":["underground-massive"],"spotify":{"id":"1Ro7L7RPp5P8heOfW4EQKA","version":"Vocal"},"youtube":["xcdOBLH_AXs","KNz01ty-kTQ","Rsb-Yxqg_ys"],"construction_en":"A sequenced bassline, vocoded voices and an 808 electro beat. More funk than house, but it lays down techno's machine grammar.","producer_origins_en":"Juan Atkins founded his own label, Metroplex, to control his output: independence sits at the core of Detroit techno's ethic.","club_sociology_en":"One of Detroit's first \"techno\" releases. Specialist shops imported it into Europe before it was even known at home.","queer_ballroom_axis_en":"No explicit queer axis. This is Detroit Afrofuturism: imagining an elsewhere for Black bodies.","why_this_record_en":"Techno's declaration of independence.","gear_en":["tr-808","Synthesizers"],"verified":false},{"id":"knights-of-the-jaguar","title":"Knights of the Jaguar","artist":"DJ Rolando (Underground Resistance)","year":1998,"label":"Underground Resistance","city":"Detroit","country":"USA","continent":"Amérique du Nord","genre":"detroit","era":"era-2","bpm":132,"camelot_key":"7A","energy":9,"gear":["tr-909","Synthétiseur (cordes)"],"construction":"Des nappes de cordes épiques, une 909 implacable et un thème mélodique qui monte sans fin. Detroit dans sa veine la plus lyrique.","producer_origins":"Rolando Rocha, DJ chicano de Detroit, rejoint Underground Resistance, le collectif militant de Mike Banks et Jeff Mills, qui refuse l'industrie et ses visages.","club_sociology":"Sony tente d'en obtenir une licence, puis publie une reprise (« Jaguar », 2000). UR répond par une mise en demeure et appelle disquaires et DJs au boycott. Les détails restent contestés, mais l'affaire fait du morceau un symbole de résistance contre la marchandisation de la techno.","queer_ballroom_axis":"Le titre évoque les guerriers aztèques : un imaginaire chicano et résistant, mais sans ancrage queer.","archive_ref":{"source":"techno-rebels","note":"Underground Resistance et l'éthique militante de Detroit ; affaire Sony documentée par la presse (Hot Press).","note_en":"Underground Resistance and Detroit's militant ethic; the Sony affair as reported in the press (Hot Press)."},"why_this_record":"La techno comme acte politique.","tags":["futurism","us","politics"],"further_reading":["underground-massive"],"spotify":{"id":"3xxARypr8NdEMesYUHSsGK"},"youtube":["ZcC3vVh3cOE","DHovfQ0VQkg","W3HHcH2oCsE"],"construction_en":"Epic string pads, a relentless 909 and a melodic theme that rises without end: Detroit at its most lyrical.","producer_origins_en":"Rolando Rocha, a Chicano DJ from Detroit, joined Underground Resistance, Mike Banks and Jeff Mills's militant collective that rejected the industry and its faces.","club_sociology_en":"Sony tried to license it, then released a cover (\"Jaguar\", 2000). UR answered with a cease-and-desist and called on record shops and DJs to boycott. The details remain disputed, but the affair made the track a symbol of resistance against the commodification of techno.","queer_ballroom_axis_en":"The title evokes Aztec warriors: a Chicano imagery of resistance, with no queer anchoring.","why_this_record_en":"Techno as a political act.","gear_en":["tr-909","Synthesizer (strings)"],"verified":false},{"id":"crispy-bacon","title":"Crispy Bacon","artist":"Laurent Garnier","year":1997,"label":"F Communications","city":"Paris","country":"France","continent":"Europe","genre":"french-touch","era":"era-2","bpm":134,"camelot_key":"9A","energy":10,"gear":["tr-909","Synthétiseurs"],"construction":"Une 909 lancée à pleine vitesse, des synthés qui s'emballent et une tension qui ne retombe jamais. C'est l'aile techno de la scène française, à l'opposé du filtre disco.","producer_origins":"Laurent Garnier a fait son éducation de DJ à l'Haçienda, à Manchester, à la fin des années 80. De retour en France, il cofonde F Communications avec Éric Morand. Il est souvent rangé parmi les précurseurs de la French Touch plutôt qu'en son cœur : sa musique reste techno.","club_sociology":"Dans Electrochoc, il raconte la répression des raves en France, les fermetures et la mauvaise réputation de la techno dans les médias des années 90.","queer_ballroom_axis":"À Paris, la house trouve d'abord ses publics dans les clubs gays et mondains, comme le Palace. Garnier en hérite avant de lancer ses soirées Wake Up au Rex.","archive_ref":{"source":"electrochoc","note":"Les années Haçienda puis la scène techno française face à la répression.","note_en":"The Haçienda years, then the French techno scene under repression."},"why_this_record":"C'est la France des raves, pas seulement celle du filtre.","tags":["europe","rave","machine"],"further_reading":["hacienda-hook","musique-house-bidder","garnier-ramadier-2026"],"spotify":{"id":"55kPbg3l5wM6u0rx9L3ypa"},"youtube":["fki4TySQqc0","4jEsu51QHtY","ASGVULb7X6U"],"construction_en":"A 909 at full throttle, runaway synths and tension that never drops: the techno wing of the French scene, the opposite of the disco filter.","producer_origins_en":"Laurent Garnier learned his craft as a DJ at Manchester's Haçienda in the late 80s. Back in France he co-founded F Communications with Éric Morand. He is often counted among the French Touch's precursors rather than at its core: his music remains techno.","club_sociology_en":"In Electrochoc he recounts the crackdown on raves in France, the closures and techno's bad press in the 1990s.","queer_ballroom_axis_en":"In Paris, house first found its audiences in gay and society clubs such as Le Palace. Garnier inherited that before launching his Wake Up nights at the Rex.","why_this_record_en":"The France of raves, not only of the filter.","gear_en":["tr-909","Synthesizers"],"verified":false,"story":"Laurent Garnier a fondé les soirées Wake Up au Rex Club à Paris au début des années 90, après un séjour à Manchester et un passage à New York où il rencontre Frankie Knuckles. Avec Éric Morand, il lance F Communications, label de ce disque. « Crispy Bacon » sort en 1997, au moment de l'album « 30 ». Le single (Part 1 et 2) paraît avec des remixes de DJ Hell, d'Aux 88 & DJ Gilb'r et de Jeff Mills, et atteint le n°60 au Royaume-Uni. Un mix de 2003 consacré à dix ans au Rex le place à côté de « The Bells » de Jeff Mills.","story_en":"Laurent Garnier founded the Wake Up nights at Paris's Rex Club in the early 1990s, after time in Manchester and a stint in New York where he met Frankie Knuckles. With Éric Morand he launched F Communications, the label of this record. \"Crispy Bacon\" came out in 1997 alongside the album \"30\". The single (Part 1 and 2) appeared with remixes by DJ Hell, Aux 88 & DJ Gilb'r and Jeff Mills, and reached no. 60 in the UK. A 2003 mix marking ten years at the Rex places it next to Jeff Mills's \"The Bells\".","timeline":[{"date":"1988","fr":"Retour en France ; passage à New York.","en":"Returns to France; time in New York."},{"date":"1993","fr":"Disque « Wake Up! » (Fnac Music Dance Division) pour l'anniversaire de la soirée.","en":"\"Wake Up!\" release (Fnac Music Dance Division) for the night's anniversary."},{"date":"1994","fr":"Premier album Shot in the Dark ; « Astral Dreams ».","en":"First album Shot in the Dark; \"Astral Dreams\"."},{"date":"1997","fr":"Single « Crispy Bacon » et album 30 (F Communications). Les dates de sortie diffèrent entre sources (février / 31 mars).","en":"\"Crispy Bacon\" single and album 30 (F Communications). Release dates differ between sources (February / 31 March)."},{"date":"2003","fr":"Mix « 10 Years at the Rex Club ».","en":"Mix \"10 Years at the Rex Club\"."}],"credits":[{"k":"auteur","v":"Laurent Garnier","k_en":"Writer","v_en":"Laurent Garnier"},{"k":"label","v":"F Communications","k_en":"Label","v_en":"F Communications"},{"k":"remixes","v":"DJ Hell, Aux 88 & DJ Gilb'r, Jeff Mills","k_en":"Remixes","v_en":"DJ Hell, Aux 88 & DJ Gilb'r, Jeff Mills"},{"k":"album","v":"30 (1997)","k_en":"Album","v_en":"30 (1997)"},{"k":"classement","v":"UK n°60 (Part 1)","k_en":"Chart","v_en":"UK no. 60 (Part 1)"}],"book_refs":[{"source":"garnier-ramadier-2026","where":"Garnier (Mathilde Ramadier, Les Pérégrines, 2026) : passage sur Crispy Bacon et l'album 30, à localiser. Ouvrage fondé sur des entretiens avec Garnier ; évoque aussi ses nuits à l'Haçienda","where_en":"Garnier (Mathilde Ramadier, Les Pérégrines, 2026): passage on Crispy Bacon and the album 30, to locate. Based on interviews with Garnier; also covers his Haçienda nights"},{"source":"electrochoc","where":"Chapitres sur Wake Up au Rex, la création de F Communications et la répression des raves","where_en":"Chapters on Wake Up at the Rex, F Communications and the crackdown on raves"}],"references":["https://en.wikipedia.org/wiki/Laurent_Garnier","https://www.laurentgarnier.com/lg--subpage--rpm--disco.html","https://xlr8r.com/features/real-talk-laurent-garnier/","https://www.shazam.com/song/138728085/crispy-bacon","https://leclaireur.fnac.com/article/689190-laurent-garnier-que-revele-le-livre-de-mathilde-ramadier-sur-le-dj/","https://mixmag.fr/read/un-nouveau-livre-retrace-la-vie-et-la-carriere-de-laurent-garnier-","https://editionslesperegrines.fr/products/garnier"],"verify":["Date exacte de sortie (février ou mars 1997)","Récit de la fabrication du morceau : à lire dans Garnier (Ramadier), je n'ai pas accès au texte"],"pilot":true},{"id":"cassius-1999","title":"Cassius 1999","artist":"Cassius","year":1999,"label":"Virgin","city":"Paris","country":"France","continent":"Europe","genre":"french-touch","era":"era-2","bpm":123,"camelot_key":"1A","energy":8,"gear":["Sampler","Filtre","Compresseur"],"construction":"Une boucle disco compressée à l'extrême, un filtre qui pompe et des voix samplées. C'est le son French Touch poussé jusqu'à la saturation.","producer_origins":"Philippe Zdar (ingénieur du son de MC Solaar) et Hubert « Boombass » Blanc-Francard viennent du rap français : la French Touch est aussi une histoire de beatmakers.","club_sociology":"Le disque atteint la 7e place des charts britanniques en janvier 1999 et la 1re place du classement dance (Official Charts). La French Touch devient une industrie d'export, financée par les majors.","queer_ballroom_axis":"Comme la filter house en général, il recycle la disco queer sans la nommer.","archive_ref":{"source":"electrochoc","note":"La scène française de la fin des années 90.","note_en":"The late-90s French scene."},"why_this_record":"Il montre la porosité entre le rap et la house à Paris.","tags":["europe","filter","disco","sample"],"further_reading":["decade-house-bleakman"],"spotify":{"id":"2R53yign0dvy3i4TLAr2Ud"},"youtube":["QXSlkjPbpkA","NDesnOyWzL0","mDPGWgVHolI"],"construction_en":"A disco loop compressed to the extreme, a pumping filter and sampled vocals: the French Touch sound pushed into saturation.","producer_origins_en":"Philippe Zdar (MC Solaar's engineer) and Hubert \"Boombass\" Blanc-Francard came from French rap: the French Touch is also a beatmakers' story.","club_sociology_en":"The record reached number 7 in the UK singles chart in January 1999 and number 1 on the dance chart (Official Charts). The French Touch became an export industry funded by the majors.","queer_ballroom_axis_en":"Like filter house in general, it recycles queer disco without naming it.","why_this_record_en":"It shows how porous rap and house were in Paris.","gear_en":["Sampler","Filter","Compressor"],"verified":false},{"id":"lady-modjo","title":"Lady (Hear Me Tonight)","artist":"Modjo","year":2000,"label":"Sound of Barclay","city":"Paris","country":"France","continent":"Europe","genre":"french-touch","era":"era-2","bpm":126,"camelot_key":"4B","energy":7,"gear":["Sampler","Guitare (sample)"],"construction":"Un riff de guitare samplé sur « Soup for One » de Chic, un kick disco et une voix pop. La French Touch à sa forme la plus radiophonique.","producer_origins":"Romain Tranchart et Yann Destagnol, étudiants en musique, produisent un tube mondial presque sans moyens, grâce au sample.","club_sociology":"C'est un numéro 1 au Royaume-Uni. Le sample de Chic, crédité à Nile Rodgers et Bernard Edwards, rappelle que la disco nourrit littéralement cette économie.","queer_ballroom_axis":"La disco de Chic, née dans les clubs mixtes et gays de New York, devient de la pop européenne mainstream.","archive_ref":{"source":"hot-stuff","note":"La disco comme matrice de la pop.","note_en":"Disco as the matrix of pop."},"why_this_record":"C'est l'apogée commerciale du filtre français.","tags":["europe","filter","disco","sample","pop"],"spotify":{"id":"49X0LAl6faAusYq02PRAY6"},"youtube":["mMfxI3r_LyA","vRB1MLGEHSc","dhpHOn5pM9k"],"further_reading":["full-on"],"construction_en":"A guitar riff sampled from Chic's \"Soup for One\", a disco kick and a pop vocal: the French Touch at its most radio-friendly.","producer_origins_en":"Romain Tranchart and Yann Destagnol, two music students, made a global hit on almost no budget, thanks to the sample.","club_sociology_en":"A UK number one. The Chic sample, credited to Nile Rodgers and Bernard Edwards, is a reminder that disco literally feeds this economy.","queer_ballroom_axis_en":"Chic's disco, born in New York's mixed and gay clubs, becomes mainstream European pop.","why_this_record_en":"The commercial peak of the French filter.","gear_en":["Sampler","Guitar (sample)"],"verified":false},{"id":"positive-education","title":"Positive Education","artist":"Slam","year":1993,"label":"Soma Quality Recordings","city":"Glasgow","country":"Royaume-Uni","continent":"Europe","genre":"tech-house","era":"era-2","bpm":130,"camelot_key":"5A","energy":9,"gear":["tr-909","tb-303"],"construction":"Un riff acid lancinant, une 909 tendue et une montée infinie. Le morceau est taillé pour les grandes salles écossaises.","producer_origins":"Stuart McMillan et Orde Meikle, résidents du Sub Club de Glasgow, fondent Soma en 1991 avec Dave Clarke. « Positive Education » en est la huitième référence. Ce sont eux qui signeront ensuite le premier Daft Punk.","club_sociology":"La résidence de Slam est celle du samedi au Sub Club de Glasgow. Le lien avec les Arches, voûtes sous la gare centrale dont Brickwork retrace l'histoire jusqu'à leur fermeture en 2015, reste à confirmer dans le livre.","queer_ballroom_axis":"La scène écossaise est surtout hétéro. Les Arches abritaient pourtant aussi du théâtre et des soirées alternatives, ce qui en faisait un lieu plus ouvert que les clubs classiques.","archive_ref":{"source":"brickwork-arches","note":"Les Arches, Slam et la scène de Glasgow.","note_en":"The Arches, Slam and the Glasgow scene."},"why_this_record":"Glasgow, capitale de la techno britannique.","tags":["uk","warehouse","machine","rave"],"further_reading":["rave-on","techno-shuffle"],"spotify":{"id":"3RSvIGylwXhu3r83K1bkJJ"},"youtube":["td2gsObDqqA","E4dSRpSnPOU","KAewmsksg7s"],"construction_en":"A nagging acid riff, a taut 909 and an endless build, cut for Scotland's big rooms.","producer_origins_en":"Stuart McMillan and Orde Meikle, residents at Glasgow's Sub Club, founded Soma in 1991 with Dave Clarke. \"Positive Education\" was its eighth release. They would go on to sign Daft Punk's first record.","club_sociology_en":"Slam's residency was the Saturday night at Glasgow's Sub Club. Its link with the Arches, the vaults under Central Station whose story Brickwork tells up to their 2015 closure, still needs confirming in the book.","queer_ballroom_axis_en":"The Scottish scene was mostly straight. The Arches also hosted theatre and alternative nights, though, making it more open than a standard club.","why_this_record_en":"Glasgow, capital of British techno.","country_en":"United Kingdom","verified":false,"story":"Stuart McMillan et Orde Meikle, résidents du Sub Club de Glasgow, fondent Soma en 1991 avec Dave Clarke. « Positive Education » est la huitième référence du label. La base du morceau est trouvée en une demi-heure en studio. Sorti en 1993, il porte Slam au-delà de l'Écosse : McMillan dit que R&S et Richie Hawtin voulaient le signer. À Paris, Thomas Bangalter, 18 ans, l'aime et envoie à Soma un mot au nom de Daft Punk ; Soma sortira ensuite le premier EP du duo (The New Wave).","story_en":"Stuart McMillan and Orde Meikle, residents at Glasgow's Sub Club, founded Soma in 1991 with Dave Clarke. \"Positive Education\" is the label's eighth release. The basis of the track came together in half an hour in the studio. Released in 1993, it took Slam beyond Scotland: McMillan says R&S and Richie Hawtin both wanted to sign it. In Paris, 18-year-old Thomas Bangalter loved it and sent Soma a note in Daft Punk's name; Soma would go on to release the duo's first EP (The New Wave).","timeline":[{"date":"1991","fr":"Fondation de Soma ; premier disque de Slam, « Eterna ».","en":"Soma founded; Slam's first single, \"Eterna\"."},{"date":"1993","fr":"Sortie de « Positive Education » (8e référence de Soma).","en":"\"Positive Education\" released (Soma's 8th release)."},{"date":"1993-été","fr":"Daft Punk écrit à Soma après avoir entendu le disque.","en":"Daft Punk writes to Soma after hearing the record."},{"date":"1995","fr":"Soma sort The New Wave de Daft Punk (date selon VICE).","en":"Soma releases Daft Punk's The New Wave (date per VICE)."},{"date":"1996","fr":"Premier album de Slam, Headstates.","en":"Slam's debut album Headstates."}],"credits":[{"k":"auteurs","v":"Stuart McMillan, Orde Meikle","k_en":"Writers","v_en":"Stuart McMillan, Orde Meikle"},{"k":"label","v":"Soma Quality Recordings","k_en":"Label","v_en":"Soma Quality Recordings"},{"k":"ville","v":"Glasgow","k_en":"City","v_en":"Glasgow"}],"book_refs":[{"source":"brickwork-arches","where":"Chapitres sur la scène club de Glasgow, Soma, Slam et le rôle des Arches","where_en":"Chapters on Glasgow's club scene, Soma, Slam and the Arches' role"}],"references":["https://www.discopogo.co/posts/slam-how-we-made-positive-education","https://www.electronicsound.co.uk/features/time-machine/soma-recordings/","https://mixmag.net/feature/label-focus-soma","https://www.vice.com/en/article/uk-techno-heroes-slam-are-back-and-fresher-than-ever/","https://en.wikipedia.org/wiki/Slam_(DJs)"],"verify":["Date de sortie du premier EP de Daft Punk sur Soma (1994 ou 1995 selon les sources)","Rôle exact des Arches dans l'histoire de Slam (Brickwork)"],"pilot":true},{"id":"charly","title":"Charly","artist":"The Prodigy","year":1991,"label":"XL Recordings","city":"Braintree (Essex)","country":"Royaume-Uni","continent":"Europe","genre":"rave-jungle","era":"era-2","bpm":138,"camelot_key":"9A","energy":9,"gear":["Sampler","Breakbeats","Synthés (stabs)"],"construction":"Un breakbeat accéléré, des stabs de synthé rave, le miaulement d'un chat et une phrase extraits de Charley Says, une série de films d'information publique pour enfants. C'est l'humour absurde du hardcore britannique.","producer_origins":"Liam Howlett, ancien DJ hip-hop de l'Essex, sample comme un beatmaker. Il produit pour les raves de la M25 depuis sa chambre.","club_sociology":"Le morceau atteint la 3e place en 1991 et lance l'étiquette « toytown techno ». Il appartient au moment des raves géantes et de la panique médiatique, contexte qui mènera trois ans plus tard au Criminal Justice Act de 1994.","queer_ballroom_axis":"Peu d'ancrage queer : la rave britannique est un phénomène de classe ouvrière, mixte mais surtout hétéro.","archive_ref":{"source":"rave-art","note":"Iconographie des raves de 1989-1992.","note_en":"Rave iconography, 1989–1992."},"why_this_record":"C'est le passage du sampler hip-hop au breakbeat rave.","tags":["uk","rave","sample"],"further_reading":["energy-flash","state-of-bass","techno-shuffle","class-of-88"],"spotify":{"id":"02G5u4AcbGhlfSkHzGCpmN"},"youtube":["cSTBFZ-To2E","oRJ607uXA40","w5PwyKtGXp8"],"construction_en":"A sped-up breakbeat, rave synth stabs, and a cat's meow plus a spoken line lifted from Charley Says, a series of children's public-information films: the absurd humour of British hardcore.","producer_origins_en":"Liam Howlett, a former Essex hip-hop DJ, samples like a beatmaker. He made tracks for the M25 raves from his bedroom.","club_sociology_en":"The track reached number 3 in 1991 and launched the \"toytown techno\" tag. It belongs to the era of giant raves and media panic, the context that would lead three years later to the 1994 Criminal Justice Act.","queer_ballroom_axis_en":"Little queer anchoring: British rave was a working-class phenomenon, mixed but mostly straight.","why_this_record_en":"The shift from the hip-hop sampler to the rave breakbeat.","country_en":"United Kingdom","gear_en":["Sampler","Breakbeats","Synths (stabs)"],"verified":false,"story":"Liam Howlett, producteur de Braintree (Essex), enregistre « Charly » aux studios C.W.S. et construit le morceau sur un extrait de Charley Says, un film d'information public pour enfants (« Mummy Should Know »). La version « Alley Cat Remix » sort chez XL le 12 août 1991. Il entre n°9 le 24 août, monte au n°3 pendant deux semaines et domine le classement dance. Il suit le « Summers Magic » de Mark Summers (janvier 1991) et lance l'étiquette « toytown techno ». Howlett refuse de refaire un disque dans le même registre, qui aurait été, dit-il, « notre perte ».","story_en":"Liam Howlett, a producer from Braintree (Essex), recorded \"Charly\" at C.W.S. studios and built it around a clip from Charley Says, a children's public information film (\"Mummy Should Know\"). The \"Alley Cat Remix\" came out on XL on 12 August 1991. It entered at no. 9 on 24 August, climbed to no. 3 for two weeks and topped the dance chart. It followed Mark Summers's \"Summers Magic\" (January 1991) and launched the \"toytown techno\" label. Howlett refused to make another record in that style, which he said would have been \"the downfall of us\".","timeline":[{"date":"1991-01","fr":"« Summers Magic » (Mark Summers) ouvre le filon des samples de TV pour enfants.","en":"Mark Summers's \"Summers Magic\" opens the children's-TV sample trend."},{"date":"1991-08-12","fr":"Sortie de « Charly (Alley Cat Remix) » chez XL.","en":"\"Charly (Alley Cat Remix)\" released on XL."},{"date":"1991-08-24","fr":"Entrée au n°9 ; n°3 deux semaines plus tard.","en":"Enters at no. 9; peaks at no. 3 two weeks later."},{"date":"1991","fr":"« Everybody in the Place » confirme le groupe.","en":"\"Everybody in the Place\" confirms the group."},{"date":"1996-04","fr":"Retour au classement (n°66).","en":"Re-enters the chart (no. 66)."}],"credits":[{"k":"auteur","v":"Liam Howlett","k_en":"Writer","v_en":"Liam Howlett"},{"k":"production","v":"Liam Howlett, Chaz Stevens","k_en":"Production","v_en":"Liam Howlett, Chaz Stevens"},{"k":"studio","v":"C.W.S., Essex","k_en":"Studio","v_en":"C.W.S., Essex"},{"k":"label","v":"XL Recordings (XLT 21)","k_en":"Label","v_en":"XL Recordings (XLT 21)"},{"k":"sample","v":"Charley Says, « Mummy Should Know »","k_en":"Sample","v_en":"Charley Says, \"Mummy Should Know\""}],"book_refs":[{"source":"class-of-88","where":"Fin des warehouse parties, 1991 (Wayne Anthony)","where_en":"End of the warehouse parties, 1991 (Wayne Anthony)"},{"source":"rave-art","where":"Flyers et cartes de 1991, esthétique « cartoon rave »","where_en":"1991 flyers and cards, \"cartoon rave\" aesthetic"}],"references":["https://en.wikipedia.org/wiki/Charly_(song)","https://en.wikipedia.org/wiki/The_Prodigy","https://en.wikipedia.org/wiki/Toytown_techno","https://en.wikipedia.org/wiki/Mark_Summers","https://en.wikipedia.org/wiki/Charley_Says"],"verify":["Chaz Stevens, rôle exact (producteur)"],"pilot":true},{"id":"i-want-you-forever","title":"I Want You (Forever)","artist":"Carl Cox","year":1991,"label":"Perfecto","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"rave-jungle","era":"era-2","bpm":128,"camelot_key":"8B","energy":8,"gear":["Breakbeats","Synthés"],"construction":"Un single de DJ aux sonorités proto-hardcore, des nappes euphoriques et une voix samplée, pensé pour les grands raves britanniques.","producer_origins":"Carl Cox, fils d'immigrés barbadiens, grandit dans le sud de Londres. DJ de sound system et de mariages, il devient l'un des premiers DJs noirs britanniques superstars, célèbre pour mixer à trois platines.","club_sociology":"Dans son autobiographie, Cox raconte le parcours d'un DJ noir dans une industrie britannique souvent blanche, des raves illégales jusqu'à ses résidences à Ibiza.","queer_ballroom_axis":"Cox incarne une autre lignée de la house : celle des sound systems caribéens britanniques, plus que celle des clubs queer.","archive_ref":{"source":"carl-cox-oh-yes","note":"Autobiographie : des sound systems aux résidences à Ibiza.","note_en":"Autobiography: from sound systems to Ibiza residencies."},"why_this_record":"Un DJ devenu une figure, et une autre généalogie noire de la house.","tags":["uk","rave","black-british"],"further_reading":["rave-on","class-of-88"],"spotify":{"id":"6A2fGSY2uZcidWpNosshqc","version":"remix Josh Butler (original indisponible)"},"youtube":["y7s9Cqw8Ykk","W0mQBnvVARk"],"construction_en":"A DJ single with a proto-hardcore sound, euphoric pads and a sampled vocal, built for Britain's big raves.","producer_origins_en":"Carl Cox, son of Barbadian immigrants, grew up in south London. A sound-system and wedding DJ, he became one of the first Black British superstar DJs, famous for mixing on three decks.","club_sociology_en":"In his autobiography, Cox describes the path of a Black DJ through an often white British industry, from illegal raves to his Ibiza residencies.","queer_ballroom_axis_en":"Cox embodies another lineage of house: Britain's Caribbean sound systems more than queer clubs.","why_this_record_en":"A DJ who became an icon, and another Black genealogy of house.","city_en":"London","country_en":"United Kingdom","gear_en":["Breakbeats","Synths"],"verified":false,"story":"Carl Cox est déjà un nom d'affiche des raves : il a joué à Sunrise en 1988, ouvert le Shoom de Danny Rampling et co-organisé The Project avec Paul Oakenfold. Son premier single, « I Want You (Forever) », sort en 1991 sur Perfecto, le label d'Oakenfold né en 1989 d'abord balearic puis tourné vers des tempos plus rapides. Il atteint le n°23 au Royaume-Uni (Cox parle de n°22) et lui vaut un passage à Top of the Pops.","story_en":"Carl Cox was already a headline name on the rave scene: he played Sunrise in 1988, opened Danny Rampling's Shoom and co-promoted The Project with Paul Oakenfold. His first single, \"I Want You (Forever)\", came out in 1991 on Perfecto, Oakenfold's label launched in 1989 as balearic and soon racing towards faster tempos. It reached no. 23 in the UK (Cox says no. 22) and earned him a Top of the Pops slot.","timeline":[{"date":"1987","fr":"Conversion à la house de Chicago avec « Acid Trax » (biographie officielle).","en":"Conversion to Chicago house via \"Acid Trax\" (official biography)."},{"date":"1988","fr":"Sunrise, premier grand rave ; Shoom.","en":"Sunrise, first big rave; Shoom."},{"date":"1989","fr":"Naissance de Perfecto.","en":"Perfecto launched."},{"date":"1991","fr":"Sortie de « I Want You (Forever) » ; n°23 au Royaume-Uni.","en":"\"I Want You (Forever)\" released; UK no. 23."},{"date":"1992","fr":"Second single, « Does It Feel Good to You », top 40.","en":"Second single \"Does It Feel Good to You\", UK top 40."}],"credits":[{"k":"artiste","v":"Carl Cox","k_en":"Artist","v_en":"Carl Cox"},{"k":"label","v":"Perfecto (Paul Oakenfold)","k_en":"Label","v_en":"Perfecto (Paul Oakenfold)"}],"book_refs":[{"source":"carl-cox-oh-yes","where":"Chapitres sur Sunrise 1988, The Project, la signature chez Perfecto et le premier single","where_en":"Chapters on Sunrise 1988, The Project, signing to Perfecto and the first single"},{"source":"class-of-88","where":"Contexte Sunrise et grandes raves","where_en":"Sunrise and big-rave context"}],"references":["https://www.insomniac.com/music/carl-cox-i-want-you-forever/","https://www.vice.com/en/article/the-arrival-carl-cox/","https://www.encyclopedia.com/education/news-wires-white-papers-and-books/cox-carl","https://banbantonton.com/2025/08/27/looking-for-the-balearic-beat-following-the-first-rush-part3-the-raid-yellow-book-boilerhouse-ophelia/"],"verify":["Place exacte au classement (22 ou 23)"],"pilot":true},{"id":"go-moby","title":"Go","artist":"Moby","year":1991,"label":"Instinct Records / Outer Rhythm (UK)","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"rave-jungle","era":"era-2","bpm":131,"camelot_key":"10A","energy":8,"gear":["Sampler","Synthés (cordes)"],"construction":"Le thème de « Laura Palmer » de la série Twin Peaks, samplé sur un beat rave, des stabs de piano et une voix qui crie « go ». Une techno cinématographique.","producer_origins":"Moby, DJ new-yorkais végétalien, chrétien et sobre, détonne dans la culture rave. Dans Porcelain, il raconte la pauvreté, les clubs de Manhattan et la scène des années 90.","club_sociology":"Le single atteint la 10e place au Royaume-Uni et la 1re des classements dance et indépendants de Music Week, alors qu'il plafonne au 18e rang du classement club de Billboard. Michaelangelo Matos montre que l'Amérique invente la techno mais la redécouvre via l'Europe.","queer_ballroom_axis":"Moby décrit dans Porcelain les clubs new-yorkais (Mars, Limelight) comme des espaces mixtes et queer où la rave américaine prend racine.","archive_ref":{"source":"porcelain","note":"Mémoires de Moby : New York, la rave et la pauvreté.","note_en":"Moby's memoir: New York, rave and poverty."},"why_this_record":"Il montre comment l'Amérique s'approprie la rave.","tags":["us","rave","sample"],"further_reading":["underground-massive"],"spotify":{"id":"2qWqHwZw7BErE6NddWaAuU"},"youtube":["NLCHARjjrws","o72NpKj0nxw","t5lP0I1lEmY"],"construction_en":"The \"Laura Palmer\" theme from Twin Peaks sampled over a rave beat, piano stabs and a voice shouting \"go\": cinematic techno.","producer_origins_en":"Moby, a vegan, Christian, sober New York DJ, stood out in rave culture. In Porcelain he recounts poverty, Manhattan's clubs and the 1990s scene.","club_sociology_en":"The single reached number 10 in the UK and number 1 on Music Week's dance and indie charts, while stalling at 18 on Billboard's club chart. Michaelangelo Matos shows America inventing techno, then rediscovering it through Europe.","queer_ballroom_axis_en":"In Porcelain, Moby describes New York clubs (Mars, Limelight) as mixed, queer spaces where American rave took root.","why_this_record_en":"It shows how America claimed rave for itself.","gear_en":["Sampler","Synths (strings)"],"verified":false,"story":"« Go » naît comme face B du premier single de Moby, « Mobility », sorti sur Instinct, petit label new-yorkais, à l'automne 1990. Moby refait ensuite le morceau autour d'un sample de « Laura Palmer's Theme », composé par Angelo Badalamenti pour la série Twin Peaks (bande originale parue en septembre 1990). Cette version sort en single en mars 1991 sur Instinct, et au Royaume-Uni via Outer Rhythm. Le disque devient numéro 1 des classements dance et indépendants de Music Week, puis entre au top 10 britannique à l'automne 1991, ce qui vaut à Moby un passage à Top of the Pops. Aux États-Unis, il reste au 18e rang du classement club de Billboard : l'Amérique de la rave le découvre surtout par l'Europe.","story_en":"\"Go\" began life as the B-side to Moby's first single, \"Mobility\", on the small New York label Instinct in autumn 1990. Moby then rebuilt it around a sample of \"Laura Palmer's Theme\", written by Angelo Badalamenti for Twin Peaks (soundtrack released September 1990). That version came out in March 1991 on Instinct, and in the UK through Outer Rhythm. It topped Music Week's dance and indie charts and entered the UK top 10 in autumn 1991, earning Moby a Top of the Pops slot. In the US it stalled at number 18 on Billboard's club chart: American rave found its audience largely through Europe.","timeline":[{"date":"1990-09/11","fr":"Sortie de « Mobility » (Instinct) avec « Go » en face B (les sources divergent entre septembre et novembre).","en":"\"Mobility\" released on Instinct with \"Go\" as B-side (sources disagree: September or November)."},{"date":"1990-09","fr":"Sortie de la bande originale de Twin Peaks (Badalamenti).","en":"Twin Peaks soundtrack released (Badalamenti)."},{"date":"1991-03","fr":"Sortie du single « Go » (version Twin Peaks) sur Instinct.","en":"\"Go\" single (Twin Peaks version) released on Instinct."},{"date":"1991-10/11","fr":"Entrée au top 10 britannique (n°10, semaine du 2 novembre selon la liste Wikipedia) ; n°1 Music Week Dance et Indie.","en":"UK top 10 (no. 10, week of 2 Nov per Wikipedia's list); no. 1 on Music Week Dance and Indie charts."},{"date":"1992-07","fr":"Sortie de l'album « Moby » (Instinct).","en":"Debut album \"Moby\" released (Instinct)."}],"credits":[{"k":"composition","v":"Moby, Angelo Badalamenti, David Lynch","k_en":"Composition","v_en":"Moby, Angelo Badalamenti, David Lynch"},{"k":"production","v":"Moby","k_en":"Production","v_en":"Moby"},{"k":"label","v":"Instinct (US) ; Outer Rhythm (UK)","k_en":"Label","v_en":"Instinct (US); Outer Rhythm (UK)"},{"k":"samples","v":"« Laura Palmer's Theme » (Badalamenti)","k_en":"Samples","v_en":"\"Laura Palmer's Theme\" (Badalamenti)"}],"book_refs":[{"source":"porcelain","where":"Chapitres 1989-1991 : Instinct, premiers disques, vie à New York","where_en":"Chapters on 1989–1991: Instinct, first records, New York life"},{"source":"underground-massive","where":"Passages sur la rave américaine et sa réception via l'Europe","where_en":"Passages on American rave and its reception via Europe"}],"references":["https://en.wikipedia.org/wiki/Go_(Moby_song)","https://en.wikipedia.org/wiki/Moby","https://en.wikipedia.org/wiki/Mobility_(song)","https://en.wikipedia.org/wiki/Soundtrack_from_Twin_Peaks","https://en.wikipedia.org/wiki/List_of_UK_top-ten_singles_in_1991"],"verify":["Date de sortie de « Mobility » : septembre ou novembre 1990","Passage exact de Porcelain sur Mars et Limelight (déjà cité par le site)"],"pilot":true},{"id":"music-bukem","title":"Music","artist":"LTJ Bukem","year":1993,"label":"Good Looking Records","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"rave-jungle","era":"era-2","bpm":165,"camelot_key":"6A","energy":5,"gear":["Breakbeats (time-stretch)","Nappes","Piano"],"construction":"Des breakbeats rapides mais feutrés, des nappes jazz et des nappes d'ambient : le drum & bass « atmosphérique ». Le tempo est double, mais l'émotion est deep house.","producer_origins":"Danny Williamson fonde Good Looking Records et défend un jungle intelligent et jazzy, en réaction à la noirceur du darkcore.","club_sociology":"Martin James retrace comment le hardcore se scinde vers 1993-1994 en jungle et drum & bass, entre sound systems caribéens, radio pirate et raves.","queer_ballroom_axis":"La jungle est une culture noire britannique, nourrie par le reggae et le sound system, plutôt que par les clubs queer.","archive_ref":{"source":"state-of-bass","note":"Les origines de la jungle et du drum & bass.","note_en":"The origins of jungle and drum & bass."},"why_this_record":"À 165 BPM, il prouve que la vitesse n'empêche pas la profondeur.","tags":["uk","black-british","deep"],"spotify":{"id":"61ah1tyKm4WgFz0RzAMv5j"},"youtube":["t3-VNrIoii4","GYKk6uJs6UQ","uiEXKp8N5FA"],"construction_en":"Fast but hushed breakbeats, jazz chords and ambient pads: \"atmospheric\" drum & bass. Double tempo, deep-house emotion.","producer_origins_en":"Danny Williamson founded Good Looking Records and championed an intelligent, jazzy jungle in reaction to darkcore's gloom.","club_sociology_en":"Martin James traces how hardcore split around 1993–1994 into jungle and drum & bass, between Caribbean sound systems, pirate radio and raves.","queer_ballroom_axis_en":"Jungle is a Black British culture fed by reggae and sound systems rather than by queer clubs.","why_this_record_en":"At 165 BPM it proves speed doesn't rule out depth.","city_en":"London","country_en":"United Kingdom","gear_en":["Breakbeats (time-stretched)","Pads","Piano"],"verified":false},{"id":"inner-city-life","title":"Inner City Life","artist":"Goldie presents Metalheadz","year":1994,"label":"FFRR","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"rave-jungle","era":"era-2","bpm":166,"camelot_key":"3A","energy":7,"gear":["Breakbeats (time-stretch)","Cordes","Voix soul"],"construction":"Des breakbeats découpés et étirés, des nappes de cordes et la voix soul de Diane Charlemagne. C'est la jungle devenue symphonie urbaine.","producer_origins":"Goldie, graffeur métis passé par les foyers de l'aide sociale à l'enfance dans les Midlands, fonde Metalheadz. Il fait de la jungle une musique d'auteur.","club_sociology":"Le single atteint la 39e place au Royaume-Uni et la 6e du classement dance ; l'album Timeless monte au n°7 en 1995. La jungle gagne une reconnaissance critique, et les soirées Metalheadz du dimanche au Blue Note, à Hoxton, commencent en juillet 1995.","queer_ballroom_axis":"Pas d'axe queer : la jungle se construit dans la culture noire britannique des sound systems.","archive_ref":{"source":"state-of-bass","note":"La jungle de Metalheadz et la reconnaissance critique.","note_en":"Metalheadz jungle and critical recognition."},"why_this_record":"C'est la jungle comme grande forme.","tags":["uk","black-british","rave"],"further_reading":["energy-flash","join-the-future"],"spotify":{"id":"0O7xFEqePrcTUgOi4qe0uB"},"youtube":["fRzjfOtsUcQ","i-P98B2skts","6vHkOI-Z7lY"],"construction_en":"Chopped, time-stretched breakbeats, string pads and Diane Charlemagne's soul vocal: jungle as urban symphony.","producer_origins_en":"Goldie, a mixed-race graffiti artist who grew up in children's homes in the Midlands, founded Metalheadz and turned jungle into auteur music.","club_sociology_en":"The single reached number 39 in the UK and number 6 on the dance chart; the album Timeless climbed to number 7 in 1995. Jungle won critical recognition, and Metalheadz's Sunday sessions at the Blue Note in Hoxton began in July 1995.","queer_ballroom_axis_en":"No queer axis: jungle was built within Black British sound-system culture.","why_this_record_en":"Jungle as a grand form.","city_en":"London","country_en":"United Kingdom","gear_en":["Breakbeats (time-stretched)","Strings","Soul vocal"],"verified":false,"story":"Clifford Price, dit Goldie, né à Walsall, vient du graffiti. Il débute sur Reinforced, invente avec « Terminator » (1992) une manière d'étirer les samples sans changer la hauteur, et fonde Metalheadz en 1994 avec Kemistry et Storm. « Inner City Life » (Price, Rob Playford) paraît chez FFRR le 21 novembre 1994, avec la voix de Diane Charlemagne. Il est le premier single de l'album Timeless (1995), dont le titre-suite dure 21 minutes. Le single atteint le n°39 au Royaume-Uni et le n°6 du classement dance. Les soirées du dimanche de Metalheadz au Blue Note, à Hoxton, commencent en juillet 1995.","story_en":"Clifford Price, known as Goldie, born in Walsall, came from graffiti. He started on Reinforced, pioneered with \"Terminator\" (1992) a way of stretching samples without changing pitch, and founded Metalheadz in 1994 with Kemistry and Storm. \"Inner City Life\" (Price, Rob Playford) was released on FFRR on 21 November 1994, with vocals by Diane Charlemagne. It is the first single from the album Timeless (1995), whose title suite runs 21 minutes. The single reached UK no. 39 and no. 6 on the dance chart. Metalheadz's Sunday sessions at the Blue Note in Hoxton began in July 1995.","timeline":[{"date":"1992","fr":"« Terminator » (Rufige Kru / Metalheads) sur Reinforced.","en":"\"Terminator\" (Rufige Kru / Metalheads) on Reinforced."},{"date":"1994","fr":"Fondation de Metalheadz.","en":"Metalheadz founded."},{"date":"1994-11-21","fr":"Sortie d'« Inner City Life » (FFRR).","en":"\"Inner City Life\" released (FFRR)."},{"date":"1995-07","fr":"Premières soirées Metalheadz au Blue Note.","en":"First Metalheadz sessions at the Blue Note."},{"date":"1995","fr":"Album Timeless, n°7 au Royaume-Uni.","en":"Album Timeless, UK no. 7."}],"credits":[{"k":"auteurs","v":"Clifford Price, Rob Playford","k_en":"Writers","v_en":"Clifford Price, Rob Playford"},{"k":"voix","v":"Diane Charlemagne","k_en":"Vocals","v_en":"Diane Charlemagne"},{"k":"label","v":"FFRR (FX 251)","k_en":"Label","v_en":"FFRR (FX 251)"},{"k":"remixes","v":"Roni Size & Krust, Peshay, 4hero, Nookie","k_en":"Remixes","v_en":"Roni Size & Krust, Peshay, 4hero, Nookie"},{"k":"album","v":"Timeless (1995)","k_en":"Album","v_en":"Timeless (1995)"}],"book_refs":[{"source":"state-of-bass","where":"Chapitres sur le passage du hardcore à la jungle et à la drum & bass, 1993-1994 (James)","where_en":"Chapters on the shift from hardcore to jungle and drum & bass, 1993–94 (James)"}],"references":["https://en.wikipedia.org/wiki/Inner_City_Life","https://en.wikipedia.org/wiki/Goldie","https://edm-ghost-production.com/blog/goldie-graffiti-to-drum-and-bass","https://www.edgepedia.org/goldie"],"verify":["Place exacte du single (n°39) : à confirmer sur Official Charts","Date de lancement des Blue Note sessions"],"pilot":true},{"id":"incredible","title":"Incredible","artist":"M-Beat feat. General Levy","year":1994,"label":"Renk Records","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"rave-jungle","era":"era-2","bpm":168,"camelot_key":"1A","energy":9,"gear":["Breakbeats (Amen)","Basse reggae"],"construction":"Des breaks hachés, une basse reggae énorme et le toasting dancehall de General Levy. Le ragga jungle dans sa forme la plus populaire.","producer_origins":"M-Beat, jeune producteur londonien, et General Levy, MC dancehall, réunissent la jungle et la culture sound system jamaïcaine.","club_sociology":"C'est un top 10 britannique en 1994. Le phénomène lance une polémique au sein de la scène sur la commercialisation de la jungle.","queer_ballroom_axis":"Le ragga jungle hérite aussi de la masculinité du dancehall ; il ne porte pas d'axe queer.","archive_ref":{"source":"state-of-bass","note":"Ragga jungle et polémiques de 1994.","note_en":"Ragga jungle and the controversies of 1994."},"why_this_record":"Il montre que la jungle vient du sound system jamaïcain.","tags":["uk","black-british","rave"],"further_reading":["energy-flash"],"spotify":{"id":"2Q9F3D53QeclwbsY24cuxO"},"youtube":["_YGbDEUVibE","mL2Bgj-za5k","7Fm2V20gZhM"],"construction_en":"Chopped breaks, a huge reggae bassline and General Levy's dancehall toasting: ragga jungle at its most popular.","producer_origins_en":"M-Beat, a young London producer, and General Levy, a dancehall MC, brought jungle and Jamaican sound-system culture together.","club_sociology_en":"A UK top 10 in 1994, it sparked a row within the scene over jungle's commercialisation.","queer_ballroom_axis_en":"Ragga jungle also inherited dancehall's masculinity; it carries no queer axis.","why_this_record_en":"It shows jungle comes from the Jamaican sound system.","city_en":"London","country_en":"United Kingdom","gear_en":["Breakbeats (Amen)","Reggae bassline"],"verified":false},{"id":"age-of-love","title":"The Age of Love (Jam & Spoon Watch Out for Stella Mix)","artist":"Age of Love","year":1992,"label":"Diki Records","city":"Bruxelles","country":"Belgique","continent":"Europe","genre":"trance","era":"era-2","bpm":132,"camelot_key":"6A","energy":8,"gear":["Synthétiseurs (arpèges)","tr-909"],"construction":"Une voix féminine hypnotique, une 909 qui roule et des arpèges qui montent en spirale. Le remix de Jam & Spoon pose la grammaire de la trance : montée, break, envolée.","producer_origins":"Le projet est italo-belge (Bruno Sanchioni). Le remix de Jam & Spoon, duo de Francfort, transforme une chanson de club en prototype trance.","club_sociology":"La trance naît au début des années 90 entre les clubs allemands (Omen et Dorian Gray à Francfort, Tresor à Berlin) et les pistes britanniques et d'Ibiza. Le livre Hypnotised retrace cet essor européen, jusqu'aux grands rassemblements néerlandais.","queer_ballroom_axis":"Pas d'ancrage queer explicite. La trance construit une utopie collective d'euphorie plutôt qu'une identité de communauté.","archive_ref":{"source":"hypnotised","note":"Les débuts de la trance et de la progressive house en Europe.","note_en":"The beginnings of trance and progressive house in Europe."},"why_this_record":"Le premier disque de trance au sens moderne.","tags":["europe","rave"],"further_reading":["energy-flash","techno-shuffle"],"spotify":{"id":"4u88MrYJ8ZCnmUdjITNGKz","version":"Jam & Spoon Watch Out for Stella Mix"},"youtube":["-ubrhlYVv2k","I4Et0DJ2L8k","xv412YPeTTE"],"construction_en":"A hypnotic female voice, a rolling 909 and spiralling arpeggios. Jam & Spoon's remix sets trance's grammar: build, break, lift-off.","producer_origins_en":"An Italo-Belgian project (Bruno Sanchioni). The remix by Frankfurt duo Jam & Spoon turned a club song into a trance prototype.","club_sociology_en":"Trance emerged in the early 90s between German clubs (Omen and Dorian Gray in Frankfurt, Tresor in Berlin) and British and Ibizan dancefloors. Hypnotised traces this European rise, all the way to the big Dutch gatherings.","queer_ballroom_axis_en":"No explicit queer anchoring. Trance builds a collective utopia of euphoria rather than a community identity.","why_this_record_en":"The first trance record in the modern sense.","city_en":"Brussels","country_en":"Belgium","gear_en":["Synthesizers (arpeggios)","tr-909"],"verified":false},{"id":"cafe-del-mar","title":"Café del Mar","artist":"Energy 52","year":1993,"label":"Eye Q Records","city":"Francfort","country":"Allemagne","continent":"Europe","genre":"trance","era":"era-2","bpm":133,"camelot_key":"9A","energy":7,"gear":["Synthétiseurs","Séquenceur"],"construction":"Une mélodie méditerranéenne, des arpèges qui s'empilent et une montée lente. Le titre rend hommage au bar d'Ibiza où l'on regarde le coucher du soleil.","producer_origins":"Paul Schmitz-Moormann et Harald Blüchel (Cosmic Baby) travaillent pour Eye Q, le label de Sven Väth à Francfort.","club_sociology":"Le morceau sera remixé et réédité à de nombreuses reprises et devient un classique des clubs d'Ibiza. Il relie la trance allemande au balearic.","queer_ballroom_axis":"Ibiza, avec son héritage d'hédonisme mixte, est la toile de fond : pas d'axe queer propre au disque.","archive_ref":{"source":"hypnotised","note":"Ibiza et l'âge d'or de la trance européenne.","note_en":"Ibiza and the golden age of European trance."},"why_this_record":"Le pont entre le balearic et la trance.","tags":["europe","sunrise"],"further_reading":["carl-cox-oh-yes","rave-on"],"spotify":{"id":"3CleFb6zdsgndKKHgE3DJc","version":"remix Three 'N One (original indisponible)"},"youtube":["JKbujL0BmKo","9o2cV-FpoHo","uTA4C5QwZEg"],"construction_en":"A Mediterranean melody, stacking arpeggios and a slow build. The title pays homage to the Ibiza bar where people watch the sunset.","producer_origins_en":"Paul Schmitz-Moormann and Harald Blüchel (Cosmic Baby) worked for Eye Q, Sven Väth's Frankfurt label.","club_sociology_en":"Remixed and reissued many times, it became an Ibiza club classic, linking German trance to balearic.","queer_ballroom_axis_en":"Ibiza, with its legacy of mixed hedonism, is the backdrop: the record itself has no queer axis.","why_this_record_en":"The bridge between balearic and trance.","city_en":"Frankfurt","country_en":"Germany","gear_en":["Synthesizers","Sequencer"],"verified":false},{"id":"for-an-angel","title":"For an Angel","artist":"Paul van Dyk","year":1994,"label":"MFS","city":"Berlin","country":"Allemagne","continent":"Europe","genre":"trance","era":"era-2","bpm":138,"camelot_key":"11B","energy":8,"gear":["Synthétiseurs","Séquenceur"],"construction":"Des accords majeurs lumineux, une mélodie de synthé portée par une basse en arpège : la trance euphorique berlinoise.","producer_origins":"Paul van Dyk a grandi à Berlin-Est. La musique occidentale y passait en cachette par la radio. La chute du Mur lui ouvre les clubs.","club_sociology":"Berlin réunifié devient une capitale de la nuit grâce aux bâtiments vides de l'Est. La Love Parade attire des centaines de milliers de personnes.","queer_ballroom_axis":"La scène berlinoise a des racines queer fortes, mais la trance de stade de la fin des années 90 se détache de ces origines.","archive_ref":{"source":"rave-on","note":"Berlin après le Mur.","note_en":"Berlin after the Wall."},"why_this_record":"La trance comme bande-son de la réunification.","tags":["europe","rave"],"further_reading":["hypnotised","techno-shuffle"],"spotify":{"id":"3PbDqZ1VMsBTjXCbs6Jv7P"},"youtube":["--3eIRSg2RY","lBKtD9TdVrI"],"construction_en":"Bright major chords, a synth melody carried by an arpeggiated bass: euphoric Berlin trance.","producer_origins_en":"Paul van Dyk grew up in East Berlin, where Western music arrived secretly over the radio. The fall of the Wall opened the clubs to him.","club_sociology_en":"Reunified Berlin became a capital of the night thanks to the East's empty buildings. The Love Parade drew hundreds of thousands.","queer_ballroom_axis_en":"Berlin's scene has strong queer roots, but late-90s stadium trance drifted away from them.","why_this_record_en":"Trance as the soundtrack of reunification.","country_en":"Germany","gear_en":["Synthesizers","Sequencer"],"verified":false},{"id":"children","title":"Children","artist":"Robert Miles","year":1995,"label":"DBX / Deconstruction","city":"Fagagna (Frioul)","country":"Italie","continent":"Europe","genre":"trance","era":"era-2","bpm":137,"camelot_key":"8A","energy":6,"gear":["Piano","Synthétiseurs"],"construction":"Une mélodie de piano simple, une basse en arpège et un kick régulier. C'est la « dream house », une trance mélodique et douce.","producer_origins":"Roberto Concina, né en Suisse et installé à Fagagna (Frioul), a donné deux raisons au morceau : des photos d'enfants victimes de la guerre de Bosnie, et le désir d'un disque calme de fin de soirée pour réduire les accidents de la route des jeunes Italiens sortant de club.","club_sociology":"Sorti en Italie en janvier 1995 sur DBX, il se vend peu avant d'être licencié par Platipus puis Deconstruction. Il devient ensuite un succès mondial (n°1 du classement dance de Billboard en 1996) : la trance devient de la pop européenne.","queer_ballroom_axis":"Sans axe queer propre, c'est une rêverie collective et apolitique.","archive_ref":{"source":"hypnotised","note":"La dream house et la trance mélodique devenue pop européenne.","note_en":"Dream house and melodic trance turned European pop."},"why_this_record":"On sent ici la house devenue berceuse.","tags":["europe","chill"],"spotify":{"id":"3zZCK9CqutoHe93hYO7Ksa","version":"Dream Version"},"youtube":["CC5ca6Hsb2Q","kc7X3q27b34","rxjOH8ykvh4"],"further_reading":["techno-shuffle"],"construction_en":"A simple piano melody, an arpeggiated bass and a steady kick: \"dream house\", melodic and gentle trance.","producer_origins_en":"Roberto Concina, born in Switzerland and based in Fagagna (Friuli), gave two reasons for the track: photographs of children who were victims of the Bosnian war, and the wish for a calm end-of-night record to reduce road deaths among young Italians leaving clubs.","club_sociology_en":"Released in Italy in January 1995 on DBX, it sold little before being licensed by Platipus, then Deconstruction. It went on to become a worldwide hit (number 1 on Billboard's dance chart in 1996): trance turned into European pop.","queer_ballroom_axis_en":"With no queer axis of its own, it is a collective, apolitical reverie.","why_this_record_en":"House turned lullaby.","city_en":"Fagagna (Friuli)","country_en":"Italy","gear_en":["Piano","Synthesizers"],"verified":false,"story":"Roberto Concina, né en Suisse à Fleurier et installé à Fagagna (Frioul), enregistre « Children » en 1994 pour environ 150 livres. Il l'a pensé de deux façons : en réponse à des photos d'enfants victimes de la guerre de Bosnie, et comme disque de fin de soirée, calme, pour réduire les accidents de la route des ravers italiens (la « strage del sabato sera »). Il le vend au label DBX de Joe Vanelli ; l'EP Soundtracks sort en janvier 1995 et se vend peu (environ 3 000 exemplaires selon une source). Vanelli le joue à Miami, au club Kimbo ; Platipus le licencie puis le cède à Deconstruction, dont l'A&R est Mike Pickering. Plus de cinq millions d'exemplaires, treize semaines n°1 du classement européen, n°1 du classement dance de Billboard en 1996.","story_en":"Roberto Concina, born in Fleurier, Switzerland and based in Fagagna (Friuli), recorded \"Children\" in 1994 for around £150. He conceived it in two ways: as a response to photos of child victims of the Bosnian war, and as a calm end-of-night record to reduce road deaths among Italian ravers (the \"strage del sabato sera\"). He sold it to Joe Vanelli's DBX label; the Soundtracks EP came out in January 1995 and sold poorly (about 3,000 copies per one source). Vanelli played it in Miami at the club Kimbo; Platipus licensed it and passed it to Deconstruction, whose A&R was Mike Pickering. Over five million copies sold, thirteen weeks at no. 1 on the European chart, no. 1 on Billboard's dance chart in 1996.","timeline":[{"date":"1994","fr":"Enregistrement à Fagagna.","en":"Recorded in Fagagna."},{"date":"1995-01","fr":"Sortie italienne sur DBX (EP Soundtracks).","en":"Italian release on DBX (EP Soundtracks)."},{"date":"1995","fr":"Licence Platipus puis Deconstruction après le club Kimbo (Miami).","en":"Platipus licence then Deconstruction after Kimbo (Miami)."},{"date":"1996","fr":"Succès mondial ; album Dreamland.","en":"Worldwide success; album Dreamland."},{"date":"2017-05-09","fr":"Mort de Robert Miles à Ibiza.","en":"Robert Miles dies in Ibiza."}],"credits":[{"k":"auteur","v":"Roberto Concina","k_en":"Writer","v_en":"Roberto Concina"},{"k":"production","v":"Robert Miles","k_en":"Production","v_en":"Robert Miles"},{"k":"label","v":"DBX (Italie), Deconstruction (UK), Arista (US)","k_en":"Label","v_en":"DBX (Italy), Deconstruction (UK), Arista (US)"},{"k":"studio","v":"Sound Master Studio (Italie)","k_en":"Studio","v_en":"Sound Master Studio (Italy)"},{"k":"versions","v":"Dream Version, original mix (7'16), radio edit","k_en":"Versions","v_en":"Dream Version, original mix (7'16), radio edit"}],"book_refs":[{"source":"hypnotised","where":"Chapitres sur la dream trance et le succès de Children, 1995-1996 (Rietveld)","where_en":"Chapters on dream trance and the success of Children, 1995–96 (Rietveld)"}],"references":["https://www.bbc.co.uk/news/entertainment-arts-39871459","https://en.wikipedia.org/wiki/Robert_Miles","https://www.insomniac.com/music/from-the-crate-robert-miles-children/","https://www.wikiwand.com/en/articles/Children_(composition)","https://www.edgepedia.org/robert-miles"],"verify":["Chiffres de ventes de l'EP original","Date de sortie britannique : fin 1995 ou mars 1996"],"pilot":true},{"id":"alabama-blues","title":"Alabama Blues","artist":"St Germain","year":1995,"label":"F Communications","city":"Paris","country":"France","continent":"Europe","genre":"french-touch","era":"era-2","bpm":122,"camelot_key":"7A","energy":5,"gear":["Sampler","Samples de blues"],"construction":"Une rythmique deep house souple, des samples de blues et de voix afro-américaines, des nappes jazz : la house parisienne côté jazz, loin du filtre disco.","producer_origins":"Ludovic Navarre, autodidacte de la banlieue parisienne, produit sur F Communications, le label de Laurent Garnier et Éric Morand. Il aborde la house en mélomane du jazz et du blues.","club_sociology":"L'album « Boulevard » devient un succès d'écoute domestique autant que de club. Il ouvre la voie à une house « lounge » qui s'écoute dans les bars et les appartements.","queer_ballroom_axis":"Pas d'axe queer explicite. Le disque cite la musique noire américaine comme une archive, une question récurrente de la scène française.","archive_ref":{"source":"musique-house-bidder","note":"La French Touch selon Bidder : Garnier, Dimitri from Paris, Ludovic Navarre.","note_en":"The French Touch according to Bidder: Garnier, Dimitri from Paris, Ludovic Navarre."},"why_this_record":"Il montre l'autre French Touch : deep, jazz et feutrée.","tags":["europe","jazz","deep","sample"],"further_reading":["electrochoc"],"spotify":{"id":"5hneuUsMI39tfqc7GkpLvZ","version":"1965 Mix"},"youtube":["p2npPILYhsM","92aJ3hb4VMU","Lvx1Cs0iaIo"],"construction_en":"A supple deep-house groove, blues samples and African-American voices, jazz pads: the jazz side of Paris house, far from the disco filter.","producer_origins_en":"Ludovic Navarre, self-taught and from the Paris suburbs, released on F Communications, Laurent Garnier and Éric Morand's label. He approached house as a jazz and blues lover.","club_sociology_en":"The album Boulevard became a home-listening success as much as a club one, opening the way for a \"lounge\" house heard in bars and flats.","queer_ballroom_axis_en":"No explicit queer axis. The record quotes Black American music as an archive, a recurring question for the French scene.","why_this_record_en":"The other French Touch: deep, jazzy and hushed.","gear_en":["Sampler","Blues samples"],"verified":false},{"id":"beautiful-people","title":"Beautiful People","artist":"Barbara Tucker","year":1994,"label":"Strictly Rhythm","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-2","bpm":125,"camelot_key":"9A","energy":8,"gear":["Orgue","Boîte à rythmes"],"construction":"Un groove garage nerveux, des riffs d'orgue et la voix gospel de Barbara Tucker qui appelle la piste. C'est le garage new-yorkais des années 90 dans sa forme la plus festive.","producer_origins":"Production de Little Louie Vega (Masters At Work) pour Strictly Rhythm, le label new-yorkais qui domine la house américaine de la décennie. Tucker est aussi danseuse et organisatrice de soirées.","club_sociology":"C'est l'âge d'or du garage new-yorkais (Sound Factory, Sound Factory Bar, Shelter), avant les fermetures des années Giuliani que DJ Disciple raconte comme la « chute » de la scène.","queer_ballroom_axis":"Le titre et le refrain célèbrent la beauté collective de la piste. C'est un hymne des clubs gays et mixtes de Manhattan, porté par une diva gospel.","archive_ref":{"source":"beat-scene-sound","note":"Le New York house des années 90, de l'intérieur.","note_en":"1990s New York house, from the inside."},"why_this_record":"Il fait entendre le New York des années 90 avant la fermeture des clubs.","tags":["us","diva","gospel","queer"],"further_reading":["decade-house-bleakman","you-better-work"],"spotify":{"id":"0yMeUdXZmUjLpURNnyqRZY","version":"Underground Network Mix"},"youtube":["Qf8_L3R9GqI","cAicP_hZzXs","oNDaholHRpE"],"construction_en":"A nervy garage groove, organ riffs and Barbara Tucker's gospel voice calling the floor: 1990s New York garage at its most festive.","producer_origins_en":"Produced by Little Louie Vega (Masters At Work) for Strictly Rhythm, the New York label that dominated American house that decade. Tucker was also a dancer and party promoter.","club_sociology_en":"The golden age of New York garage (Sound Factory, Sound Factory Bar, Shelter), before the Giuliani-era closures that DJ Disciple describes as the scene's \"fall\".","queer_ballroom_axis_en":"Title and chorus celebrate the collective beauty of the dancefloor: an anthem of Manhattan's gay and mixed clubs, carried by a gospel diva.","why_this_record_en":"It lets you hear 1990s New York before the clubs closed.","gear_en":["Organ","Drum machine"],"verified":false},{"id":"blue-monday","title":"Blue Monday","artist":"New Order","year":1983,"label":"Factory Records (FAC 73)","city":"Manchester","country":"Royaume-Uni","country_en":"United Kingdom","continent":"Europe","genre":"electro","era":"era-1","gear":["Oberheim DMX","Moog Source","Emulator 1"],"gear_en":["Oberheim DMX","Moog Source","Emulator 1"],"construction":"Une boîte à rythmes Oberheim DMX programmée à la main, un long motif de basse séquencé, et un groupe de rock qui assume de se faire remplacer par des machines. Le disque doit beaucoup à Kraftwerk, à Donna Summer et au disco-électro new-yorkais que le groupe écoute à Manhattan.","construction_en":"An Oberheim DMX drum machine programmed by hand, a long sequenced bassline, and a rock band choosing to be replaced by machines. The record owes a lot to Kraftwerk, Donna Summer and the New York electro-disco the band heard in Manhattan.","producer_origins":"New Order naît des cendres de Joy Division après la mort d'Ian Curtis en 1980. Peter Hook, Bernard Sumner, Stephen Morris et Gillian Gilbert passent du post-punk à la danse en découvrant les clubs new-yorkais, et produisent eux-mêmes le morceau.","producer_origins_en":"New Order rose from the ashes of Joy Division after Ian Curtis's death in 1980. Peter Hook, Bernard Sumner, Stephen Morris and Gillian Gilbert moved from post-punk to dance music after discovering New York's clubs, and produced the track themselves.","club_sociology":"Factory finance l'Haçienda, ouverte en mai 1982, qui perd de l'argent pendant des années. « Blue Monday » est présenté comme le 12 pouces le plus vendu de tous les temps. Selon Tony Wilson, sa pochette découpée en disquette faisait perdre 5 pence par exemplaire, une légende que Peter Saville dit ne plus supporter.","club_sociology_en":"Factory funded the Haçienda, which opened in May 1982 and lost money for years. \"Blue Monday\" is described as the best-selling 12\" of all time. According to Tony Wilson its die-cut floppy-disk sleeve lost 5 pence on every copy, a legend Peter Saville says he is tired of.","queer_ballroom_axis":"Le morceau puise dans l'électro-disco et le hi-NRG des clubs gays new-yorkais (Sylvester, Donna Summer), mais New Order n'en parle presque jamais comme dette. Un angle à documenter plutôt qu'à affirmer.","queer_ballroom_axis_en":"The track draws on electro-disco and hi-NRG from New York gay clubs (Sylvester, Donna Summer), yet New Order rarely frames that as a debt. An angle to document rather than assert.","why_this_record":"Le pont entre le post-punk mancunien et la house, un an avant le premier maxi house de Chicago.","why_this_record_en":"The bridge between Manchester post-punk and house, a year before Chicago's first house 12\".","archive_ref":{"source":"hacienda-hook","note":"Chapitres sur l'ouverture et l'économie de l'Haçienda.","note_en":"Chapters on the Haçienda's opening and economics."},"further_reading":["sonic-youth-floor","hacienda-hook","adventures-wonderland"],"verify":["Chiffres de pertes (5 pence) : légende contestée par Saville","Part du chœur « Uranium » : lire la note Wikipedia à sa source"],"bpm":130,"camelot_key":"7A","energy":8,"verified":false,"continent_en":"Europe","tags":["uk","machine","crossover"],"youtube":["c1GxjzHm5us","W2e2Nw8oTgc"],"spotify":{"id":"6hHc7Pks7wtBIW8Z6A0iFq"},"story":"Le 12 pouces sort le 7 mars 1983 chez Factory (FAC 73). New Order a joué à New York en 1981 et découvert le post-disco, le freestyle et l'électro ; le groupe écoute aussi du disco italien. Après le départ de Martin Hannett, il se produit lui-même. Le morceau repose sur une boîte à rythmes Oberheim DMX, une basse sur Moog Source pilotée par un séquenceur construit par Bernard Sumner, et un Emulator 1, avec des chœurs de « Uranium » de Kraftwerk. La pochette, découpée comme une disquette, coûtait si cher que Factory aurait perdu 5 pence par exemplaire (Tony Wilson) ; Peter Saville dit n'en plus pouvoir de cette histoire. C'est le 12 pouces le plus vendu de tous les temps. Il aide à financer l'Haçienda, ouvert en mai 1982, qui perd de l'argent.","story_en":"The 12-inch came out on 7 March 1983 on Factory (FAC 73). New Order had played New York in 1981 and discovered post-disco, freestyle and electro; the band also listened to Italian disco. After Martin Hannett left, they produced themselves. The track rests on an Oberheim DMX drum machine, a Moog Source bassline driven by a sequencer built by Bernard Sumner, and an Emulator 1, with choir sounds from Kraftwerk's \"Uranium\". The sleeve, die-cut like a floppy disk, cost so much that Factory reportedly lost 5p per copy (Tony Wilson); Peter Saville says he is bored of the story. It is the best-selling 12-inch of all time. It helped fund the Haçienda, opened in May 1982, which lost money.","timeline":[{"date":"1981","fr":"Séjour new-yorkais de New Order ; départ de Hannett du projet Temptation.","en":"New Order's New York stay; Hannett leaves during Temptation."},{"date":"1982-05-21","fr":"Ouverture de l'Haçienda (FAC 51).","en":"Haçienda opens (FAC 51)."},{"date":"1983-03-07","fr":"Sortie de « Blue Monday » (FAC 73).","en":"\"Blue Monday\" released (FAC 73)."},{"date":"1988","fr":"Reprise « Blue Monday 1988 » (FAC 73R), remix Quincy Jones et John Potoker.","en":"\"Blue Monday 1988\" (FAC 73R), remixed by Quincy Jones and John Potoker."},{"date":"1989","fr":"808 State enregistre une version acid, jouée aux nuits Hot.","en":"808 State records an acid version, played at Hot nights."}],"credits":[{"k":"auteurs","v":"Gillian Gilbert, Peter Hook, Stephen Morris, Bernard Sumner","k_en":"Writers","v_en":"Gillian Gilbert, Peter Hook, Stephen Morris, Bernard Sumner"},{"k":"production","v":"New Order","k_en":"Production","v_en":"New Order"},{"k":"studio","v":"Britannia Row, Islington","k_en":"Studio","v_en":"Britannia Row, Islington"},{"k":"machines","v":"Oberheim DMX, Moog Source, Emulator 1","k_en":"Machines","v_en":"Oberheim DMX, Moog Source, Emulator 1"},{"k":"pochette","v":"Peter Saville, Brett Wickens","k_en":"Sleeve","v_en":"Peter Saville, Brett Wickens"}],"book_refs":[{"source":"hacienda-hook","where":"Chapitres 1982-1983 : ouverture de l'Haçienda, finances, « Blue Monday »","where_en":"Chapters on 1982–83: Haçienda opening, finances, \"Blue Monday\""},{"source":"sonic-youth-floor","where":"Haslam sur la scène mancunienne avant l'acid","where_en":"Haslam on Manchester's pre-acid scene"}],"references":["https://en.wikipedia.org/wiki/Blue_Monday_(New_Order_song)","https://en.wikipedia.org/wiki/Factory_Records","https://en.wikipedia.org/wiki/The_Ha%C3%A7ienda","https://en.wikipedia.org/wiki/New_Order_(band)","https://en.wikipedia.org/wiki/808_State","https://en.wikipedia.org/wiki/Oberheim_DMX"],"pilot":true},{"id":"planet-rock","title":"Planet Rock","artist":"Afrika Bambaataa & The Soulsonic Force","year":1982,"label":"Tommy Boy Records","city":"New York (Bronx)","city_en":"New York (Bronx)","country":"USA","continent":"Amérique du Nord","genre":"electro","era":"era-1","gear":["tr-808","Synthétiseurs (Arthur Baker, John Robie)"],"gear_en":["tr-808","Synthesizers (Arthur Baker, John Robie)"],"construction":"La mélodie de « Trans-Europe Express » et le rythme de « Numbers » de Kraftwerk rejoués, une TR-808 qui pousse les basses, et des voix rap lancées comme un appel à la fête. Kraftwerk n'a d'abord pas été crédité ; un accord a suivi.","construction_en":"The melody of Kraftwerk's \"Trans-Europe Express\" and the beat of \"Numbers\", replayed, a TR-808 pushing the low end, and rap vocals thrown out like a party call. Kraftwerk was not credited at first; a settlement followed.","producer_origins":"Afrika Bambaataa vient du Bronx, ancien chef de gang devenu fondateur de la Universal Zulu Nation. Arthur Baker et John Robie, producteurs de Tommy Boy, assemblent le disque.","producer_origins_en":"Afrika Bambaataa came from the Bronx, a former gang leader who founded the Universal Zulu Nation. Arthur Baker and John Robie, Tommy Boy producers, built the record.","club_sociology":"Le Bronx des block parties et les clubs du downtown new-yorkais mêlent hip-hop, disco et new wave. L'électro de Planet Rock ouvre la voie à celle de Detroit, dont Cybotron sera l'un des premiers échos.","club_sociology_en":"The Bronx of block parties and downtown New York clubs mixed hip-hop, disco and new wave. Planet Rock's electro opened the way for Detroit's, of which Cybotron would be one of the first echoes.","queer_ballroom_axis":"Pas d'axe queer explicite dans le disque. À contextualiser par les clubs downtown (Paradise Garage, Danceteria) où l'électro circule.","queer_ballroom_axis_en":"No explicit queer axis in the record itself. To be framed through downtown clubs (Paradise Garage, Danceteria) where electro circulated.","why_this_record":"Un chaînon décisif : l'électro relie Kraftwerk, le hip-hop et la future techno.","why_this_record_en":"A decisive link: electro connects Kraftwerk, hip-hop and the techno to come.","archive_ref":{"source":"techno-rebels","note":"Détroit et l'influence de l'électro new-yorkais.","note_en":"Detroit and the influence of New York electro."},"further_reading":["techno-rebels","last-night-dj","modulations"],"verify":["crédits de production exacts","date de sortie (1982) et numéro de catalogue","accord de crédit avec Kraftwerk"],"bpm":127,"camelot_key":"9A","energy":8,"verified":false,"continent_en":"North America","tags":["us","machine","roots"],"youtube":["9J3lwZjHenA","_rlUQsC8ECk","wXsqzTL6le8"],"spotify":{"id":"5aD3fAa1fy8XUesj3lgr19","version":"Original 12\" Version"}},{"id":"ten-percent","title":"Ten Percent (Walter Gibbons Remix)","artist":"Double Exposure","year":1976,"label":"Salsoul Records","city":"Philadelphie / New York","city_en":"Philadelphia / New York","country":"USA","continent":"Amérique du Nord","genre":"disco","era":"era-1","gear":["Bandes magnétiques (découpe au rasoir)","Section rythmique live"],"gear_en":["Tape reels (razor-blade edits)","Live rhythm section"],"construction":"Walter Gibbons ne remixe pas, il redécoupe : il isole les percussions et les breaks sur bande et transforme les 6'51 de l'album en un mix de près de dix minutes. Sorti en mai 1976, c'est le premier 12 pouces vendu dans le commerce (des promos 12 pouces circulaient en club depuis 1975).","construction_en":"Walter Gibbons did not just remix, he re-cut: isolating percussion and breaks on tape, he turned the album's 6:51 into a mix of nearly ten minutes. Released in May 1976, it was the first 12\" sold commercially (12\" promos had circulated in clubs since 1975).","producer_origins":"Double Exposure est un groupe vocal de Philadelphie. Gibbons, DJ new-yorkais, s'est fait connaître par ses mixes en club avant d'être embauché par Salsoul.","producer_origins_en":"Double Exposure was a Philadelphia vocal group. Gibbons, a New York DJ, built his name through club mixing before Salsoul hired him.","club_sociology":"C'est l'époque où Vince Aletti raconte dans Record World ce que jouent les DJs de New York. Le 12\" naît de la demande des DJs : plus de volume, plus de durée, plus de basses sur le sillon.","club_sociology_en":"This is when Vince Aletti was reporting in Record World what New York DJs were playing. The 12\" came out of DJ demand: more volume, more length, more bass in the groove.","queer_ballroom_axis":"Le public des clubs où Gibbons passe ce disque est majoritairement noir, latino et gay ; les DJs y sont les premiers prescripteurs, avant la radio.","queer_ballroom_axis_en":"The audience of the clubs where Gibbons played this record was largely Black, Latino and gay; DJs were the first tastemakers, ahead of radio.","why_this_record":"L'acte de naissance du remix de club en format maxi.","why_this_record_en":"The birth certificate of the club remix on a 12-inch.","archive_ref":{"source":"disco-files","note":"Colonnes 1976 sur les DJs new-yorkais.","note_en":"1976 columns on New York DJs."},"further_reading":["disco-files","last-night-dj","hot-stuff","love-saves-the-day"],"verify":["Durée exacte de la face A (9'42 ou 9'48)","Rôle précis de Bob Blank (Lawrence) vs mix de Cayre"],"bpm":120,"camelot_key":"4B","energy":7,"verified":false,"continent_en":"North America","tags":["roots","disco","queer","us"],"youtube":["cCz8Kunyjlk","4YglhzH0vUk","g-J9mA0DS3Q"],"spotify":{"id":"4HCAvS6Mzk0LuHkzpD2c3z","version":"Walter Gibbons 12\" Mix"},"story":"Double Exposure, quatuor vocal de Philadelphie (anciennement United Image), enregistre « Ten Percent » (Allan Felder, T.G. Conway ; production Norman Harris) pour Salsoul, dont c'est la huitième référence. Le patron du label, Ken Cayre, voit Walter Gibbons manipuler deux exemplaires d'une promo 12 pouces et lui demande de refaire le travail en studio avec l'ingénieur Bob Blank. Gibbons transforme les 6'51 de l'album en un mix de 9'42 (mix de Cayre en face B, 7'31), commencé sur acétate fin février-mars 1976. Le 12 pouces sort en mai 1976, un mois après le 7 pouces qui se vendait mal. C'est le premier 12 pouces vendu dans le commerce. Il atteint le n°2 du classement disco de Billboard ; Felder déteste le remix.","story_en":"Double Exposure, a Philadelphia vocal quartet (formerly United Image), recorded \"Ten Percent\" (Allan Felder, T.G. Conway; produced by Norman Harris) for Salsoul, the label's eighth release. Label boss Ken Cayre watched Walter Gibbons work two copies of a promo 12-inch and asked him to repeat it in the studio with engineer Bob Blank. Gibbons turned the album's 6:51 into a 9:42 mix (Cayre's mix on the B-side, 7:31), started on acetate in late February–March 1976. The 12-inch came out in May 1976, a month after the poorly selling 7-inch. It was the first 12-inch sold commercially. It reached no. 2 on Billboard's disco chart; Felder hated the remix.","timeline":[{"date":"1975","fr":"Premiers acétates et promos 12 pouces diffusés en clubs (Tom Moulton).","en":"First 12-inch acetates and promos circulate in clubs (Tom Moulton)."},{"date":"1976-02/03","fr":"Gibbons commence son mix sur acétate.","en":"Gibbons starts his mix on acetate."},{"date":"1976-04","fr":"Sortie du 7 pouces, ventes lentes.","en":"7-inch released, slow sales."},{"date":"1976-05","fr":"Sortie du 12 pouces Salsoul (12D-2008), le premier commercialisé.","en":"Salsoul 12-inch (12D-2008) released, the first commercial one."},{"date":"1976","fr":"Prix Billboard Disco Forum pour Salsoul.","en":"Salsoul wins Billboard Disco Forum awards."}],"credits":[{"k":"auteurs","v":"Allan Felder, T.G. Conway","k_en":"Writers","v_en":"Allan Felder, T.G. Conway"},{"k":"production","v":"Baker, Harris & Young (Norman Harris)","k_en":"Production","v_en":"Baker, Harris & Young (Norman Harris)"},{"k":"remix","v":"Walter Gibbons","k_en":"Remix","v_en":"Walter Gibbons"},{"k":"mix face B","v":"Ken Cayre","k_en":"B-side mix","v_en":"Ken Cayre"},{"k":"ingénieur","v":"Bob Blank","k_en":"Engineer","v_en":"Bob Blank"},{"k":"label","v":"Salsoul (12D-2008)","k_en":"Label","v_en":"Salsoul (12D-2008)"}],"book_refs":[{"source":"disco-files","where":"Colonnes de 1976 sur les DJs new-yorkais et la naissance du 12 pouces","where_en":"1976 columns on New York DJs and the birth of the 12-inch"},{"source":"love-saves-the-day","where":"Passages sur Gibbons, Salsoul et le remix (Lawrence)","where_en":"Passages on Gibbons, Salsoul and the remix (Lawrence)"},{"source":"hot-stuff","where":"Chapitre sur l'industrie disco et les formats","where_en":"Chapter on the disco industry and formats"}],"references":["https://en.wikipedia.org/wiki/Ten_Percent_(song)","https://en.wikipedia.org/wiki/Twelve-inch_single","https://www.timlawrence.info/articles2/2013/7/16/walter-gibbons-jungle-music-strut-2010","https://www.allmusic.com/artist/double-exposure-mn0000192288","https://jahsonic.com/WalterGibbons.html"],"pilot":true},{"id":"is-it-all-over-my-face","title":"Is It All Over My Face (Female Vocal)","artist":"Loose Joints","year":1980,"label":"West End Records","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-1","gear":["Percussions live","Voix"],"gear_en":["Live percussion","Vocals"],"construction":"Une rythmique de percussions déliée, un groove dub et une voix féminine qui flotte au-dessus. La version « female vocal » mixée par Larry Levan devient la référence du Paradise Garage.","construction_en":"Loose percussion, a dub groove and a female vocal drifting above. The \"female vocal\" version mixed by Larry Levan became the Paradise Garage reference.","producer_origins":"Loose Joints est un projet d'Arthur Russell, compositeur et violoncelliste de l'avant-garde new-yorkaise, avec le DJ Steve D'Acquisto.","producer_origins_en":"Loose Joints was a project of Arthur Russell, a composer and cellist from New York's avant-garde, with DJ Steve D'Acquisto.","club_sociology":"Le disque circule d'abord en club avant de sortir. Levan et D'Acquisto en portent la version dans le circuit gay noir et latino, au moment où le Paradise Garage s'impose.","club_sociology_en":"The record circulated in clubs before release. Levan and D'Acquisto carried the version through the Black and Latino gay circuit as the Paradise Garage rose.","queer_ballroom_axis":"Arthur Russell était gay ; sa musique relie l'avant-garde du downtown et les pistes de danse. Un cas rare de passerelle entre ces deux scènes.","queer_ballroom_axis_en":"Arthur Russell was gay; his music links the downtown avant-garde and the dance floor. A rare bridge between those two scenes.","why_this_record":"Là où le disco devient dub, expérimental et profondément queer.","why_this_record_en":"Where disco turns dub, experimental and deeply queer.","archive_ref":{"source":"disco-files","note":"Contexte des clubs new-yorkais 1980.","note_en":"Context of New York clubs in 1980."},"further_reading":["last-night-dj","disco-files","you-better-work"],"verify":["différence entre versions (male vs female vocal)","rôle exact de Levan (mix vs production)","personnel"],"bpm":112,"camelot_key":"3A","energy":5,"verified":false,"continent_en":"North America","tags":["roots","queer","dub","us"],"youtube":["T_msLtqvpl8","hn27RiqRj7s","1c4kJwR8dIk"],"spotify":{"id":"1WtsuRKEu7GVJrxkOJXPO7","version":"Larry Levan Female Vocal Version"}},{"id":"energy-flash-beltram","title":"Energy Flash","artist":"Joey Beltram","year":1990,"label":"R&S Records","city":"New York / Gand","city_en":"New York / Ghent","country":"USA","country_en":"USA","continent":"Amérique du Nord","genre":"rave-jungle","era":"era-2","gear":["À documenter"],"gear_en":["To be documented"],"construction":"Un kick saturé, une basse tendue et un motif de synthé hypnotique : la techno new-yorkaise au maximum de pression. Le titre a donné son nom au livre de Simon Reynolds sur la rave.","construction_en":"A distorted kick, a tight bassline and a hypnotic synth riff: New York techno at full pressure. The title lent its name to Simon Reynolds's book on rave.","producer_origins":"Joey Beltram est un producteur new-yorkais ; son disque sort sur R&S, label belge de Gand, ce qui illustre la circulation transatlantique de la techno.","producer_origins_en":"Joey Beltram is a New York producer; his record came out on Belgium's Ghent label R&S, illustrating techno's transatlantic circulation.","club_sociology":"Le disque est un hymne des raves européennes de 1990-1991 et prépare le hardcore britannique.","club_sociology_en":"The record was an anthem at 1990–91 European raves and prepared the ground for British hardcore.","queer_ballroom_axis":"Pas d'axe queer propre. Le disque montre surtout la dette de la rave européenne envers les studios américains.","queer_ballroom_axis_en":"No specific queer axis. The record mostly shows the debt of European rave to American studios.","why_this_record":"Le disque qui rend la techno plus dure, plus rapide, plus européenne.","why_this_record_en":"The record that made techno harder, faster, more European.","archive_ref":{"source":"energy-flash","note":"Chapitres sur la techno hard et la rave.","note_en":"Chapters on hard techno and rave."},"further_reading":["energy-flash","underground-massive","rave-on"],"verify":["année exacte, formats, matériel","lien précis titre du disque / titre du livre"],"bpm":132,"camelot_key":"10A","energy":10,"verified":false,"continent_en":"North America","tags":["rave","machine","us"],"youtube":["ALsHox5sYCk","43W62fFY8C4","maOM81a-Gyg"],"spotify":{"id":"46ddej1ibGIgs58H0wakoK"}},{"id":"higher-state-of-consciousness","title":"Higher State of Consciousness","artist":"Josh Wink","year":1995,"label":"Strictly Rhythm","city":"Philadelphie","city_en":"Philadelphia","country":"USA","continent":"Amérique du Nord","genre":"acid","era":"era-2","gear":["tb-303"],"gear_en":["tb-303"],"construction":"Une seule ligne de 303 dont le filtre monte sans jamais redescendre, sur un kick sec : la tension est le sujet du disque. Il rappelle Acid Tracks de Phuture huit ans plus tard.","construction_en":"A single 303 line whose filter keeps climbing, over a dry kick: tension is the subject of the record. It recalls Phuture's Acid Tracks eight years on.","producer_origins":"Josh Wink vient de Philadelphie, où il cofonde le label Ovum avec King Britt. Le morceau sort d'abord en mars 1995 sur Strictly Rhythm, à New York : il remet l'acid au premier plan quand la house vocale domine.","producer_origins_en":"Josh Wink comes from Philadelphia, where he co-founded the Ovum label with King Britt. The track first came out in March 1995 on New York's Strictly Rhythm, putting acid back in the spotlight while vocal house dominated.","club_sociology":"Le disque est un tube de club mondial en 1995, y compris au Royaume-Uni, où la mémoire acid de 1988 est encore vive.","club_sociology_en":"The record was a worldwide club hit in 1995, including in the UK where the 1988 acid memory was still alive.","queer_ballroom_axis":"Comme pour Acid Tracks, la lignée remonte à la Music Box de Chicago, scène noire et gay, effacée par le récit de la rave.","queer_ballroom_axis_en":"As with Acid Tracks, the lineage goes back to Chicago's Music Box, a Black and gay scene that rave narratives erased.","why_this_record":"La preuve que l'acid n'est jamais mort.","why_this_record_en":"Proof that acid never died.","archive_ref":{"source":"underground-massive","note":"Le revival acid aux États-Unis.","note_en":"The acid revival in the US."},"further_reading":["underground-massive","last-night-dj","energy-flash"],"verify":["sortie originale vs réédition 1995","rôle de King Britt"],"bpm":130,"camelot_key":"8A","energy":10,"verified":false,"continent_en":"North America","tags":["machine","us"],"youtube":["d3hAnAnJwyU","4v2h8pfuZNQ"],"spotify":{"id":"6cJ3yBgG1VzRpf4xrKsfB8","version":"Tweekin Acid Funk"}},{"id":"technopolis","title":"Technopolis","artist":"Yellow Magic Orchestra","year":1979,"label":"Alfa Records","city":"Tokyo","country":"Japon","country_en":"Japan","continent":"Asie","continent_en":"Asia","genre":"electro","era":"era-1","gear":["Roland MC-8 Microcomposer","Synthétiseurs modulaires"],"gear_en":["Roland MC-8 Microcomposer","Modular synthesizers"],"construction":"Séquences programmées et sons de synthé en nappes froides : Tokyo vue comme une ville-machine. Le groupe affiche la dette envers Kraftwerk tout en y ajoutant une écriture pop japonaise.","construction_en":"Programmed sequences and cold synth pads: Tokyo as a machine-city. The group acknowledges its debt to Kraftwerk while adding Japanese pop writing.","producer_origins":"Haruomi Hosono, Ryuichi Sakamoto et Yukihiro Takahashi forment YMO ; Hideki Matsutake programme les machines.","producer_origins_en":"Haruomi Hosono, Ryuichi Sakamoto and Yukihiro Takahashi formed YMO; Hideki Matsutake programmed the machines.","club_sociology":"Les disques de YMO circulent dans l'électro new-yorkaise et figurent souvent parmi les influences citées par la génération de Detroit. Le Japon y apparaît comme producteur de sons, pas seulement comme récepteur.","club_sociology_en":"YMO's records circulated in New York electro and are often listed among the influences of Detroit's generation. Japan appears here as a producer of sounds, not just a receiver.","queer_ballroom_axis":"Pas d'axe queer explicite. Le disque est retenu pour la généalogie des machines.","queer_ballroom_axis_en":"No explicit queer axis. The record is included for the genealogy of machines.","why_this_record":"Le Japon dans l'histoire des machines, avant la house.","why_this_record_en":"Japan in the story of machines, before house.","archive_ref":{"source":"techno-rebels","note":"Influences japonaises sur Detroit (à confirmer dans le livre).","note_en":"Japanese influences on Detroit (to be confirmed in the book)."},"further_reading":["techno-rebels","modulations","rave-on"],"verify":["année de sortie du single vs de l'album"],"bpm":130,"camelot_key":"6A","energy":6,"verified":false,"tags":["machine","futurism","roots"],"youtube":["di_L7O56ZXE","zFADf3CW8zI"],"spotify":{"id":"025rboHEX5F2T0jRBMjuxI"}},{"id":"vogue","title":"Vogue","artist":"Madonna","year":1990,"label":"Sire / Warner Bros.","city":"New York","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-2","gear":["Boîte à rythmes","Synthétiseurs (production Shep Pettibone)"],"gear_en":["Drum machine","Synthesizers (Shep Pettibone production)"],"construction":"Une ligne de piano house, une basse garage et une liste parlée de noms d'icônes d'Hollywood. Shep Pettibone, producteur new-yorkais venu des clubs, signe un titre pensé pour la piste autant que pour la radio.","construction_en":"A house piano line, a garage bassline and a spoken list of Hollywood icons. Shep Pettibone, a New York producer from the clubs, shaped a track made for the floor as much as for radio.","producer_origins":"Madonna avait fréquenté le downtown new-yorkais et la scène des clubs gays dès les années 80 ; Pettibone vient du remix de club.","producer_origins_en":"Madonna had frequented downtown New York and gay club scenes since the 80s; Pettibone came from club remixing.","club_sociology":"Le disque et le clip popularisent le vogue au-delà de Harlem. Des danseurs de la House of Xtravaganza participent à la tournée de Madonna, et le film Paris Is Burning sort la même année.","club_sociology_en":"The record and video popularized vogue beyond Harlem. Dancers from the House of Xtravaganza joined Madonna's tour, and the film Paris Is Burning came out the same year.","queer_ballroom_axis":"Le disque est au centre du débat sur l'appropriation : la culture ballroom noire et latina queer est montrée au monde, mais sans que ses créateurs en tirent le même bénéfice.","queer_ballroom_axis_en":"The record is central to the appropriation debate: Black and Latino queer ballroom culture was shown to the world without its creators sharing the same benefit.","why_this_record":"Le pont entre ballroom, house et pop mondiale.","why_this_record_en":"The bridge between ballroom, house and global pop.","archive_ref":{"source":"paris-is-burning","note":"Mise en perspective avec le film.","note_en":"Context with the film."},"further_reading":["paris-is-burning","do-you-remember-house","underground-massive"],"verify":["liste exacte des danseurs de la tournée","crédits d'écriture"],"bpm":116,"camelot_key":"4B","energy":7,"verified":false,"continent_en":"North America","tags":["ballroom","queer","diva","us"],"youtube":["GuJQSAiODqI","An472Ijvww8"],"spotify":{"id":"4vNuuqBFdid5yTSWtppBYx"}},{"id":"break-my-soul","title":"Break My Soul","artist":"Beyoncé","year":2022,"label":"Parkwood / Columbia","city":"New York / Los Angeles","city_en":"New York / Los Angeles","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-3c","gear":["Samples : « Show Me Love » (Robin S), « Explode » (Big Freedia)"],"gear_en":["Samples: \"Show Me Love\" (Robin S), \"Explode\" (Big Freedia)"],"construction":"Un sample de « Show Me Love » de Robin S (et de son orgue M1) et une interpolation de « Explode » de Big Freedia, rappeuse bounce de La Nouvelle-Orléans. Le refrain est pensé pour la piste ; la production est signée Beyoncé, The-Dream et Tricky Stewart.","construction_en":"A sample of Robin S's \"Show Me Love\" (and its M1 organ) and an interpolation of \"Explode\" by New Orleans bounce artist Big Freedia. The hook is built for the floor; production by Beyoncé, The-Dream and Tricky Stewart.","producer_origins":"Beyoncé revendique sur l'album Renaissance une lignée de musiques noires de club, avec un hommage explicite aux pionniers de la house.","producer_origins_en":"On Renaissance Beyoncé claims a lineage of Black club music, with an explicit tribute to house pioneers.","club_sociology":"Le titre devient numéro un du Billboard Hot 100 et du classement dance américain, rouvrant la question de la visibilité de la house hors de ses scènes d'origine.","club_sociology_en":"The track went to number one on the Billboard Hot 100 and the US dance chart, reopening the question of house's visibility beyond its original scenes.","queer_ballroom_axis":"Le disque fait directement référence à la culture ballroom et à la house queer noire, en position d'hommage mainstream : à lire avec Vogue (1990) et Show Me Love.","queer_ballroom_axis_en":"The record directly references ballroom and Black queer house, as a mainstream tribute: read alongside Vogue (1990) and Show Me Love.","why_this_record":"La boucle est bouclée : la house revient en tête des charts en revendiquant sa lignée noire et queer.","why_this_record_en":"The loop closes: house returns to the top of the charts by claiming its Black and queer lineage.","archive_ref":{"source":"do-you-remember-house","note":"Généalogie queer de la house.","note_en":"Queer genealogy of house."},"further_reading":["do-you-remember-house","energy-never-dies","underground-massive"],"verify":["crédits de production et d'écriture exacts (dont Honey Dijon)","position dans le classement"],"bpm":115,"camelot_key":"6A","energy":8,"verified":false,"continent_en":"North America","tags":["ballroom","queer","diva","us"],"youtube":["iz1rIp1-b-Y","yjki-9Pthh0"],"spotify":{"id":"5pyoxDZ1PX0KxBxiRVxA4U"}},{"id":"tshwala-bam","title":"Tshwala Bam","artist":"TitoM & Yuppe feat. S.N.E & EeQue","year":2024,"label":"Africori","city":"Johannesburg","country":"Afrique du Sud","country_en":"South Africa","continent":"Afrique","continent_en":"Africa","genre":"amapiano","era":"era-3c","gear":["log-drum","DAW"],"gear_en":["log-drum","DAW"],"construction":"Un log drum large, des chœurs de rue et un tempo lent : l'amapiano à son point de circulation maximale.","construction_en":"A broad log drum, street chants and a slow tempo: amapiano at its point of maximum circulation.","producer_origins":"TitoM et Yuppe, producteurs de Johannesburg, signent le morceau avec les voix de S.N.E et EeQue. Sorti en février 2024, il dépasse les 100 millions d'écoutes en moins d'un mois ; un remix avec Burna Boy suit en mai.","producer_origins_en":"TitoM and Yuppe, Johannesburg producers, made the track with vocals by S.N.E and EeQue. Released in February 2024, it passed 100 million streams in under a month; a remix with Burna Boy followed in May.","club_sociology":"Après Ke Star et Water, le titre confirme que l'amapiano est une industrie à part entière, diffusée par danses virales et DJs internationaux.","club_sociology_en":"After Ke Star and Water, the track confirms amapiano as an industry in itself, spread by viral dances and international DJs.","queer_ballroom_axis":"Sujet à documenter avant d'affirmer quoi que ce soit.","queer_ballroom_axis_en":"To be documented before asserting anything.","why_this_record":"Le chaînon d'après Water : l'amapiano, hors du township.","why_this_record_en":"The link after Water: amapiano beyond the township.","archive_ref":{"source":"rave-on","note":"Ouverture mondiale de la dance music (à confirmer).","note_en":"Global opening of dance music (to be confirmed)."},"further_reading":["rave-on"],"verify":["label et crédits exacts","année de sortie","statut de la source bibliographique (à remplacer par une source récente)"],"bpm":113,"camelot_key":"5A","energy":7,"verified":false,"tags":["africa","log-drum","diaspora"],"youtube":["KK4dC7rASYs","j1n8B6J1JF8"],"spotify":{"id":"54seQV7MCcppBrznALCdlT"}},{"id":"reachin","title":"Reachin'","artist":"Phase II","year":1988,"label":"Movin' Records","city":"New Jersey","country":"USA","continent":"Amérique du Nord","genre":"garage-nyc","era":"era-1","bpm":120,"camelot_key":"8A","energy":6,"gear":["Boîte à rythmes","Synthétiseurs"],"construction":"Un groove garage souple, des accords chauds et une voix soul qui « tend la main » : le son gospel et deep du New Jersey, moins frontal que celui de Manhattan.","construction_en":"A loose garage groove, warm chords and a soul vocal \"reaching\" out: New Jersey's gospel, deep sound, less frontal than Manhattan's.","producer_origins":"Phase II est un nom collectif utilisé par des figures des clubs du New Jersey, dont les membres de Blaze (Josh Milan, Kevin Hedge, Chris Herbert). Le disque est l'un des premiers succès de Movin' Records, label du New Jersey.","producer_origins_en":"Phase II was a collective name used by New Jersey club figures, including the members of Blaze (Josh Milan, Kevin Hedge, Chris Herbert). The record was one of the first hits for the New Jersey label Movin' Records.","club_sociology":"C'est le son du Club Zanzibar de Newark, où Tony Humphries est résident de 1982 à 1994 et qui devient, après la fermeture du Paradise Garage en 1987, un centre de la house de la région.","club_sociology_en":"This is the sound of Newark's Club Zanzibar, where Tony Humphries was resident from 1982 to 1994 and which became, after the Paradise Garage closed in 1987, a centre of the region's house.","queer_ballroom_axis":"Le garage du New Jersey prolonge la ferveur gospel des clubs noirs et gays new-yorkais ; la composition du public du Zanzibar reste à documenter précisément.","queer_ballroom_axis_en":"New Jersey garage extends the gospel fervour of New York's Black and gay clubs; the exact make-up of Zanzibar's crowd still needs documenting.","why_this_record":"Il fait exister le New Jersey comme matrice distincte de New York.","why_this_record_en":"It makes New Jersey exist as a matrix distinct from New York.","archive_ref":{"source":"beat-scene-sound","note":"Le Zanzibar et la scène du New Jersey dans le récit de DJ Disciple.","note_en":"Zanzibar and the New Jersey scene in DJ Disciple's account."},"tags":["roots","gospel","us"],"verified":false,"continent_en":"North America","gear_en":["Drum machine","Synthesizers"],"further_reading":["last-night-dj"],"verify":["Crédits exacts de Phase II sur ce disque"],"youtube":["rV_mmxsaPeM","1Gobukd4y5s"],"spotify":{"id":"6KlbbkiO0VC9mqdNWT3XtI","version":"Brotherhood Mix"}},{"id":"keep-on-movin","title":"Keep On Movin'","artist":"Soul II Soul","year":1989,"label":"Ten Records","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"uk-bass","era":"era-1","bpm":94,"camelot_key":"5A","energy":5,"gear":["Boîtes à rythmes","Cordes","Basse"],"construction":"Un tempo lent et chaloupé (le « Funki Dred beat »), une basse ronde, des cordes et la voix de Caron Wheeler. Le groove vient du sound system plus que du club house.","construction_en":"A slow, swaying tempo (the \"Funki Dred beat\"), a round bassline, strings and Caron Wheeler's voice. The groove comes from the sound system more than from the house club.","producer_origins":"Soul II Soul naît d'un sound system londonien mené par Jazzie B, avec Nellee Hooper à la production. Le collectif est à la fois un groupe, une boutique et une soirée.","producer_origins_en":"Soul II Soul grew out of a London sound system led by Jazzie B, with Nellee Hooper producing. The collective was a band, a shop and a party all at once.","club_sociology":"Les soirées du dimanche du collectif, à l'Africa Centre de Covent Garden, font le lien entre culture sound system caribéenne, soul et house naissante. Le single entre au top 5 britannique.","club_sociology_en":"The collective's Sunday sessions at the Africa Centre in Covent Garden linked Caribbean sound-system culture, soul and emerging house. The single made the UK top 5.","queer_ballroom_axis":"Pas d'axe queer explicite : c'est une culture noire britannique du sound system.","queer_ballroom_axis_en":"No explicit queer axis: this is Black British sound-system culture.","why_this_record":"La station Sound System prend vie : la basse britannique avant l'acid.","why_this_record_en":"The Sound System station comes alive: British bass before acid.","archive_ref":{"source":"join-the-future","note":"Culture sound system et sub-bass britannique.","note_en":"Sound-system culture and British sub-bass."},"tags":["uk","black-british","roots"],"verified":false,"continent_en":"Europe","city_en":"London","country_en":"United Kingdom","gear_en":["Drum machines","Strings","Bass"],"further_reading":["energy-flash"],"verify":["Classement exact au Royaume-Uni"],"youtube":["1iQl46-zIcM"]},{"id":"lfo","title":"LFO","artist":"LFO","year":1990,"label":"Warp","city":"Leeds","country":"Royaume-Uni","continent":"Europe","genre":"uk-bass","era":"era-2","bpm":125,"camelot_key":"10A","energy":8,"gear":["Synthétiseurs","Boîte à rythmes"],"construction":"Des tonalités pures (les « bleeps »), un sub-bass énorme et une rythmique sèche : la techno de Detroit passée au filtre des sound systems du Yorkshire.","construction_en":"Pure tones (the \"bleeps\"), an enormous sub-bass and a dry rhythm: Detroit techno filtered through Yorkshire's sound systems.","producer_origins":"Mark Bell et Gez Varley, deux jeunes de Leeds, signent chez Warp, label fondé à Sheffield en 1989.","producer_origins_en":"Mark Bell and Gez Varley, two young Leeds producers, signed to Warp, the label founded in Sheffield in 1989.","club_sociology":"Le disque entre dans le top 20 britannique : la bleep devient la première musique bass britannique à toucher le grand public.","club_sociology_en":"The record entered the UK top 20: bleep became the first British bass music to reach a mass audience.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"La station Bleep prend vie, et la correspondance avec Detroit devient audible.","why_this_record_en":"The Bleep station comes alive, and the transfer to Detroit becomes audible.","archive_ref":{"source":"join-the-future","note":"Leeds, Sheffield, Warp et la bleep.","note_en":"Leeds, Sheffield, Warp and bleep."},"tags":["uk","machine"],"verified":false,"continent_en":"Europe","country_en":"United Kingdom","gear_en":["Synthesizers","Drum machine"],"further_reading":["energy-flash"],"verify":["Classement exact au Royaume-Uni"],"youtube":["s-1Y2EqThyQ"],"spotify":{"id":"5AMGYRhiqZoCYkJEK3yqgi","version":"Leeds Warehouse Mix"}},{"id":"midnight-request-line","title":"Midnight Request Line","artist":"Skream","year":2005,"label":"Tempa","city":"Croydon","country":"Royaume-Uni","continent":"Europe","genre":"uk-bass","era":"era-3a","bpm":140,"camelot_key":"6A","energy":7,"gear":["DAW","Sub-bass"],"construction":"Une mélodie de synthé obsédante, un sub-bass profond et une rythmique en demi-temps à 140 BPM : le dubstep dans sa forme la plus mélodique.","construction_en":"A haunting synth melody, deep sub-bass and a half-time rhythm at 140 BPM: dubstep at its most melodic.","producer_origins":"Skream (Oliver Jones), adolescent de Croydon, gravite autour du disquaire Big Apple Records, foyer de la dark garage puis du dubstep.","producer_origins_en":"Skream (Oliver Jones), a Croydon teenager, orbited around Big Apple Records, the shop at the heart of dark garage and then dubstep.","club_sociology":"Les soirées FWD>> et DMZ sont les lieux clés de la scène ; ce disque marque son passage à une audience mondiale.","club_sociology_en":"The FWD>> and DMZ nights were the scene's key venues; this record marked its move to a worldwide audience.","queer_ballroom_axis":"Pas d'axe queer explicite : la scène dubstep est d'abord une culture de la basse et des sound systems.","queer_ballroom_axis_en":"No explicit queer axis: the dubstep scene is first of all a culture of bass and sound systems.","why_this_record":"La station Dubstep prend vie.","why_this_record_en":"The Dubstep station comes alive.","archive_ref":{"source":"energy-flash","note":"Le hardcore continuum et ses prolongements.","note_en":"The hardcore continuum and its extensions."},"tags":["uk","black-british"],"verified":false,"continent_en":"Europe","country_en":"United Kingdom","further_reading":["state-of-bass"],"youtube":["lcMAbnZy8l8"],"spotify":{"id":"5FbqI4BGhhKMykDiLoJSad"}},{"id":"summertime-is-here","title":"Summertime Is Here","artist":"Theo Parrish","year":1999,"label":"Sound Signature","city":"Detroit","country":"USA","continent":"Amérique du Nord","genre":"detroit","era":"era-2","bpm":116,"camelot_key":"4A","energy":5,"gear":["Sampler","Filtres"],"construction":"Une boucle soul samplée, filtrée et laissée respirer pendant plus de dix minutes, avec un tempo qui semble flotter. Le grain est volontairement brut.","construction_en":"A sampled soul loop, filtered and left to breathe for more than ten minutes, with a tempo that seems to float. The grit is deliberately raw.","producer_origins":"Theo Parrish, né à Washington D.C. en 1972, élevé à Chicago et installé dans le Michigan en 1994, fonde Sound Signature en 1997.","producer_origins_en":"Theo Parrish, born in Washington D.C. in 1972, raised in Chicago and based in Michigan from 1994, founded Sound Signature in 1997.","club_sociology":"Sorti en 12 pouces sur Sound Signature en 1999 (SS008), le morceau devient un classique des DJs deep ; il est repressé à plusieurs reprises et repris sur la compilation Parallel Dimensions.","club_sociology_en":"Released as a 12\" on Sound Signature in 1999 (SS008), the track became a classic for deep DJs; it has been repressed several times and included on the Parallel Dimensions compilation.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"La station Sound Signature prend vie.","why_this_record_en":"The Sound Signature station comes alive.","archive_ref":{"source":"techno-rebels","note":"Detroit après la première vague techno.","note_en":"Detroit after the first techno wave."},"tags":["us","deep","sample"],"verified":false,"continent_en":"North America","gear_en":["Sampler","Filters"],"youtube":["76E-thr2I14","UMMrF6wPnxo"],"spotify":{"id":"6mJIX7DpkImJLybaKDBPLA"}},{"id":"ice-drop","title":"Ice Drop","artist":"DJ Lag","year":2016,"label":"Goon Club Allstars","city":"Durban","country":"Afrique du Sud","continent":"Afrique","genre":"gqom","era":"era-3b","bpm":126,"camelot_key":"7A","energy":8,"gear":["DAW","Kicks"],"construction":"Des kicks lourds et décalés, des percussions sèches et presque pas de mélodie : le gqom tient sur la tension rythmique.","construction_en":"Heavy, off-kilter kicks, dry percussion and almost no melody: gqom runs on rhythmic tension.","producer_origins":"DJ Lag (Lwazi Asanda Gwala) écrit le morceau à 17 ans ; il circule à Durban vers 2013 avant de sortir fin 2016 sur l'EP publié par le label londonien Goon Club Allstars.","producer_origins_en":"DJ Lag (Lwazi Asanda Gwala) wrote the track at 17; it circulated in Durban around 2013 before coming out in late 2016 on an EP released by the London label Goon Club Allstars.","club_sociology":"Le gqom circule d'abord par les taxis, WhatsApp et les fêtes de township, puis s'exporte via des labels européens : le Sud global devient un centre de création.","club_sociology_en":"Gqom first circulated through taxis, WhatsApp and township parties, then spread through European labels: the Global South becomes a centre of creation.","queer_ballroom_axis":"Sujet à documenter avant d'affirmer quoi que ce soit.","queer_ballroom_axis_en":"To be documented before asserting anything.","why_this_record":"Il donne à Durban sa station sur la ligne des Afriques.","why_this_record_en":"It gives Durban its station on the Africas line.","archive_ref":{"source":"rave-on","note":"Scènes électroniques hors d'Europe et des États-Unis.","note_en":"Electronic scenes beyond Europe and the US."},"tags":["africa","diaspora"],"verified":false,"continent_en":"Africa","country_en":"South Africa","youtube":["9ycr4BI8I94"],"spotify":{"id":"1AUkzwumfpusZ9wkUVSaQX"}},{"id":"double-cup","title":"Double Cup","artist":"DJ Rashad feat. DJ Spinn","year":2013,"label":"Hyperdub","city":"Chicago","country":"USA","continent":"Amérique du Nord","genre":"footwork","era":"era-3b","bpm":160,"camelot_key":"9A","energy":8,"gear":["Sampler","Boîte à rythmes (808)"],"construction":"Des kicks en triolets autour de 160 BPM, des samples vocaux hachés et des nappes plus douces que le footwork de battle : le footwork tourné vers l'écoute.","construction_en":"Triplet kicks around 160 BPM, chopped vocal samples and softer pads than battle footwork: footwork turned towards listening.","producer_origins":"DJ Rashad, figure du collectif Teklife, vient de la ghetto house de Chicago (Dance Mania, DJ Funk). Il meurt en 2014, un an après la sortie de l'album.","producer_origins_en":"DJ Rashad, a leading figure of the Teklife crew, came out of Chicago ghetto house (Dance Mania, DJ Funk). He died in 2014, a year after the album came out.","club_sociology":"L'album sort chez Hyperdub, à Londres : le footwork, né des battles de danse du South Side et du West Side, trouve une audience internationale.","club_sociology_en":"The album came out on Hyperdub in London: footwork, born from South Side and West Side dance battles, found an international audience.","queer_ballroom_axis":"Pas d'axe queer explicite : le footwork est d'abord une culture de danse de la jeunesse noire de Chicago.","queer_ballroom_axis_en":"No explicit queer axis: footwork is first a dance culture of Chicago's Black youth.","why_this_record":"Il prolonge la ligne de Chicago au-delà de 2005.","why_this_record_en":"It extends the Chicago line beyond 2005.","archive_ref":{"source":"underground-massive","note":"La dance music américaine des années 2010.","note_en":"American dance music in the 2010s."},"tags":["us","machine"],"verified":false,"continent_en":"North America","gear_en":["Sampler","Drum machine (808)"],"youtube":["dPv33vCU3k8","qc2CZDezGHQ"]},{"id":"feels-like","title":"Feels Like","artist":"MikeQ feat. Kevin JZ Prodigy","year":2011,"label":"Fade to Mind","city":"New Jersey","country":"USA","continent":"Amérique du Nord","genre":"ballroom","era":"era-3a","bpm":130,"camelot_key":"4A","energy":8,"gear":["DAW","Samples (« The Ha Dance »)"],"construction":"Le « ha » et le crash hérités de « The Ha Dance », une rythmique tendue et les chants de Kevin JZ Prodigy, commentateur de ballroom : un morceau fait pour les catégories.","construction_en":"The \"ha\" and the crash inherited from \"The Ha Dance\", a tense rhythm and the chants of ballroom commentator Kevin JZ Prodigy: a track made for the categories.","producer_origins":"MikeQ, producteur du New Jersey, publie le morceau sur l'EP Let It All Out (Fade to Mind, 2011). Il fait remonter Qween Beat à 2005, d'abord comme nom sous lequel il publie sa musique, puis comme collectif ; la première sortie officielle du label, Qweendom, paraît en août 2016.","producer_origins_en":"MikeQ, a New Jersey producer, released the track on the Let It All Out EP (Fade to Mind, 2011). He dates Qween Beat back to 2005, first as the name he released his music under, then as a collective; the label's first official release, Qweendom, came out in August 2016.","club_sociology":"Le morceau est samplé en 2022 par Beyoncé sur « Pure/Honey » (album Renaissance) : la ballroom passe de scène fermée à référence pop.","club_sociology_en":"The track was sampled in 2022 by Beyoncé on \"Pure/Honey\" (Renaissance): ballroom moves from a closed scene to a pop reference.","queer_ballroom_axis":"C'est la musique des balls contemporains, faite par et pour les houses queer et trans noires et latinas.","queer_ballroom_axis_en":"This is the music of contemporary balls, made by and for Black and Latina queer and trans houses.","why_this_record":"Le chaînon entre « The Ha Dance » et Renaissance.","why_this_record_en":"The link between \"The Ha Dance\" and Renaissance.","archive_ref":{"source":"paris-is-burning","note":"Le contexte ballroom que ce beat prolonge.","note_en":"The ballroom context this beat extends."},"tags":["ballroom","queer","us"],"verified":false,"continent_en":"North America","gear_en":["DAW","Samples (\"The Ha Dance\")"],"further_reading":["do-you-remember-house"],"youtube":["tW8curhicTQ","zAddWB67PGo"],"spotify":{"id":"607iqTCELM1TcCdziMcRrT"}},{"id":"dawning","title":"Dawning","artist":"Dettmann & Klock","year":2006,"label":"Ostgut Ton","city":"Berlin","country":"Allemagne","continent":"Europe","genre":"techno","era":"era-3a","bpm":130,"camelot_key":"8A","energy":8,"gear":["Boîte à rythmes","Synthétiseurs"],"construction":"Un kick sec, des nappes sourdes et une montée lente : la techno de Berghain, austère et hypnotique.","construction_en":"A dry kick, muffled pads and a slow build: Berghain techno, austere and hypnotic.","producer_origins":"Marcel Dettmann et Ben Klock, résidents de Berghain, signent leur première collaboration ; c'est le premier maxi du label Ostgut Ton (O-Ton 001), lancé fin 2005.","producer_origins_en":"Marcel Dettmann and Ben Klock, Berghain residents, made their first collaboration; it was the first 12\" on the Ostgut Ton label (O-Ton 001), launched in late 2005.","club_sociology":"Berghain ouvre en 2004 dans une ancienne centrale électrique : Berlin devient le centre de la techno européenne, dans la continuité de Detroit.","club_sociology_en":"Berghain opened in 2004 in a former power station: Berlin became the centre of European techno, in Detroit's lineage.","queer_ballroom_axis":"Berghain et Panorama Bar héritent de la scène gay berlinoise (Ostgut, Snax) ; la présence queer y est structurelle.","queer_ballroom_axis_en":"Berghain and Panorama Bar grew out of Berlin's gay scene (Ostgut, Snax); the queer presence there is structural.","why_this_record":"Il ouvre la ligne Techno & Berlin.","why_this_record_en":"It opens the Techno & Berlin line.","archive_ref":{"source":"rave-on","note":"Berlin après le Mur et Berghain.","note_en":"Berlin after the Wall and Berghain."},"tags":["europe","machine","queer"],"verified":false,"continent_en":"Europe","country_en":"Germany","gear_en":["Drum machine","Synthesizers"],"verify":["Filiation Ostgut / Snax à sourcer"],"youtube":["QVad8r5FTsk","-z4QdShPw_A"],"spotify":{"id":"2E6WTPlkw9uCQgZ9QzcSBg"}},{"id":"not-about-you","title":"Not About You","artist":"Honey Dijon feat. Hadiya George","year":2022,"label":"Classic Music Company","city":"Chicago / New York","country":"USA","continent":"Amérique du Nord","genre":"chicago","era":"era-3c","bpm":124,"camelot_key":"8B","energy":7,"gear":["DAW","Voix"],"construction":"Une house vocale lumineuse, une basse ronde et la voix soul de Hadiya George : la house de Chicago réécrite pour 2022.","construction_en":"Bright vocal house, a round bassline and Hadiya George's soul voice: Chicago house rewritten for 2022.","producer_origins":"Honey Dijon, DJ et productrice née à Chicago, femme trans noire, coécrit l'album Black Girl Magic avec Luke Solomon ; elle travaille aussi sur Renaissance de Beyoncé.","producer_origins_en":"Honey Dijon, a Chicago-born DJ and producer and a Black trans woman, co-wrote the album Black Girl Magic with Luke Solomon; she also worked on Beyoncé's Renaissance.","club_sociology":"Le single tourne sur BBC Radio 1 avant la sortie de l'album en novembre 2022 : la house noire et queer revient au cœur de la pop.","club_sociology_en":"The single was playlisted on BBC Radio 1 before the album's release in November 2022: Black and queer house returns to the heart of pop.","queer_ballroom_axis":"Honey Dijon dit vouloir réancrer la house dans ses communautés d'origine, noires et queer.","queer_ballroom_axis_en":"Honey Dijon says she wants to re-root house in its original Black and queer communities.","why_this_record":"La réappropriation, par celles et ceux qui ont inventé la house.","why_this_record_en":"Reclamation, by those who invented house.","archive_ref":{"source":"do-you-remember-house","note":"La house queer noire de Chicago et sa mémoire.","note_en":"Chicago's Black queer house and its memory."},"tags":["queer","diva","us"],"verified":false,"continent_en":"North America","gear_en":["DAW","Vocals"],"further_reading":["energy-never-dies"],"youtube":["3fzuzLkzL2w","XULoHyXfVXk"],"spotify":{"id":"3F152F42cdRCeKMCP9by6X"}},{"id":"u-seinfeld","title":"U","artist":"DJ Seinfeld","year":2017,"label":"Lobster Fury","city":"Malmö","country":"Suède","continent":"Europe","genre":"lofi","era":"era-3b","bpm":120,"camelot_key":"3A","energy":5,"gear":["Saturation","Sampler"],"construction":"Des accords voilés, un kick étouffé et un sample vocal pitché, sous une couche de souffle et de poussière analogique.","construction_en":"Hazy chords, a muffled kick and a pitched vocal sample, under a layer of hiss and analogue dust.","producer_origins":"DJ Seinfeld (Armand Jakobsson), producteur suédois, sort son premier EP en 2016 chez Lobster Fury ; « U » circule en ligne avant de paraître sur l'album Time Spent Away From U (2017).","producer_origins_en":"DJ Seinfeld (Armand Jakobsson), a Swedish producer, released his first EP in 2016 on Lobster Fury; \"U\" circulated online before appearing on the album Time Spent Away From U (2017).","club_sociology":"Le morceau doit une grande partie de sa diffusion à YouTube : la lo-fi house est une scène internationale, de l'Australie à la Suède.","club_sociology_en":"The track owes much of its spread to YouTube: lo-fi house is an international scene, from Australia to Sweden.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"Il montre le caractère international de la lo-fi house.","why_this_record_en":"It shows lo-fi house's international character.","archive_ref":{"source":"how-music-works","note":"Le son façonné par son lieu d'écoute.","note_en":"Sound shaped by where it is heard."},"tags":["internet","nostalgia","europe"],"verified":false,"continent_en":"Europe","country_en":"Sweden","verify":["Label et date de la première diffusion de « U »","Ville de résidence de l'artiste"],"youtube":["6F6Sxrd7rw4","g6eu1Wb8CVE"]},{"id":"black-mahogani","title":"Black Mahogani","artist":"Moodymann","year":2004,"label":"Peacefrog","city":"Detroit","country":"USA","continent":"Amérique du Nord","genre":"detroit","era":"era-2","bpm":115,"camelot_key":"5A","energy":5,"gear":["Sampler","Instruments live"],"construction":"Un album de deep house lent et soul, entre samples, instruments joués et ambiance de fin de nuit.","construction_en":"A slow, soulful deep house album, between samples, played instruments and an end-of-night atmosphere.","producer_origins":"Moodymann (Kenny Dixon Jr.), producteur de Detroit et patron du label KDJ, publie l'album chez Peacefrog en mai 2004, après une série de maxis rares.","producer_origins_en":"Moodymann (Kenny Dixon Jr.), a Detroit producer and head of the KDJ label, released the album on Peacefrog in May 2004, after a run of rare 12\"s.","club_sociology":"C'est l'une des œuvres les plus révérées de la seconde vague de Detroit, celle qui revendique la soul et la culture noire de la ville.","club_sociology_en":"It is one of the most revered works of Detroit's second wave, the one that claims the city's soul and Black culture.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"Detroit en continu après la techno de la première vague.","why_this_record_en":"Detroit carrying on after first-wave techno.","archive_ref":{"source":"techno-rebels","note":"Detroit après la première vague.","note_en":"Detroit after the first wave."},"tags":["us","deep","soul"],"verified":false,"continent_en":"North America","gear_en":["Sampler","Live instruments"],"youtube":["I579xnM6ocQ"],"spotify":{"id":"495oT3dvrhlsppXTlXHpQx"}},{"id":"dance-justice","title":"D.A.N.C.E.","artist":"Justice","year":2007,"label":"Ed Banger Records","city":"Paris","country":"France","continent":"Europe","genre":"french-touch","era":"era-3a","bpm":113,"camelot_key":"11B","energy":8,"gear":["Sampler","Basse saturée"],"construction":"Une chorale d'enfants, une basse disco saturée et un hommage à Michael Jackson : la French Touch passe de la boucle filtrée à l'électro saturée.","construction_en":"A children's choir, a distorted disco bassline and a tribute to Michael Jackson: the French Touch moves from the filtered loop to saturated electro.","producer_origins":"Gaspard Augé et Xavier de Rosnay signent chez Ed Banger, le label de Pedro Winter, ancien manager de Daft Punk.","producer_origins_en":"Gaspard Augé and Xavier de Rosnay signed to Ed Banger, the label of Pedro Winter, Daft Punk's former manager.","club_sociology":"Le disque, tiré de l'album Cross (2007), incarne la seconde vague French Touch, portée par les blogs et MySpace.","club_sociology_en":"Taken from the album Cross (2007), the record embodies the French Touch's second wave, carried by blogs and MySpace.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"La seconde vague French Touch.","why_this_record_en":"The French Touch's second wave.","archive_ref":{"source":"musique-house-bidder","note":"La French Touch et ses suites.","note_en":"The French Touch and what followed."},"tags":["europe","crossover"],"verified":false,"continent_en":"Europe","gear_en":["Sampler","Distorted bass"],"youtube":["sy1dYFGkPUE","tCnBrrnOefs"],"spotify":{"id":"33yAEqzKXexYM3WlOYtTfQ"}},{"id":"need-u","title":"Need U (100%)","artist":"Duke Dumont feat. A*M*E","year":2013,"label":"Blasé Boys Club / Ministry of Sound","city":"Londres","country":"Royaume-Uni","continent":"Europe","genre":"chart-house","era":"era-3b","bpm":124,"camelot_key":"7A","energy":8,"gear":["DAW","Orgue (preset)"],"construction":"Un riff d'orgue, une basse ronde et une voix pop pitchée : la deep house des années 90 remise au goût des radios.","construction_en":"An organ riff, a round bassline and a pitched pop vocal: 90s deep house updated for radio.","producer_origins":"Duke Dumont (Adam Dyment), producteur londonien, s'appuie sur la voix de la chanteuse A*M*E.","producer_origins_en":"Duke Dumont (Adam Dyment), a London producer, built the track around singer A*M*E's voice.","club_sociology":"Numéro 1 au Royaume-Uni en avril 2013, avec « White Noise » de Disclosure (n°2) : la house sort des sous-sols pour revenir dans les charts et à Ibiza.","club_sociology_en":"Number 1 in the UK in April 2013, alongside Disclosure's \"White Noise\" (number 2): house leaves the basements to return to the charts and Ibiza.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"Le crossover de 2013.","why_this_record_en":"The 2013 crossover.","archive_ref":{"source":"underground-massive","note":"La house redevenue grand public.","note_en":"House going mainstream again."},"tags":["uk","crossover","pop"],"verified":false,"continent_en":"Europe","city_en":"London","country_en":"United Kingdom","gear_en":["DAW","Organ (preset)"],"youtube":["_B-DscDxsmw","CgTB1ay_nnA"]},{"id":"spongebob","title":"Spongebob","artist":"Coki","year":2007,"label":"DMZ","city":"Londres","country":"Royaume-Uni","continent":"Europe","continent_en":"Europe","genre":"uk-bass","era":"era-3a","bpm":140,"camelot_key":"1A","energy":8,"gear":["DAW","Sub-bass"],"gear_en":["DAW","Sub-bass"],"construction":"Une basse médium qui se tord et grogne au lieu de rester dans le sub : le « wobble » qui annonce le virage du dubstep vers la piste de danse.","construction_en":"A mid-range bassline that twists and growls instead of staying in the sub: the \"wobble\" that announces dubstep's turn towards the dancefloor.","producer_origins":"Coki (Dean Harris) forme Digital Mystikz avec Mala ; tous deux fondent avec Loefah le label et la soirée DMZ. Le maxi « Spongebob / The End » sort en 2007 (DMZ 013).","producer_origins_en":"Coki (Dean Harris) formed Digital Mystikz with Mala; with Loefah they founded the DMZ label and night. The \"Spongebob / The End\" 12\" came out in 2007 (DMZ 013).","club_sociology":"Le morceau est repris par Caspa & Rusko dans leur mix FabricLive : il ouvre la voie à la vague dubstep centrée sur le drop, puis au brostep des années 2010.","club_sociology_en":"Caspa & Rusko featured it in their FabricLive mix: it paved the way for the drop-driven dubstep wave, then the brostep of the 2010s.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"Le moment où le dubstep change de corps.","why_this_record_en":"The moment dubstep changes its body.","archive_ref":{"source":"energy-flash","note":"Le hardcore continuum et ses prolongements.","note_en":"The hardcore continuum and its extensions."},"tags":["uk","black-british"],"youtube":["cIpc817U_R4","-BFeY5aC06k"],"verified":false,"city_en":"London","country_en":"United Kingdom"},{"id":"white-noise","title":"White Noise","artist":"Disclosure feat. AlunaGeorge","year":2013,"label":"PMR Records","city":"Reigate / Londres","country":"Royaume-Uni","continent":"Europe","continent_en":"Europe","genre":"chart-house","era":"era-3b","bpm":120,"camelot_key":"4A","energy":7,"gear":["DAW","Voix"],"gear_en":["DAW","Vocals"],"construction":"Une rythmique garage et house, une basse ronde et la voix pop d'Aluna Francis : le garage des années 90 réécrit pour la radio.","construction_en":"A garage-and-house rhythm, a round bassline and Aluna Francis's pop vocal: 90s garage rewritten for radio.","producer_origins":"Guy et Howard Lawrence, deux frères du Surrey, signent chez PMR ; ils invitent le duo londonien AlunaGeorge.","producer_origins_en":"Guy and Howard Lawrence, two brothers from Surrey, signed to PMR; they brought in the London duo AlunaGeorge.","club_sociology":"Le single atteint la 2e place au Royaume-Uni en février 2013, deux mois avant le n°1 de Duke Dumont : la house revient en tête des charts.","club_sociology_en":"The single reached number 2 in the UK in February 2013, two months before Duke Dumont's number 1: house returns to the top of the charts.","queer_ballroom_axis":"Pas d'axe queer explicite.","queer_ballroom_axis_en":"No explicit queer axis.","why_this_record":"L'autre moitié du crossover de 2013.","why_this_record_en":"The other half of the 2013 crossover.","archive_ref":{"source":"underground-massive","note":"La house redevenue grand public.","note_en":"House going mainstream again."},"tags":["uk","crossover","pop"],"youtube":["bkk2H3Ztrfk","FTwCgK-zTEs"],"verified":false,"city_en":"Reigate / London","country_en":"United Kingdom"},{"id":"fizheuer-zieheuer","title":"Fizheuer Zieheuer","artist":"Ricardo Villalobos","year":2006,"label":"Playhouse","city":"Francfort / Berlin","country":"Allemagne","continent":"Europe","continent_en":"Europe","genre":"techno","era":"era-3a","bpm":125,"camelot_key":"9A","energy":5,"gear":["Ordinateur","Samples de cuivres"],"gear_en":["Computer","Brass samples"],"construction":"Trente-sept minutes bâties sur une seule boucle de cuivres et une rythmique minimale qui se transforme à peine : la répétition poussée jusqu'à l'hypnose.","construction_en":"Thirty-seven minutes built on a single brass loop and a minimal rhythm that barely changes: repetition pushed to the point of hypnosis.","producer_origins":"Ricardo Villalobos, né au Chili et arrivé enfant en Allemagne, est l'une des figures de la minimale berlinoise ; l'EP sort en novembre 2006 sur Playhouse, label de Francfort.","producer_origins_en":"Ricardo Villalobos, born in Chile and brought to Germany as a child, is a leading figure of Berlin minimal; the EP came out in November 2006 on Playhouse, a Frankfurt label.","club_sociology":"Le disque polarise : chef-d'œuvre pour les uns, excès pour les autres. Il incarne la minimale des clubs berlinois, où les sets durent des heures.","club_sociology_en":"The record polarised listeners: a masterpiece for some, an excess for others. It embodies the minimal of Berlin clubs, where sets last for hours.","queer_ballroom_axis":"Pas d'axe queer explicite pour le disque ; la scène des after berlinois mêle publics gays et hétéros.","queer_ballroom_axis_en":"No explicit queer axis for the record; Berlin's after-hours scene mixes gay and straight crowds.","why_this_record":"La minimale à son extrême.","why_this_record_en":"Minimal at its most extreme.","archive_ref":{"source":"energy-flash","note":"Simon Reynolds cite ce disque parmi ceux qui poussent encore la dance music vers l'inconnu (édition augmentée).","note_en":"Simon Reynolds cites this record among those still pushing dance music into new territory (expanded edition)."},"tags":["europe","machine"],"youtube":["JNleC-2Yiuk","H8_BAoVwoaM"],"verified":false,"city_en":"Frankfurt / Berlin","country_en":"Germany","spotify":{"id":"0H1UQcJXx2oXZhDRckrHgL"}}]},"machines":{"_meta":{"note":"Fiches éditoriales. Dates et chiffres de production indicatifs, à recouper avec les sources constructeur."},"machines":[{"id":"tr-808","name":"Roland TR-808 Rhythm Composer","maker":"Roland","year":1980,"type":"Boîte à rythmes analogique","synth_mode":"808","intended_use":"Accompagner des musiciens en studio ou en répétition par une batterie « réaliste » programmable.","hijack":"Elle n'imite aucune vraie batterie et se vend mal. Revendue à bas prix d'occasion, elle tombe entre les mains de l'électro new-yorkaise, du hip-hop puis des premiers producteurs de Chicago. Son kick, devenu une sinusoïde grave à longue décroissance, sert de basse : la « sub 808 ».","signature":"Kick-boom grave et tenu, clap sec, cowbell métallique, charleston fin.","house_usage":"Les tout premiers disques house de Chicago. Le clap 808 et le kick court calent les premiers grooves jack.","trivia":"Arrêtée après quelques années de production, elle est devenue l'une des machines les plus samplées de l'histoire.","tracks":["on-and-on","dont-make-me-wait","voodoo-ray","yo-yo-get-funky"],"type_en":"Analogue drum machine","intended_use_en":"To accompany musicians in the studio or rehearsal room with a programmable, \"realistic\" drum kit.","hijack_en":"It sounded like no real drum kit and sold poorly. Resold cheap on the second-hand market, it fell into the hands of New York electro, hip-hop and then Chicago's first producers. Its kick, a deep sine wave with a long decay, doubles as a bassline: the \"808 sub\".","signature_en":"Deep, sustained boom kick, dry clap, metallic cowbell, thin hi-hat.","house_usage_en":"The very first Chicago house records. The 808 clap and short kick lock in the earliest jack grooves.","trivia_en":"Discontinued after a few years of production, it became one of the most sampled machines in history."},{"id":"tr-909","name":"Roland TR-909 Rhythm Composer","maker":"Roland","year":1983,"type":"Boîte à rythmes hybride (analogique + échantillons 6-bit)","synth_mode":"909","intended_use":"Succéder à la 808 avec des sons plus réalistes (cymbales échantillonnées) et une synchronisation MIDI.","hijack":"Jugée trop chère et peu crédible à sa sortie, elle est soldée. Son kick punchy, à attaque claquante, devient l'unité de mesure de la house et de la techno, tandis que ses charlestons ouverts définissent le « off-beat » de la piste de danse.","signature":"Kick percutant à attaque marquée, open hat sur le contretemps, clap large, snare bruitée.","house_usage":"Detroit, deep house, filter house parisienne, tech house : elle structure presque toute la house des années 85-2000.","trivia":"C'est l'une des premières boîtes Roland avec MIDI, ce qui la rend compatible avec les séquenceurs naissants.","tracks":["strings-of-life","big-fun","can-you-feel-it","da-funk","right-on","frozen-calderone","music-is-the-answer"],"type_en":"Hybrid drum machine (analogue + 6-bit samples)","intended_use_en":"To succeed the 808 with more realistic sounds (sampled cymbals) and MIDI sync.","hijack_en":"Judged too expensive and unconvincing at launch, it was sold off cheap. Its punchy, snapping kick became the unit of measure of house and techno, while its open hats defined the dancefloor's off-beat.","signature_en":"Punchy kick with a hard attack, off-beat open hat, wide clap, noisy snare.","house_usage_en":"Detroit, deep house, Parisian filter house, tech house: it underpins almost all house from 1985 to 2000.","trivia_en":"One of Roland's first drum machines with MIDI, which made it compatible with the emerging sequencers."},{"id":"tr-707","name":"Roland TR-707","maker":"Roland","year":1985,"type":"Boîte à rythmes à échantillons numériques","synth_mode":"909","intended_use":"Une boîte à rythmes abordable aux sons « réalistes » pour les groupes pop et les home-studios.","hijack":"Bon marché et simple, elle équipe les chambres de Chicago. Sa sécheresse numérique et son swing rigide fabriquent le son raw et jack de Trax Records. C'est elle qu'on entend derrière la 303 de « Acid Tracks ».","signature":"Sons courts et secs, peu de réglages, rimshot et cowbell très « années 80 ».","house_usage":"Chicago jack, acid house, premiers disques de Detroit.","trivia":"Son écran en grille permet de programmer visuellement : une interface parfaite pour des autodidactes.","tracks":["acid-tracks","move-your-body"],"type_en":"Digital sample-based drum machine","intended_use_en":"An affordable drum machine with \"realistic\" sounds for pop bands and home studios.","hijack_en":"Cheap and simple, it filled Chicago bedrooms. Its digital dryness and stiff swing shaped the raw, jacking sound of Trax Records: it is the machine behind the 303 on \"Acid Tracks\".","signature_en":"Short, dry sounds, few parameters, very \"eighties\" rimshot and cowbell.","house_usage_en":"Chicago jack, acid house, early Detroit records.","trivia_en":"Its grid display allowed visual programming: the perfect interface for self-taught producers."},{"id":"tb-303","name":"Roland TB-303 Bass Line","maker":"Roland","year":1981,"type":"Synthétiseur basse monophonique à séquenceur","synth_mode":"303","intended_use":"Remplacer le bassiste pour les guitaristes qui répètent seuls.","hijack":"C'est un échec commercial : elle ne sonne pas du tout comme une basse électrique et sort du catalogue en quelques années. À Chicago, Phuture tourne en direct le cutoff, la résonance, l'accent et le slide. La basse se met à « parler » et l'acid house est née de cet accident.","signature":"Filtre résonant 18 dB qui siffle, glissandos (slide), accents qui claquent.","house_usage":"Acid house (Chicago puis Manchester), acid techno, citations chez Daft Punk.","trivia":"Sa programmation est si peu intuitive que beaucoup de patterns célèbres sont nés d'erreurs ou de piles retirées qui effaçaient la mémoire.","tracks":["acid-tracks","voodoo-ray","da-funk"],"type_en":"Monophonic bass synthesizer with sequencer","intended_use_en":"To replace the bass player for guitarists rehearsing alone.","hijack_en":"A commercial flop: it sounded nothing like an electric bass and was discontinued within a few years. In Chicago, Phuture twisted the cutoff, resonance, accent and slide live. The bass started to \"talk\", and acid house was born from that accident.","signature_en":"Squelching 18 dB resonant filter, glides (slide), snapping accents.","house_usage_en":"Acid house (Chicago, then Manchester), acid techno, nods by Daft Punk.","trivia_en":"Its programming is so counter-intuitive that many famous patterns came from mistakes, or from batteries removed and wiping the memory."},{"id":"dx100","name":"Yamaha DX100","maker":"Yamaha","year":1985,"type":"Synthétiseur FM 4 opérateurs (mini-clavier)","synth_mode":"808","intended_use":"Démocratiser la synthèse FM du DX7 dans un format compact et bon marché pour les amateurs.","hijack":"Ses presets, en particulier la basse « Solid Bass », deviennent une palette toute faite pour la house et la techno. Des producteurs sans formation trouvent dans ces sons d'usine des lignes de basse claquantes qui font plus de bruit que les basses analogiques.","signature":"Basse FM percussive et brillante, cloches, sons métalliques.","house_usage":"Lignes de basse house et techno de la fin des années 80 et du début des années 90.","trivia":"Son cousin le TX81Z (preset « Lately Bass ») joue le même rôle dans le module rack.","tracks":["big-fun"],"type_en":"4-operator FM synthesizer (mini keys)","intended_use_en":"To bring the DX7's FM synthesis to hobbyists in a compact, cheap format.","hijack_en":"Its presets, especially the \"Solid Bass\" patch, became a ready-made palette for house and techno. Untrained producers found in those factory sounds snapping basslines that cut through harder than analogue basses.","signature_en":"Percussive, bright FM bass, bells, metallic tones.","house_usage_en":"House and techno basslines of the late 80s and early 90s.","trivia_en":"Its rack-module cousin, the TX81Z (\"Lately Bass\" preset), played the same role."},{"id":"mpc60","name":"Akai MPC60 MIDI Production Center","maker":"Akai (conçu avec Roger Linn)","year":1988,"type":"Sampler / séquenceur à pads","synth_mode":"909","intended_use":"Une station de production complète pour le studio : échantillonnage, séquençage et pads de jeu.","hijack":"Les pads sensibles et le swing de quantification signé Roger Linn donnent un groove « humain » aux boucles. Le hip-hop s'en empare, puis les producteurs garage et house new-yorkais qui jouent les samples comme des percussions.","signature":"Swing MPC, échantillonnage 12-bit chaleureux, jeu au doigt.","house_usage":"Garage new-yorkais, house samplée, plus tard UK garage.","trivia":"Le « swing MPC » est devenu une catégorie à part entière dans les logiciels modernes.","tracks":["ha-dance"],"maker_en":"Akai (designed with Roger Linn)","type_en":"Pad-based sampler / sequencer","intended_use_en":"A complete studio production station: sampling, sequencing and playable pads.","hijack_en":"Velocity-sensitive pads and Roger Linn's quantise swing gave loops a \"human\" groove. Hip-hop seized on it, then New York garage and house producers who played samples like percussion.","signature_en":"MPC swing, warm 12-bit sampling, finger-drumming.","house_usage_en":"New York garage, sample-based house, later UK garage.","trivia_en":"\"MPC swing\" has become a category of its own in modern software."},{"id":"sp-1200","name":"E-mu SP-1200","maker":"E-mu Systems","year":1987,"type":"Boîte à rythmes échantillonneuse 12-bit","synth_mode":"808","intended_use":"Une boîte à rythmes de studio à sons personnalisables par échantillonnage.","hijack":"Sa faible fréquence d'échantillonnage (environ 26 kHz) et ses quelques secondes de mémoire forcent les producteurs à sampler des disques en 45 tours puis à les ralentir. Il en sort un son granuleux et compressé qui définit le golden age du hip-hop et la house samplée de Todd Terry ou de Kenny Dope.","signature":"Grain 12-bit, sous-échantillonnage audible, filtres de sortie colorés.","house_usage":"Hip-house, garage samplé, house new-yorkaise de la fin des années 80.","trivia":"Sa limite de mémoire a littéralement dicté une technique de production : sampler vite, pitcher en bas.","tracks":["ill-house-you","ha-dance"],"type_en":"12-bit sampling drum machine","intended_use_en":"A studio drum machine whose sounds can be customised by sampling.","hijack_en":"Its low sample rate (around 26 kHz) and few seconds of memory forced producers to sample records at 45 rpm and pitch them down. The result, a gritty, compressed sound, defined hip-hop's golden age and the sample-based house of Todd Terry and Kenny Dope.","signature_en":"12-bit grit, audible aliasing, coloured output filters.","house_usage_en":"Hip-house, sampled garage, late-80s New York house.","trivia_en":"Its memory limit literally dictated a production technique: sample fast, pitch down."},{"id":"log-drum","name":"Log Drum (amapiano)","maker":"Son logiciel — FL Studio et presets partagés","year":2016,"type":"Basse percussive synthétisée (sound design)","synth_mode":"log","intended_use":"Ce n'est pas un instrument commercial : c'est un son sculpté dans un logiciel puis échangé entre producteurs.","hijack":"Inspirée du son d'un tambour en bois, la basse est le plus souvent produite sur FL Studio, logiciel partagé dans les townships. Sa paternité est souvent attribuée à MDU aka TRP. Elle joue à la fois le rôle de basse, de percussion et de mélodie, avec des glissandos qui deviennent la signature de l'amapiano.","signature":"Attaque boisée, sub qui glisse, notes courtes et chantantes, souvent sur le contretemps.","house_usage":"Amapiano, puis pop africaine et mondiale.","trivia":"Après le kick 909 et la basse 303, c'est le premier son « signature » de la house à naître dans un logiciel plutôt que dans une machine.","tracks":["ke-star","water-tyla"],"name_en":"Log Drum (amapiano)","maker_en":"Software sound: FL Studio and shared presets","type_en":"Synthesised percussive bass (sound design)","intended_use_en":"Not a commercial instrument: a sound sculpted in software and traded between producers.","hijack_en":"Inspired by the sound of a wooden slit drum, the bass is most often produced on FL Studio, software shared across the townships. It is often credited to MDU aka TRP. It plays bass, percussion and melody at once, with glides that became amapiano's signature.","signature_en":"Woody attack, gliding sub, short singing notes, often on the off-beat.","house_usage_en":"Amapiano, then African and global pop.","trivia_en":"After the 909 kick and the 303 bass, the first signature sound in house to be born in software rather than in a machine."},{"id":"moog-modular","name":"Moog modulaire","maker":"Moog Music","year":1964,"type":"Synthétiseur analogique modulaire","synth_mode":"303","intended_use":"Un instrument de laboratoire et de studio pour compositeurs expérimentaux et musique de film.","hijack":"À Munich, Giorgio Moroder l'emploie pour séquencer une ligne de basse disco entière : « I Feel Love » (1977) prouve qu'une machine peut porter un tube de piste. Le synthétiseur passe de l'avant-garde au dancefloor.","signature":"Basses épaisses, filtre 24 dB « ladder », séquences en arpège.","house_usage":"Disco électronique, hi-NRG, et par filiation toute la basse séquencée de la house.","trivia":"Programmer la séquence de « I Feel Love » demandait de synchroniser la machine avec la bande, une prouesse technique en 1977.","tracks":["i-feel-love"],"name_en":"Moog modular","type_en":"Modular analogue synthesizer","intended_use_en":"A lab and studio instrument for experimental composers and film music.","hijack_en":"In Munich, Giorgio Moroder used it to sequence an entire disco bassline: \"I Feel Love\" (1977) proved a machine could carry a dancefloor hit. The synthesizer moved from the avant-garde to the dancefloor.","signature_en":"Fat basses, 24 dB \"ladder\" filter, arpeggiated sequences.","house_usage_en":"Electronic disco, hi-NRG and, by descent, all of house's sequenced basslines.","trivia_en":"Programming the \"I Feel Love\" sequence meant syncing the machine to tape, a technical feat in 1977."},{"id":"korg-m1","name":"Korg M1 Music Workstation","maker":"Korg","year":1988,"type":"Workstation numérique (échantillons + synthèse)","synth_mode":"909","intended_use":"Une station tout-en-un pour compositeurs pop : sons réalistes, séquenceur, effets.","hijack":"Ses presets d'usine deviennent la signature de la house des années 90. Le piano « Piano 16' » fait les hymnes piano house, l'orgue « Organ 2 » fait la basse de « Show Me Love ». Les producteurs ne programment pas : ils détournent les presets.","signature":"Basse d'orgue percussive, piano house brillant, nappes numériques.","house_usage":"Piano house, garage vocal, italo house, puis revival 90s des années 2020.","trivia":"C'est l'un des synthétiseurs les plus vendus de son époque, ce qui explique l'omniprésence de ses presets.","tracks":["show-me-love"],"type_en":"Digital workstation (samples + synthesis)","intended_use_en":"An all-in-one station for pop songwriters: realistic sounds, sequencer, effects.","hijack_en":"Its factory presets became the signature of 90s house: the \"Piano 16'\" patch made the piano-house anthems, the \"Organ 2\" patch made the bassline of \"Show Me Love\". Producers didn't program, they hijacked presets.","signature_en":"Percussive organ bass, bright house piano, digital pads.","house_usage_en":"Piano house, vocal garage, Italo house, then the 2020s 90s revival.","trivia_en":"One of the best-selling synthesizers of its era, which explains how ubiquitous its presets became."}]},"sources":{"_meta":{"note":"Résumés éditoriaux de l'apport de chaque œuvre au projet. Les entrées marquées « to_verify » doivent être complétées (éditeur, date exacte) par l'équipe."},"sources":[{"id":"modulations","title":"Modulations","author":"Iara Lee (film) · Peter Shapiro (dir., livre)","year":1998,"type":"Film documentaire + livre","contribution":"C'est une généalogie panoramique de la musique électronique, des avant-gardes (Stockhausen, musique concrète) jusqu'à la techno, la house et la jungle. Sa thèse traverse tout le projet : les machines sont des instruments détournés, et chaque scène réinvente un outil prévu pour autre chose.","themes":["machines","généalogie","Detroit","Chicago"],"genres":["chicago","acid","detroit","french-touch"],"to_verify":false,"author_en":"Iara Lee (film) · Peter Shapiro (ed., book)","type_en":"Documentary film + book","themes_en":["machines","genealogy","Detroit","Chicago"],"contribution_en":"A panoramic genealogy of electronic music, from the avant-garde (Stockhausen, musique concrète) to techno, house and jungle. Its thesis runs through the whole project: machines are hijacked instruments, and every scene reinvents a tool designed for something else."},{"id":"paris-is-burning","title":"Paris Is Burning","author":"Jennie Livingston","year":1990,"type":"Film documentaire","contribution":"Le documentaire filme la ballroom new-yorkaise de la fin des années 80 : les houses, les mothers, les catégories, le « realness », le vogue (Willi Ninja), le shade et le reading. C'est la référence de l'axe queer et ballroom. Il aide aussi à penser la question de l'appropriation (Madonna, French Touch) et les débats sur le regard porté par une réalisatrice extérieure à la communauté.","themes":["ballroom","vogue","queer","trans","New York"],"genres":["garage-nyc","tribal-nyc","french-touch"],"to_verify":false,"type_en":"Documentary film","themes_en":["ballroom","vogue","queer","trans","New York"],"contribution_en":"The documentary films late-80s New York ballroom: houses, mothers, categories, realness, vogue (Willi Ninja), shade and reading. It is the reference for our queer and ballroom axis, and helps think through appropriation (Madonna, the French Touch) and the debates over the gaze of a filmmaker from outside the community."},{"id":"last-night-dj","title":"Last Night a DJ Saved My Life","author":"Bill Brewster & Frank Broughton","year":1999,"type":"Livre","contribution":"C'est l'histoire de référence du DJ, du sound system jamaïcain à la superstar des années 90. Elle documente la Loft de David Mancuso, le Paradise Garage, le Warehouse et la Music Box, et fait du DJ un auteur. Le livre sert d'ossature à nos récits de clubs et de filiation entre DJs. Mixmag et les communautés de DJs le citent régulièrement comme lecture fondatrice.","themes":["DJ","disco","clubs","New York","Chicago"],"genres":["chicago","garage-nyc","tribal-nyc","hip-house","french-touch"],"to_verify":false,"type_en":"Book","themes_en":["DJ","disco","clubs","New York","Chicago"],"contribution_en":"The reference history of the DJ, from the Jamaican sound system to the 90s superstar. It documents David Mancuso's Loft, the Paradise Garage, the Warehouse and the Music Box, and casts the DJ as an author. It is the backbone of our club stories and DJ lineages; Mixmag and DJ communities regularly cite it as a foundational read."},{"id":"history-of-house","title":"History of House","author":"Chris Kempster (dir.)","year":1996,"type":"Livre (recueil d'articles)","contribution":"Cette anthologie d'articles et d'entretiens publiés à chaud dans la presse musicale fait entendre les acteurs de Chicago, New York et du Royaume-Uni. Elle est précieuse pour les querelles de paternité (premier disque house, inventeur du hip-house) et pour saisir comment la scène se racontait elle-même.","themes":["Chicago","témoignages","presse","paternité"],"genres":["chicago","deep","hip-house","acid"],"to_verify":false,"author_en":"Chris Kempster (ed.)","type_en":"Book (collected articles)","themes_en":["Chicago","testimonies","press","authorship"],"contribution_en":"An anthology of articles and interviews published in the music press as things happened, giving voice to the players of Chicago, New York and the UK. Invaluable for authorship disputes (the first house record, who invented hip-house) and for how the scene told its own story."},{"id":"join-the-future","title":"Join the Future: Bleep Techno and the Birth of British Bass Music","author":"Matt Anniss","year":2019,"type":"Livre","contribution":"Le livre retrace la manière dont Sheffield, Leeds et Bradford ont transformé la house et la techno importées en « bleep », fondée sur le sub-bass et la culture sound system des Caraïbes. Il fournit le cadre de la lignée britannique des musiques bass qui mène à l'UK garage et au-delà.","themes":["Royaume-Uni","sound system","basses","diaspora caribéenne"],"genres":["detroit","ukg","afro"],"to_verify":false,"type_en":"Book","themes_en":["United Kingdom","sound system","bass","Caribbean diaspora"],"contribution_en":"How Sheffield, Leeds and Bradford turned imported house and techno into \"bleep\", built on sub-bass and Caribbean sound-system culture. It frames the British bass-music lineage that leads to UK garage and beyond."},{"id":"you-better-work","title":"« You Better Work! » Underground Dance Music in New York City","author":"Kai Fikentscher","year":2000,"type":"Livre (ethnomusicologie)","contribution":"C'est une ethnographie de la piste underground new-yorkaise des années 90, analysée comme un espace rituel afro-américain et gay. L'auteur étudie le DJ comme officiant, la danse comme langage et la musique comme lien communautaire. Le livre est central pour notre onglet sociologie.","themes":["ethnographie","New York","queer","rituel","danse"],"genres":["garage-nyc","tribal-nyc"],"to_verify":false,"type_en":"Book (ethnomusicology)","themes_en":["ethnography","New York","queer","ritual","dance"],"contribution_en":"An ethnography of the 1990s New York underground dancefloor as an African-American and gay ritual space: the DJ as officiant, dance as language, music as communal bond. Central to our sociology tab."},{"id":"adventures-wonderland","title":"Adventures in Wonderland: Acid House, Rave and the UK Club Explosion","author":"Sheryl Garratt","year":1998,"type":"Livre","contribution":"C'est le récit journalistique de la culture club britannique, d'Ibiza 1987 au Second Summer of Love, des raves aux superclubs. Garratt est attentive aux femmes, aux clubs gays et aux tensions de classe, et nous sert de source pour l'acid britannique et le balearic. (Réédité sous ce sous-titre ; première édition 1998 : « A Decade of Club Culture ».)","themes":["Royaume-Uni","rave","Ibiza","club culture"],"genres":["acid","balearic","tech-house"],"to_verify":false,"type_en":"Book","themes_en":["United Kingdom","rave","Ibiza","club culture"],"contribution_en":"A journalistic account of British club culture, from Ibiza 1987 and the Second Summer of Love to raves and superclubs. Garratt pays attention to women, gay clubs and class tensions; our source for British acid and balearic. (Reissued under this subtitle; first edition 1998: \"A Decade of Club Culture\".)"},{"id":"soul-underground","title":"Soul Underground","author":"Dave Pearce (fondateur et rédacteur en chef), avec Mark Webster, Gilles Peterson, Norman Jay, Chris Bangs, Judge Jules, Tony Monson, Maxine Gordon…","year":1987,"type":"Magazine mensuel (Londres, 1987–1991) · anthologie « Catch the Beat: Soul Underground 1987–91 » (DJhistory.com / Omnibus Press, 2021)","contribution":"Ce mensuel londonien indépendant et culte a documenté en temps réel, avant la presse musicale mainstream, la scène rare groove, l'arrivée du hip-hop, l'explosion de la house de Chicago, le garage new-yorkais et les premières raves britanniques. Sa rédaction réunit des DJs et acteurs majeurs de la scène (Gilles Peterson, Norman Jay, Judge Jules…). C'est une archive presse de première main, rééditée en anthologie en 2021.","themes":["presse","Londres","rare groove","hip-hop","Chicago house","garage","raves"],"genres":["chicago","hip-house","deep","garage-nyc","acid"],"to_verify":false,"author_en":"Dave Pearce (founder and editor), with Mark Webster, Gilles Peterson, Norman Jay, Chris Bangs, Judge Jules, Tony Monson, Maxine Gordon…","type_en":"Monthly magazine (London, 1987–1991) · anthology \"Catch the Beat: Soul Underground 1987–91\" (DJhistory.com / Omnibus Press, 2021)","themes_en":["press","London","rare groove","hip-hop","Chicago house","garage","raves"],"contribution_en":"A cult independent London monthly that documented in real time, ahead of the mainstream music press, the rare groove scene, the arrival of hip-hop, the Chicago house explosion, New York garage and the first British raves. Its contributors included key DJs and players (Gilles Peterson, Norman Jay, Judge Jules…). A first-hand press archive, reissued as an anthology in 2021."},{"id":"energy-never-dies","title":"Energy Never Dies: Afro-Optimism and Creativity in Chicago","author":"Ayana Contreras","year":2021,"type":"Livre (University of Illinois Press, 184 p.)","contribution":"Une histoire de la créativité noire de Chicago à travers l'« afro-optimisme » : comment musiciens, DJs, radios, labels et entrepreneurs culturels ont imaginé un avenir positif malgré la ségrégation et le déclin urbain. Le livre replace la house dans une généalogie locale plus longue (soul, radio, culture noire de Chicago) et nourrit notre lecture de la house comme projet d'espoir collectif.","themes":["Chicago","afro-optimisme","culture noire","radio","mémoire"],"genres":["chicago","deep","hip-house","acid"],"to_verify":false,"type_en":"Book (University of Illinois Press, 184 pp.)","themes_en":["Chicago","Afro-optimism","Black culture","radio","memory"],"contribution_en":"A history of Black creativity in Chicago through \"Afro-optimism\": how musicians, DJs, radio, labels and cultural entrepreneurs imagined a positive future despite segregation and urban decline. It places house within a longer local genealogy (soul, radio, Black Chicago culture) and informs our reading of house as a project of collective hope."},{"id":"rave-art","title":"Rave Art: Flyers, Invitations and Membership Cards from the Birth of Acid House Clubs and Raves","author":"Chelsea Louise Berlin","year":2009,"type":"Livre (iconographie)","contribution":"Une archive visuelle des flyers, invitations et cartes de membre de l'acid house et des raves (1987-1992). C'est notre source pour l'esthétique visuelle : le smiley, le futurisme, les numéros de téléphone secrets. Le graphisme y apparaît aussi comme un outil d'organisation clandestine.","themes":["flyers","graphisme","rave","Royaume-Uni"],"genres":["acid","rave-jungle"],"to_verify":false,"type_en":"Book (visual archive)","themes_en":["flyers","graphic design","rave","United Kingdom"],"contribution_en":"A visual archive of acid house and rave flyers, invitations and membership cards (1987–1992). Our source for the visual aesthetic: the smiley, futurism, secret phone numbers. Graphic design emerges as a tool of clandestine organisation."},{"id":"hacienda-hook","title":"The Haçienda: How Not to Run a Club","author":"Peter Hook","year":2009,"type":"Livre (mémoires)","contribution":"Le bassiste de New Order, copropriétaire du club, raconte l'Haçienda de 1982 à 1997 : l'utopie de Factory, l'explosion acid de 1988, les gangs, l'ecstasy, les dettes. Un contrepoint précieux au mythe de « Madchester ».","themes":["Manchester","Haçienda","économie du club","violence"],"genres":["acid","rave-jungle"],"to_verify":false,"type_en":"Book (memoir)","themes_en":["Manchester","Haçienda","club economics","violence"],"contribution_en":"New Order's bassist, the club's co-owner, recounts the Haçienda from 1982 to 1997: Factory's utopia, the 1988 acid explosion, gangs, ecstasy, debts. A valuable counterpoint to the \"Madchester\" myth."},{"id":"techno-shuffle","title":"Techno Shuffle: Rave Culture and the Melbourne Underground","author":"Paul Fleckney","year":2018,"type":"Livre (Melbourne Books, Australie)","contribution":"Le livre retrace l'explosion des raves en entrepôt à Melbourne dans les années 1990, dans le sillage de New York 1978 et de Londres 1988, et la naissance d'une danse propre à la ville, le Melbourne Shuffle. Il décentre le récit vers l'Australie : une scène locale qui invente ses propres gestes à partir de la house, de la techno et de la trance importées.","themes":["Melbourne","Australie","raves en entrepôt","Melbourne Shuffle","danse"],"genres":["rave-jungle","trance","tech-house"],"to_verify":false,"type_en":"Book (Melbourne Books, Australia)","themes_en":["Melbourne","Australia","warehouse raves","Melbourne Shuffle","dance"],"contribution_en":"Traces the explosion of warehouse raves in 1990s Melbourne, in the wake of New York 1978 and London 1988, and the birth of the city's own dance, the Melbourne Shuffle. It shifts the story to Australia: a local scene inventing its own moves from imported house, techno and trance."},{"id":"techno-rebels","title":"Techno Rebels: The Renegades of Electronic Funk","author":"Dan Sicko","year":1999,"type":"Livre","contribution":"L'histoire de référence de la techno de Detroit, de Juan Atkins à Underground Resistance. Elle relie la techno à la ville post-industrielle, à l'électro, à la radio (The Electrifying Mojo) et à l'éthique de l'indépendance.","themes":["Detroit","techno","Belleville Three","indépendance"],"genres":["detroit"],"to_verify":false,"type_en":"Book","themes_en":["Detroit","techno","Belleville Three","independence"],"contribution_en":"The reference history of Detroit techno, from Juan Atkins to Underground Resistance. It ties techno to the post-industrial city, to electro, to radio (The Electrifying Mojo) and to an ethic of independence."},{"id":"class-of-88","title":"Class of '88: Find the Warehouse. Lose the Hitmen. Pump the Beats","author":"Wayne Anthony","year":1998,"type":"Livre (mémoires)","contribution":"Les mémoires d'un organisateur de raves illégales (Genesis) de la fin des années 80 : warehouses, convois, police, gangsters. C'est le point de vue de l'organisateur, de l'économie souterraine de la rave.","themes":["warehouse","raves illégales","Londres","police"],"genres":["acid","chicago","rave-jungle"],"to_verify":false,"type_en":"Book (memoir)","themes_en":["warehouse","illegal raves","London","police"],"contribution_en":"The memoir of an illegal-rave organiser (Genesis) in the late 80s: warehouses, convoys, police, gangsters. The promoter's view of rave's underground economy."},{"id":"real-story-saunders","title":"House Music… The Real Story","author":"Jesse Saunders (avec James Cummins)","year":2007,"type":"Livre (autobiographie, 167 p., SandlerComm)","contribution":"Le récit autobiographique de Jesse Saunders, auteur de « On and On », sur les débuts de la house à Chicago : production, DJing, diffusion du son. C'est un témoignage partisan et précieux sur les querelles de paternité, les pressages et les labels (Trax, DJ International).","themes":["Chicago","témoignage","paternité","labels"],"genres":["chicago","deep","acid"],"to_verify":false,"author_en":"Jesse Saunders (with James Cummins)","type_en":"Book (autobiography, 167 pp., SandlerComm)","themes_en":["Chicago","testimony","authorship","labels"],"contribution_en":"Jesse Saunders's autobiographical account, by the man behind \"On and On\", of house's beginnings in Chicago: production, DJing, the spread of the sound. A partisan but valuable testimony on authorship disputes, pressings and labels (Trax, DJ International)."},{"id":"full-on","title":"Full On. Non-Stop. All Over.","author":"Matthew Smith (photographies et essai) ; préface de Simon Reynolds ; édité par Davy Reed","year":2021,"type":"Livre photographique (TRIP Publishing, Royaume-Uni)","contribution":"Un livre photographique sur les raves et la culture club britannique entre 2000 et 2005 (« Human Rave Behaviour »), au tournant de l'ère numérique, juste avant les smartphones. Il prolonge Energy Flash, dont l'auteur Simon Reynolds signe la préface, en montrant les corps et les publics de l'après-âge d'or : UK garage, tech house, superclubs.","themes":["photographie","Royaume-Uni","2000-2005","publics","ère numérique"],"genres":["ukg","tech-house","rave-jungle"],"to_verify":false,"author_en":"Matthew Smith (photographs and essay); foreword by Simon Reynolds; edited by Davy Reed","type_en":"Photobook (TRIP Publishing, UK)","themes_en":["photography","United Kingdom","2000–2005","crowds","digital age"],"contribution_en":"A photobook on British rave and club culture between 2000 and 2005 (\"Human Rave Behaviour\"), at the turn of the digital age, just before smartphones. It extends Energy Flash, whose author Simon Reynolds wrote the foreword, by showing the bodies and crowds of the post-golden age: UK garage, tech house, superclubs."},{"id":"carl-cox-oh-yes","title":"Oh Yes, Oh Yes!","author":"Carl Cox & Ian Winwood","year":2021,"type":"Livre (autobiographie, White Rabbit)","contribution":"Le parcours de Carl Cox, des sound systems et mariages du sud de Londres à l'acid house de 1988, aux raves puis aux résidences à Ibiza. C'est notre source pour l'axe acid house UK, raves et Ibiza, et une autre généalogie de la house : noire, britannique et caribéenne.","themes":["acid house UK","raves","Ibiza","DJ","black british"],"genres":["acid","rave-jungle","balearic","tech-house"],"to_verify":false,"type_en":"Book (autobiography, White Rabbit)","themes_en":["UK acid house","raves","Ibiza","DJ","Black British"],"contribution_en":"Carl Cox's path from south London sound systems and weddings to 1988 acid house, the raves and his Ibiza residencies. Our source for UK acid house, rave and Ibiza, and another genealogy of house: Black, British and Caribbean."},{"id":"disco-files","title":"The Disco Files 1973–78: New York's Underground, Week by Week","author":"Vince Aletti","year":2009,"type":"Livre (chroniques ; DJhistory.com 2009, réédition D.A.P. 2018)","contribution":"Les colonnes hebdomadaires d'Aletti dans Record World : ce que jouent les DJs du Loft, du Gallery, du Paradise Garage avant les charts. Un document de première main sur la naissance de la disco underground.","themes":["disco","New York","presse","DJ"],"genres":["disco","garage-nyc"],"to_verify":false,"type_en":"Book (columns; DJhistory.com 2009, D.A.P. reissue 2018)","themes_en":["disco","New York","press","DJ"],"contribution_en":"Aletti's weekly Record World columns: what DJs at the Loft, the Gallery and the Paradise Garage were playing before the charts caught on. A first-hand document of underground disco's birth."},{"id":"porcelain","title":"Porcelain: A Memoir","author":"Moby","year":2016,"type":"Livre (mémoires)","contribution":"Les mémoires de Moby à New York entre 1989 et 1999 : la pauvreté, les clubs (Mars, Limelight), la rave américaine naissante. Un regard d'intérieur sur la scène mixte et queer des clubs new-yorkais.","themes":["New York","rave","clubs","mémoires"],"genres":["rave-jungle","tribal-nyc"],"to_verify":false,"type_en":"Book (memoir)","themes_en":["New York","rave","clubs","memoir"],"contribution_en":"Moby's memoir of New York between 1989 and 1999: poverty, the clubs (Mars, Limelight), the emerging American rave scene. An insider's view of the mixed and queer New York club scene."},{"id":"electrochoc","title":"Electrochoc","author":"Laurent Garnier & David Brun-Lambert","year":2003,"type":"Livre (autobiographie)","contribution":"L'autobiographie de référence de Laurent Garnier et une histoire de la techno vue par l'un de ses acteurs. Elle commence à Manchester, où le jeune Français découvre la house à l'Haçienda à la fin des années 80 et y devient DJ. Elle se poursuit avec le retour en France : la répression des raves, les clubs parisiens (Palace, Rex) et la création de F Communications. C'est la référence pour Manchester vue de l'intérieur et pour la scène française.","themes":["Manchester","Haçienda","techno","France","raves"],"genres":["acid","detroit","french-touch"],"to_verify":false,"type_en":"Book (autobiography)","themes_en":["Manchester","Haçienda","techno","France","raves"],"contribution_en":"Laurent Garnier's definitive autobiography and a history of techno told by one of its protagonists. It opens in Manchester, where the young Frenchman discovered house at the Haçienda in the late 80s and became a DJ there, then follows his return to France: the crackdown on raves, the Paris clubs (Palace, Rex) and the founding of F Communications. The reference for Manchester from the inside and for the French scene."},{"id":"underground-massive","title":"The Underground Is Massive: How Electronic Dance Music Conquered America","author":"Michaelangelo Matos","year":2015,"type":"Livre","contribution":"L'histoire de la dance music aux États-Unis, des raves du Midwest à l'EDM des années 2010. Elle montre le paradoxe américain : le pays invente la house et la techno, puis les redécouvre par l'Europe.","themes":["États-Unis","rave","EDM","industrie"],"genres":["detroit","garage-nyc","tech-house","rave-jungle"],"to_verify":false,"type_en":"Book","themes_en":["United States","rave","EDM","industry"],"contribution_en":"The history of dance music in the United States, from Midwest raves to 2010s EDM. It shows the American paradox: the country invented house and techno, then rediscovered them through Europe."},{"id":"brickwork-arches","title":"Brickwork: A Biography of The Arches","author":"David Bratchpiece & Kirstin Innes","year":2021,"type":"Livre (Salamander Street, 2021)","contribution":"La biographie des Arches, voûtes de briques sous la gare centrale de Glasgow, à la fois théâtre, lieu d'art et club, fermé en 2015. C'est notre source pour la scène club écossaise : les soirées Slam, le label Soma Records et ses premiers maxis de Daft Punk.","themes":["Glasgow","Slam","Soma Records","lieu","licence"],"genres":["tech-house","french-touch"],"to_verify":false,"type_en":"Book (Salamander Street, 2021)","themes_en":["Glasgow","Slam","Soma Records","venue","licensing"],"contribution_en":"The biography of the Arches, brick vaults beneath Glasgow Central Station that were theatre, arts venue and club at once, closed in 2015. Our source for the Scottish club scene: the Slam nights, Soma Records and its first Daft Punk releases."},{"id":"rave-on","title":"Rave On: Global Adventures in Electronic Dance Music","author":"Matthew Collin","year":2018,"type":"Livre","contribution":"Un reportage mondial sur les scènes électroniques, de Berlin à Tbilissi, de Shanghai à Las Vegas. Il sert à penser la house comme culture globale et politique, après les grands récits britanniques.","themes":["global","politique","Berlin","reportage"],"genres":["trance","tech-house","afro","chicago"],"to_verify":false,"type_en":"Book","themes_en":["global","politics","Berlin","reportage"],"contribution_en":"A global report on electronic scenes, from Berlin to Tbilisi, from Shanghai to Las Vegas. It helps think of house as a global and political culture, beyond the great British narratives."},{"id":"state-of-bass","title":"State of Bass: The Origins of Jungle/Drum & Bass","author":"Martin James","year":1997,"type":"Livre","contribution":"L'histoire des origines de la jungle : du hardcore aux sound systems, des radios pirates aux labels (Metalheadz, Good Looking). C'est la référence pour la lignée bass britannique, après le bleep de Join the Future.","themes":["jungle","drum & bass","sound system","Londres"],"genres":["rave-jungle","ukg"],"to_verify":false,"type_en":"Book","themes_en":["jungle","drum & bass","sound system","London"],"contribution_en":"The origins of jungle: from hardcore to sound systems, from pirate radio to labels (Metalheadz, Good Looking). The reference for the British bass lineage after Join the Future's bleep."},{"id":"hot-stuff","title":"Hot Stuff: Disco and the Remaking of American Culture","author":"Alice Echols","year":2010,"type":"Livre (histoire culturelle)","contribution":"Une histoire culturelle de la disco : sa place dans les cultures gays, noires et féministes et sa redéfinition des genres et des sexualités. On y lit aussi le backlash du « Disco Sucks ». C'est indispensable pour comprendre de quoi la house hérite.","themes":["disco","queer","genre","backlash"],"genres":["disco","garage-nyc","french-touch"],"to_verify":false,"type_en":"Book (cultural history)","themes_en":["disco","queer","gender","backlash"],"contribution_en":"A cultural history of disco: its place in gay, Black and feminist cultures and how it redefined gender and sexuality, plus the \"Disco Sucks\" backlash. Essential to understand what house inherits."},{"id":"sonic-youth-floor","title":"Sonic Youth Slept on My Floor: Music, Manchester, and More","author":"Dave Haslam","year":2018,"type":"Livre (mémoires)","contribution":"Les mémoires de Dave Haslam, DJ résident de l'Haçienda, de 1986 à 1997. C'est la ville vue par un DJ et un journaliste, entre rock indé, house et culture locale.","themes":["Manchester","Haçienda","DJ","mémoires"],"genres":["acid"],"to_verify":false,"type_en":"Book (memoir)","themes_en":["Manchester","Haçienda","DJ","memoir"],"contribution_en":"The memoir of Dave Haslam, Haçienda resident DJ from 1986 to 1997: the city seen by a DJ and journalist, between indie rock, house and local culture."},{"id":"hypnotised","title":"Hypnotised: A Journey Through Trance Music (1990–2005)","author":"Arjan Rietveld","year":2022,"type":"Livre (Mary Go Wild, Pays-Bas)","contribution":"Le livre retrace l'essor de la progressive house et de la trance européenne entre 1990 et 2005 : de l'acid house et des clubs britanniques et ibizencs jusqu'aux grands rassemblements néerlandais. Il situe la trance comme une ramification européenne de la house, devenue culture de masse.","themes":["trance","progressive house","Ibiza","Royaume-Uni","Pays-Bas"],"genres":["trance","balearic","acid"],"to_verify":false,"type_en":"Book (Mary Go Wild, Netherlands)","themes_en":["trance","progressive house","Ibiza","United Kingdom","Netherlands"],"contribution_en":"Traces the rise of progressive house and European trance from 1990 to 2005: from acid house and British and Ibizan clubs to the big Dutch gatherings. It places trance as a European offshoot of house that became mass culture."},{"id":"second-summer","title":"The Second Summer of Love: How Dance Music Took Over the World","author":"Alon Shulman","year":2019,"type":"Livre (John Blake)","contribution":"Comment la house et l'acid house passent des États-Unis au Royaume-Uni à la fin des années 80 et transforment le clubbing britannique puis mondial. C'est le récit du basculement culturel de 1988-1989 : raves, presse, panique morale, puis industrie.","themes":["1988","acid house","Royaume-Uni","rave"],"genres":["acid","chicago","rave-jungle","balearic"],"to_verify":false,"type_en":"Book (John Blake)","themes_en":["1988","acid house","United Kingdom","rave"],"contribution_en":"How house and acid house crossed from the US to the UK in the late 80s and transformed British, then global, clubbing. The story of the 1988–1989 cultural shift: raves, press, moral panic, then industry."},{"id":"musique-house-bidder","title":"Musique house","author":"Sean Bidder","year":null,"type":"Livre (guide ; édition originale : The Rough Guide to House Music, 1999)","contribution":"Le guide de référence en français. Il couvre l'essor de la house à Chicago, New York et Londres à la fin des années 80, puis la French Touch (Laurent Garnier, Dimitri from Paris, Ludovic Navarre). C'est notre porte d'entrée francophone sur l'histoire du genre.","themes":["guide","Chicago","New York","Londres","France"],"genres":["chicago","garage-nyc","deep","french-touch"],"to_verify":false,"type_en":"Book (guide; original edition: The Rough Guide to House Music, 1999)","themes_en":["guide","Chicago","New York","London","France"],"contribution_en":"The reference guide in French. It covers house's rise in Chicago, New York and London in the late 80s, then the French Touch (Laurent Garnier, Dimitri from Paris, Ludovic Navarre). Our French-language entry point into the genre's history."},{"id":"beat-scene-sound","title":"The Beat, The Scene, The Sound: A DJ's Journey Through the Rise, Fall, and Rebirth of House Music in New York City","author":"DJ Disciple & Henry Kronk","year":2023,"type":"Livre (mémoires, Rowman & Littlefield ; préface de Louie Vega)","contribution":"La house new-yorkaise vue de l'intérieur par un DJ, avec ses promoteurs et ses publics : l'essor, la chute (fermetures de clubs, années Giuliani) et la renaissance. C'est un récit de scène plutôt qu'un panorama, précieux pour le garage et le tribal des années 90.","themes":["New York","DJ","clubs","années 90"],"genres":["garage-nyc","tribal-nyc"],"to_verify":false,"type_en":"Book (memoir, Rowman & Littlefield; foreword by Louie Vega)","themes_en":["New York","DJ","clubs","1990s"],"contribution_en":"New York house from the inside, through a DJ, his promoters and crowds: the rise, the fall (club closures, the Giuliani years) and the rebirth. A scene story rather than an overview, invaluable for 90s garage and tribal."},{"id":"decade-house-bleakman","title":"1990–2000: The Decade That Was House Music","author":"James Bleakman","year":2026,"type":"Livre (mémoires ; ebook et audio, 1er septembre 2026)","contribution":"Les mémoires d'un passionné sur la façon dont la house a façonné le collectionnement de disques, le clubbing et la culture DJ dans les années 90, de l'écoute dans la chambre aux grandes dates des clubs. C'est le point de vue du public, celui du fan, sur la décennie.","themes":["années 90","collection","clubbing","fans"],"genres":["garage-nyc","french-touch","tech-house","ukg"],"to_verify":false,"type_en":"Book (memoir; ebook and audio, 1 September 2026)","themes_en":["1990s","collecting","clubbing","fans"],"contribution_en":"A devotee's memoir of how house shaped record collecting, clubbing and DJ culture in the 1990s, from bedroom listening to landmark club nights. The audience's, the fan's, view of the decade."},{"id":"energy-flash","title":"Energy Flash: A Journey Through Rave Music and Dance Culture","author":"Simon Reynolds","year":1998,"type":"Livre (en anglais ; publié aux États-Unis sous le titre « Generation Ecstasy »)","contribution":"La grande histoire critique de la rave, de Detroit et Chicago à l'acid house, au hardcore, à la jungle, à la trance et au UK garage. Reynolds analyse les sons (le « hardcore continuum »), les drogues et les corps : c'est le cadre théorique de nos lignées britanniques.","themes":["rave","hardcore continuum","ecstasy","critique"],"genres":["acid","rave-jungle","ukg","detroit","trance"],"to_verify":false,"type_en":"Book (published in the US as \"Generation Ecstasy\")","themes_en":["rave","hardcore continuum","ecstasy","criticism"],"contribution_en":"The great critical history of rave, from Detroit and Chicago to acid house, hardcore, jungle, trance and UK garage. Reynolds analyses sounds (the \"hardcore continuum\"), drugs and bodies: the theoretical frame for our British lineages."},{"id":"turn-the-beat-around","title":"Turn the Beat Around: The Secret History of Disco","author":"Peter Shapiro","year":2005,"type":"Livre","contribution":"Une histoire de la disco comme musique de libération (gay, noire, féminine), puis comme industrie, jusqu'au backlash « Disco Sucks ». Shapiro, qui a aussi dirigé le livre Modulations, montre la disco comme la matrice technique et sociale de la house.","themes":["disco","libération","backlash","industrie"],"genres":["disco","garage-nyc","chicago"],"to_verify":false,"type_en":"Book","themes_en":["disco","liberation","backlash","industry"],"contribution_en":"A history of disco as a music of liberation (gay, Black, female), then as an industry, up to the \"Disco Sucks\" backlash. Shapiro, who also edited the Modulations book, shows disco as the technical and social matrix of house."},{"id":"do-you-remember-house","title":"Do You Remember House? Chicago's Queer of Color Undergrounds","author":"Micah E. Salkind","year":2019,"type":"Livre (histoire culturelle, universitaire)","contribution":"Une histoire de la house de Chicago recentrée sur les communautés queer noires et latines qui l'ont inventée, du Warehouse et de la Music Box aux soirées actuelles. Le livre fonde l'onglet Ballroom & queer : la house comme pratique de mémoire et de survie communautaire.","themes":["Chicago","queer of color","mémoire","communauté"],"genres":["chicago","acid","deep"],"to_verify":false,"type_en":"Book (cultural history, academic)","themes_en":["Chicago","queer of color","memory","community"],"contribution_en":"A history of Chicago house refocused on the Black and Latinx queer communities that invented it, from the Warehouse and the Music Box to today's parties. It grounds our Ballroom & queer tab: house as a practice of memory and communal survival."},{"id":"love-saves-the-day","title":"Love Saves the Day: A History of American Dance Music Culture, 1970–1979","author":"Tim Lawrence","year":2003,"type":"Livre (histoire, universitaire)","contribution":"L'histoire minutieuse des années 70 new-yorkaises : le Loft de David Mancuso, le Sanctuary, le Gallery, les débuts de Larry Levan et Frankie Knuckles, la naissance du 12\" et du remix. C'est la source la plus précise sur la préhistoire de la house.","themes":["Loft","New York","années 70","remix"],"genres":["disco","garage-nyc"],"to_verify":false,"type_en":"Book (history, academic)","themes_en":["Loft","New York","1970s","remix"],"contribution_en":"A meticulous history of 1970s New York: David Mancuso's Loft, the Sanctuary, the Gallery, the early days of Larry Levan and Frankie Knuckles, the birth of the 12\" and the remix. The most precise source on house's prehistory."},{"id":"how-music-works","title":"How Music Works","author":"David Byrne","year":2012,"type":"Livre (essai)","contribution":"Un essai général sur la manière dont les lieux, les technologies et l'économie façonnent la musique. Il ne porte pas spécifiquement sur le DJing, mais il éclaire une idée centrale du projet : un son est conçu pour un espace (le Paradise Garage, la warehouse, l'écouteur de téléphone).","themes":["espace","technologie","économie","essai"],"genres":["garage-nyc","lofi","amapiano"],"to_verify":false,"type_en":"Book (essay)","themes_en":["space","technology","economics","essay"],"contribution_en":"A general essay on how venues, technologies and economics shape music. Not specifically about DJing, but it illuminates a core idea of the project: a sound is designed for a space (the Paradise Garage, the warehouse, the phone earbud)."},{"id":"garnier-ramadier-2026","title":"Garnier","author":"Mathilde Ramadier","year":2026,"type":"Livre (biographie, Les Pérégrines, 160 p.)","type_en":"Book (biography, Les Pérégrines, 160 pp.)","contribution":"Une biographie de Laurent Garnier fondée sur de longs entretiens avec lui, de ses débuts à Manchester en 1987, quand il mixe sous le nom de DJ Pedro et fréquente l'Haçienda, jusqu'à sa carrière internationale. Elle complète Electrochoc par un regard extérieur.","contribution_en":"A biography of Laurent Garnier built on long conversations with him, from his beginnings in Manchester in 1987, when he played as DJ Pedro and frequented the Haçienda, to his international career. It complements Electrochoc with an outside view.","themes":["Laurent Garnier","Manchester","Haçienda","France","biographie"],"themes_en":["Laurent Garnier","Manchester","Haçienda","France","biography"],"genres":["french-touch","acid"],"to_verify":false}]},"metro":{"_meta":{"note":"Plan du métro généalogique. Coordonnées dans un viewBox 1200×700, tracés à 0°/45°/90°. Une station renvoie à des disques par genre (genres) et/ou par identifiant (tracks)."},"lines":[{"id":"L1","num":1,"name":"Chicago & Acid","color":"#ff5500","path":[[100,140],[790,140]],"stations":["loft","warehouse","chicago","acid","hiphouse","footwork"],"name_en":"Chicago & Acid"},{"id":"L2","num":2,"name":"NYC, Garage & Tribal","color":"#e6007e","path":[[240,320],[850,320]],"stations":["paradise","garage","zanzibar","ballroom","soundfactory","tribal"],"name_en":"NYC, Garage & Tribal"},{"id":"L3","num":3,"name":"Deep & gospel","color":"#00e5a8","path":[[380,230],[470,320]],"stations":["deep","zanzibar"],"name_en":"Deep & gospel"},{"id":"L4","num":4,"name":"UK Sound System & Bass","color":"#ffd000","path":[[500,230],[1010,230],[1100,320],[1100,620]],"stations":["soundsystem","shoom","bleep","hardcore","ukg","dubstep","charthouse"],"name_en":"UK Sound System & Bass"},{"id":"L5","num":5,"name":"Escales européennes","color":"#3b82f6","path":[[610,60],[1000,60],[1100,160]],"stations":["balearic","italo","french","techhouse"],"name_en":"European Stopovers"},{"id":"L6","num":6,"name":"Futurisme & Machines","color":"#a855f7","path":[[670,440],[900,440],[1010,550]],"stations":["electro","detroit","soundsig","lofi"],"name_en":"Futurism & Machines"},{"id":"L7","num":7,"name":"Ballroom & queer","name_en":"Ballroom & queer","color":"#f9a8d4","path":[[600,320],[600,720],[680,800],[940,800]],"stations":["ballroom","qweenbeat","renaissance"],"badge":[976,800]},{"id":"L8","num":8,"name":"Afriques","name_en":"Africas","color":"#84cc16","path":[[560,410],[560,640]],"stations":["afro","gqom","amapiano"],"badge":[560,678]},{"id":"L9","num":9,"name":"Techno & Europe","name_en":"Techno & Europe","color":"#94a3b8","path":[[780,440],[780,540],[840,600],[930,690]],"stations":["detroit","trance","berlin"],"badge":[752,560]}],"stations":{"loft":{"name":"Disco / The Loft","years":"1970–1979","x":100,"y":140,"label":"above","summary":"En 1970, David Mancuso ouvre le Loft à New York : des fêtes privées sur invitation où le son, la sélection et la nuit entière deviennent un art. Tom Moulton invente le remix dansant, le breakdown et le format 12\" (acétates dès 1974) ; Salsoul commercialise en 1976 le premier 12\" vendu au public, « Ten Percent ».","genres":["disco"],"machines":["moog-modular"],"links":["paradise"],"summary_en":"In 1970 David Mancuso opened the Loft in New York: private, invitation-only parties where sound, selection and the whole night became an art. Tom Moulton invented the dance remix, the breakdown and the 12\" format (acetates from 1974); in 1976 Salsoul released the first 12\" sold to the public, \"Ten Percent\".","tracks":["ten-percent"]},"warehouse":{"name":"The Warehouse","years":"1977–1982","x":240,"y":140,"label":"above","summary":"Le club de Chicago où Frankie Knuckles mixe de 1977 à novembre 1982 (départ pour le Power Plant) pour un public majoritairement noir et gay. L'origine du mot « house » circule en trois versions concurrentes : un panneau vu par Knuckles, les bacs « As heard at the Warehouse » du disquaire Importes Etc., ou un terme générique pour la disco.","tracks":["your-love","love-is-the-message"],"machines":["tr-909"],"summary_en":"The Chicago club where Frankie Knuckles played from 1977 to November 1982 (when he left for the Power Plant) to a mostly Black and gay crowd. The origin of the word \"house\" circulates in three competing versions: a sign Knuckles saw, the \"As heard at the Warehouse\" bins at the Importes Etc. record shop, or a generic term for disco."},"chicago":{"name":"Chicago House","years":"1984–1989","x":380,"y":140,"label":"above","summary":"Ron Hardy à la Music Box, la radio WBMX, Trax et DJ International : la disco se reprogramme sur des boîtes à rythmes bon marché. Jack, piano house et deep house naissent en trois ans.","genres":["chicago"],"machines":["tr-808","tr-707"],"links":["detroit","french"],"summary_en":"Ron Hardy at the Music Box, WBMX radio, Trax and DJ International: disco reprogrammed on cheap drum machines. Jack, piano house and deep house were all born within three years."},"acid":{"name":"Acid House","years":"1985–1989","x":520,"y":140,"label":"above","summary":"Phuture tourne en direct les potentiomètres d'une TB-303 d'occasion, et Ron Hardy joue la cassette à la Music Box. La basse se met à « parler » : l'acid est née d'un détournement.","genres":["acid"],"machines":["tb-303","tr-707"],"summary_en":"Phuture twisted the knobs of a second-hand TB-303 live, and Ron Hardy played the tape at the Music Box. The bass started to \"talk\": acid was born from a hijack.","tracks":["higher-state-of-consciousness"]},"hiphouse":{"name":"Hip-House","years":"1988–1990","x":660,"y":140,"label":"above","summary":"Chicago et New York tentent de marier le kick house et le flow rap. Le MC remplace la diva, et le genre sert de format crossover vers les clubs hétéros et les charts.","genres":["hip-house"],"machines":["tr-808","sp-1200"],"summary_en":"Chicago and New York tried to marry the house kick and the rap flow. The MC replaced the diva, and the genre served as a crossover format for straight clubs and the charts."},"paradise":{"name":"Paradise Garage","years":"1977–1987","x":240,"y":320,"label":"below","summary":"Au 84 King Street, Larry Levan fait de la piste une église pour un public noir et latino majoritairement gay : soul, gospel, effets dub et un système son légendaire. Le mot « garage » vient de là.","tracks":["dont-make-me-wait","love-is-the-message","love-sensation","is-it-all-over-my-face"],"machines":["tr-808"],"links":["loft"],"summary_en":"At 84 King Street, Larry Levan turned the dancefloor into a church for a mostly gay Black and Latino crowd: soul, gospel, dub effects and a legendary sound system. The word \"garage\" comes from here."},"garage":{"name":"Garage House (NYC/NJ)","years":"1988–1999","x":355,"y":320,"label":"above","summary":"La house vocale de New York et du New Jersey : voix gospel, orgues, grooves souples. Masters At Work, Strictly Rhythm et Nervous Records en font un son mondial, que Londres accélérera en UK garage.","genres":["garage-nyc"],"machines":["korg-m1","mpc60","sp-1200"],"links":["ukg"],"summary_en":"Vocal house from New York and New Jersey: gospel voices, organs, loose grooves. Masters At Work, Strictly Rhythm and Nervous Records made it a global sound, which London would speed up into UK garage."},"zanzibar":{"name":"Club Zanzibar (NJ)","years":"1979–années 90","x":470,"y":320,"label":"below-left","interchange":true,"summary":"À Newark (New Jersey), le Zanzibar ouvre en 1979 ; Tony Humphries y est résident de 1982 à 1994. Après la fermeture du Paradise Garage en 1987, le club devient un centre de la house de la région new-yorkaise. Le « Jersey sound » est gospel, porté notamment par Movin' Records (1987).","tracks":["reachin"],"years_en":"1979–1990s","summary_en":"In Newark, New Jersey, Zanzibar opened in 1979; Tony Humphries was resident from 1982 to 1994. After the Paradise Garage closed in 1987, the club became a centre of house in the New York area. The \"Jersey sound\" is gospel, carried notably by Movin' Records (1987)."},"ballroom":{"name":"Ballroom & Voguing","years":"1920s–","x":600,"y":320,"label":"below-left","summary":"La ballroom précède la house : ses origines remontent à la Harlem Renaissance. Le « Old Way » s'impose dans les années 1980 (House of LaBeija, House of Corey), le « New Way » au début des années 1990. Le lien avec la house arrive avec le Sound Factory (1989–1995) et « The Ha Dance » (1991) : chaque « Ha » appelle une pose.","tracks":["ha-dance","gypsy-woman","show-me-love","mighty-real","vogue"],"sources":["paris-is-burning"],"summary_en":"Ballroom predates house: its origins go back to the Harlem Renaissance. \"Old Way\" took hold in the 1980s (House of LaBeija, House of Corey), \"New Way\" in the early 1990s. The link with house came with the Sound Factory (1989–1995) and \"The Ha Dance\" (1991): every \"Ha\" calls for a pose.","years_en":"1920s–"},"soundfactory":{"name":"Sound Factory","years":"1989–1995","x":710,"y":320,"label":"above","summary":"Le club du 530 West 27th Street (1989–1995) où Junior Vasquez mixe des nuits entières pour un public majoritairement gay et de couleur, et fait entrer les houses de la ballroom dans le club. Le lieu devient ensuite le Twilo (1995–2001).","tracks":["beautiful-people","show-me-love"],"sources":["beat-scene-sound"],"summary_en":"The club at 530 West 27th Street (1989–1995) where Junior Vasquez played all night for a mostly gay crowd of colour and brought the ballroom houses into the club. The space later became Twilo (1995–2001)."},"tribal":{"name":"Tribal House NYC","years":"1995–2002","x":850,"y":320,"label":"below","summary":"Toms en cascade, percussions roulantes et remixes de divas pour les grands clubs gays de Manhattan (Twilo, Roxy) et les circuit parties. Danny Tenaglia et Victor Calderone en sont les architectes.","genres":["tribal-nyc"],"machines":["tr-909"],"summary_en":"Cascading toms, rolling percussion and diva remixes for Manhattan's big gay clubs (Twilo, Roxy) and the circuit parties. Danny Tenaglia and Victor Calderone were its architects."},"deep":{"name":"Deep House (Mr. Fingers)","years":"1986–","x":380,"y":230,"label":"left","summary":"Larry Heard, ancien batteur de jazz-fusion, apporte à la house des accords de septième, des nappes chaudes et un tempo retenu. La deep house nourrit le garage gospel du New Jersey ; son influence sur la house sud-africaine est une influence importée parmi d'autres, pas une filiation directe.","genres":["deep"],"machines":["tr-909"],"summary_en":"Larry Heard, a former jazz-fusion drummer, brought seventh chords, warm pads and a held-back tempo to house. Deep house fed New Jersey's gospel garage; its influence on South African house is one imported influence among others, not a direct lineage."},"afro":{"name":"Afro House (Afrique du Sud)","years":"fin 1980s–","x":560,"y":410,"label":"left","summary":"La house sud-africaine naît à Hillbrow et à Pretoria à la fin des années 1980 et coexiste avec le kwaito dans les années 1990. Black Coffee fonde Soulistic Music en 2005 : l'afro house devient une industrie. La house spirituelle américaine d'Osunlade (Yoruba Records) relève d'une autre histoire.","genres":["afro"],"summary_en":"South African house was born in Hillbrow and Pretoria in the late 1980s and coexisted with kwaito in the 1990s. Black Coffee founded Soulistic Music in 2005: afro house became an industry. Osunlade's American spiritual house (Yoruba Records) belongs to another story.","name_en":"Afro House (South Africa)","years_en":"late 1980s–"},"amapiano":{"name":"Amapiano (Log Drum)","years":"2016–","x":560,"y":640,"label":"left","summary":"Né au milieu des années 2010 dans le Gauteng, l'amapiano mêle kwaito, percussions bacardi, jazz, synthés de deep house et log drum, une basse percussive le plus souvent produite sur FL Studio, logiciel partagé dans les townships. Il se répand dans le monde à partir de 2020.","genres":["amapiano"],"machines":["log-drum"],"summary_en":"Born in the mid-2010s in Gauteng, amapiano blends kwaito, bacardi percussion, jazz, deep house synths and the log drum, a percussive bass most often produced on FL Studio, software shared across the townships. It spread worldwide from 2020."},"soundsystem":{"name":"Sound Systems Dub & Jazz-Funk","years":"1975–1988","x":500,"y":230,"label":"below-right","summary":"Avant l'acid house, la Grande-Bretagne danse sur les sound systems jamaïcains (le dub et la culture de la basse) et dans les all-dayers jazz-funk. Soul II Soul naît d'un sound system. La house britannique héritera de ce culte du sub-bass.","tracks":["keep-on-movin"],"sources":["join-the-future","carl-cox-oh-yes"],"summary_en":"Before acid house, Britain danced to Jamaican sound systems (dub and bass culture) and at jazz-funk all-dayers. Soul II Soul grew out of a sound system. British house would inherit this cult of sub-bass."},"shoom":{"name":"Shoom & Haçienda","years":"1987–1989","x":610,"y":230,"label":"above-right","interchange":true,"summary":"À Manchester, la soirée Nude de Mike Pickering joue de la house dès 1986 ; la nuit acid Hot (Pickering et Jon Dasilva) suit en 1988 (juillet ou novembre selon les sources). À Londres, Danny Rampling ouvre Shoom à l'automne 1987 au retour d'Ibiza, pour quelque 300 personnes. L'acid de Chicago devient le Second Summer of Love.","tracks":["promised-land","voodoo-ray","pacific-state","stakker-humanoid","acid-tracks","blue-monday"],"sources":["adventures-wonderland","hacienda-hook"],"summary_en":"In Manchester, Mike Pickering's Nude night played house from 1986; the acid night Hot (Pickering and Jon Dasilva) followed in 1988 (July or November depending on sources). In London, Danny Rampling opened Shoom in autumn 1987 after returning from Ibiza, for some 300 people. Chicago acid became the Second Summer of Love."},"bleep":{"name":"UK Bleep","years":"1989–1991","x":780,"y":230,"label":"above-right","interchange":true,"summary":"À Sheffield, Leeds et Bradford, des producteurs nourris de techno de Detroit et de sound systems inventent le bleep : des tonalités pures et un sub-bass énorme. Warp naît à Sheffield en 1989. C'est la première musique bass britannique.","tracks":["lfo"],"sources":["join-the-future"],"summary_en":"In Sheffield, Leeds and Bradford, producers raised on Detroit techno and sound systems invented bleep: pure tones and enormous sub-bass. Warp was born in Sheffield in 1989. Britain's first bass music."},"hardcore":{"name":"Hardcore & Jungle","years":"1991–1996","x":900,"y":230,"label":"below","summary":"La rave accélère : breakbeats samplés, stabs de synthé, basses reggae. Le hardcore se scinde vers 1994 en jungle et drum & bass, au cœur de ce que Simon Reynolds appelle le « hardcore continuum ».","genres":["rave-jungle"],"sources":["state-of-bass","energy-flash"],"summary_en":"Rave speeds up: sampled breakbeats, synth stabs, reggae basslines. Around 1994 hardcore splits into jungle and drum & bass, at the heart of what Simon Reynolds calls the \"hardcore continuum\"."},"ukg":{"name":"UK Garage (2-Step)","years":"1997–2002","x":1010,"y":230,"label":"above","summary":"Le garage new-yorkais accéléré et syncopé : le kick saute des temps, les voix R&B dansent. Sunday sessions, radios pirates et MCs en font une culture noire britannique.","genres":["ukg"],"links":["garage"],"summary_en":"New York garage sped up and syncopated: the kick skips beats, R&B vocals dance. Sunday sessions, pirate radio and MCs made it a Black British culture."},"dubstep":{"name":"Dark Garage / Dubstep","years":"2000–","x":1100,"y":430,"label":"right","summary":"Né vers 2000 de la dark garage (Zed Bias, El-B, Horsepower Productions) à Croydon et dans le sud de Londres. Les soirées FWD>> et DMZ en sont les lieux clés ; « Midnight Request Line » (Skream, 2005) ouvre la scène au monde, avant le virage « brostep » vers 2011.","tracks":["midnight-request-line","spongebob"],"sources":["energy-flash"],"summary_en":"Born around 2000 out of dark garage (Zed Bias, El-B, Horsepower Productions) in Croydon and south London. The FWD>> and DMZ nights were the key venues; \"Midnight Request Line\" (Skream, 2005) opened the scene to the world, before the \"brostep\" turn around 2011.","years_en":"2000–"},"balearic":{"name":"Balearic House (Ibiza)","years":"1984–1990","x":610,"y":60,"label":"left","interchange":true,"summary":"Alfredo est DJ à l'Amnesia dès 1984 et y mélange pop, rock indé et house en plein air : le balearic existe avant les Anglais. En septembre 1987, Oakenfold, Rampling, Holloway et Walker y vivent une révélation qu'ils exportent à Londres : c'est la correspondance avec Shoom.","genres":["balearic"],"summary_en":"Alfredo was DJing at Amnesia from 1984, mixing pop, indie rock and house under the open sky: balearic existed before the British arrived. In September 1987 Oakenfold, Rampling, Holloway and Walker had a revelation there and exported it to London: hence the transfer to Shoom.","years_en":"1984–1990"},"italo":{"name":"Italo-House","years":"1988–1995","x":740,"y":60,"label":"above","summary":"Les studios italiens recyclent house de Chicago, piano et mélodie méditerranéenne : Sueño Latino, Black Box, puis la « dream house » de Robert Miles. Un son de juke-box européen, souvent fait de samples.","tracks":["sueno-latino","children"],"summary_en":"Italian studios recycled Chicago house, piano and Mediterranean melody: Sueño Latino, Black Box, then Robert Miles's \"dream house\". A European jukebox sound, often built from samples."},"trance":{"name":"Trance","years":"1988–","x":840,"y":600,"label":"left","summary":"La trance sort de la techno de Francfort : Mixmag décrit l'Omen (1988) comme le lieu où la techno a muté en trance. Arpèges, montées et breaks euphoriques s'étendent ensuite aux clubs britanniques et ibizencs, jusqu'aux grands rassemblements néerlandais (borne 2005 du livre Hypnotised).","genres":["trance"],"sources":["hypnotised"],"summary_en":"Trance came out of Frankfurt techno: Mixmag describes the Omen (1988) as the place where techno mutated into trance. Arpeggios, builds and euphoric breakdowns then spread to British and Ibizan clubs, up to the big Dutch gatherings (the 2005 cut-off is that of the book Hypnotised).","years_en":"1988–"},"french":{"name":"French Touch","years":"1994–2002","x":1000,"y":60,"label":"above","summary":"Paris filtre la disco et la répète jusqu'à l'extase (Daft Punk, Cassius, Stardust). L'étiquette « French Touch » est forgée par la presse britannique vers 1996 ; Laurent Garnier et St Germain en sont des précurseurs ou des voisins, plus techno ou plus jazz. La bulle éclate au début des années 2000, avant une seconde vague électro (Ed Banger, Justice) en 2007.","genres":["french-touch"],"links":["chicago"],"summary_en":"Paris filtered disco and looped it to ecstasy (Daft Punk, Cassius, Stardust). The \"French Touch\" label was coined by the British press around 1996; Laurent Garnier and St Germain are precursors or neighbours, more techno or more jazz. The bubble burst in the early 2000s, before a second, electro wave (Ed Banger, Justice) in 2007."},"techhouse":{"name":"Tech House (Wiggle Londres)","years":"1994–","x":1100,"y":160,"label":"right","summary":"Les soirées Wiggle démarrent en mars 1994 (Terry Francis, Nathan Coles, Eddie Richards) ; Heart & Soul et The End sont les autres berceaux londoniens. La rigueur de la techno y rencontre la chaleur de la house, avant que la tech house ne devienne le son des méga-clubs d'Ibiza puis des festivals.","genres":["tech-house"],"name_en":"Tech House (Wiggle London)","summary_en":"The Wiggle parties started in March 1994 (Terry Francis, Nathan Coles, Eddie Richards); Heart & Soul and The End were London's other cradles. Techno's rigour met house's warmth there, before tech house became the sound of Ibiza's megaclubs and then of festivals.","years_en":"1994–"},"detroit":{"name":"Detroit Techno-Soul","years":"1983–","x":780,"y":440,"label":"below-right","interchange":true,"summary":"Juan Atkins, Derrick May et Kevin Saunderson imaginent une musique pour une ville que l'industrie abandonne : de la soul jouée par des machines. Underground Resistance en fera une éthique d'indépendance.","genres":["detroit"],"machines":["tr-909","tr-808"],"links":["chicago"],"summary_en":"Juan Atkins, Derrick May and Kevin Saunderson imagined music for a city abandoned by industry: soul played by machines. Underground Resistance turned it into an ethic of independence."},"soundsig":{"name":"Sound Signature (Detroit Deep)","years":"1997–","x":900,"y":440,"label":"above-right","summary":"Le label de Theo Parrish, fondé en 1997. Né à Washington D.C. en 1972, élevé à Chicago, formé à Kansas City, installé dans le Michigan en 1994 : des samples soul et jazz bruts, filtrés, saturés, et des tempos qui flottent. Son influence sur l'outsider house est une lecture éditoriale, à sourcer.","tracks":["summertime-is-here"],"summary_en":"Theo Parrish's label, founded in 1997. Born in Washington D.C. in 1972, raised in Chicago, trained in Kansas City, based in Michigan from 1994: raw, filtered, saturated soul and jazz samples and floating tempos. Its influence on outsider house is an editorial reading, to be sourced."},"lofi":{"name":"Outsider / Lo-Fi House","years":"2015–","x":1010,"y":550,"label":"below","summary":"Vers 2015-2016, YouTube et SoundCloud diffusent une house saturée et voilée (DJ Seinfeld, Ross From Friends, DJ Boring) : une scène internationale plus que londonienne, de l'Australie à la Suède. Le rapprochement avec le grain de Sound Signature est une lecture éditoriale, pas une filiation établie.","genres":["lofi"],"sources":["how-music-works"],"summary_en":"Around 2015–2016, YouTube and SoundCloud spread a saturated, hazy house (DJ Seinfeld, Ross From Friends, DJ Boring): an international scene more than a London one, from Australia to Sweden. The comparison with Sound Signature's grit is an editorial reading, not an established lineage."},"electro":{"name":"Électro","name_en":"Electro","years":"1979–1984","x":670,"y":440,"label":"above","summary":"Tokyo, le Bronx, Manchester. Avant Detroit, trois villes programment la machine : Tokyo avec YMO, le Bronx avec Planet Rock, Manchester avec Blue Monday. Kraftwerk en est le point commun. C'est l'origine de la ligne Futurisme & Machines.","summary_en":"Tokyo, the Bronx, Manchester. Before Detroit, three cities programmed the machine: Tokyo with YMO, the Bronx with Planet Rock, Manchester with Blue Monday. Kraftwerk is the common thread. This is where the Futurism & Machines line begins.","genres":["electro"],"machines":["tr-808"],"links":["shoom","detroit"]},"footwork":{"name":"Footwork & ghetto house","name_en":"Footwork & ghetto house","years":"1990s–","years_en":"1990s–","x":790,"y":140,"label":"above","summary":"La ghetto house de Chicago (Dance Mania, DJ Funk) accélère jusqu'au footwork, autour de 160 BPM, né des battles de danse. DJ Rashad et le collectif Teklife l'exportent au début des années 2010.","summary_en":"Chicago ghetto house (Dance Mania, DJ Funk) sped up into footwork, around 160 BPM, born from dance battles. DJ Rashad and the Teklife crew took it worldwide in the early 2010s.","genres":["footwork"]},"gqom":{"name":"Gqom (Durban)","name_en":"Gqom (Durban)","years":"2010s–","years_en":"2010s–","x":560,"y":520,"label":"left","summary":"À Durban, une house brute aux kicks lourds et brisés circule par les taxis et WhatsApp, puis s'exporte via des labels européens (la compilation The Sound of Durban Vol. 1 de Gqom Oh! en janvier 2016, Goon Club Allstars) au milieu des années 2010. À Londres, Scratcha DVA dit avoir retrouvé dans le gqom l'énergie de la face sombre du UK funky.","summary_en":"In Durban, a raw house of heavy, broken kicks circulated through taxis and WhatsApp, then spread via European labels (Gqom Oh!'s The Sound of Durban Vol. 1 compilation in January 2016, Goon Club Allstars) in the mid-2010s. In London, Scratcha DVA says he found in gqom the same energy as the darker side of UK funky.","genres":["gqom"]},"qweenbeat":{"name":"Qween Beat","name_en":"Qween Beat","years":"2005–","years_en":"2005–","x":710,"y":800,"label":"below","summary":"MikeQ fait remonter Qween Beat à 2005, d'abord comme nom sous lequel il publie sa musique, puis comme collectif ; le label publie sa première sortie officielle, Qweendom, en août 2016. Leur musique pour les balls part du « ha » et du crash de « The Ha Dance » ; elle est samplée par Beyoncé en 2022.","summary_en":"MikeQ dates Qween Beat back to 2005, first as the name he released his music under, then as a collective; the label put out its first official release, Qweendom, in August 2016. Their ball music builds on the \"ha\" and the crash of \"The Ha Dance\"; it was sampled by Beyoncé in 2022.","genres":["ballroom"]},"renaissance":{"name":"Renaissance","name_en":"Renaissance","years":"2022–","years_en":"2022–","x":940,"y":800,"label":"below","summary":"En 2022, Beyoncé (Renaissance) et Honey Dijon (Black Girl Magic) ramènent la house noire et queer au cœur de la pop, en citant explicitement ses pionniers et la ballroom.","summary_en":"In 2022 Beyoncé (Renaissance) and Honey Dijon (Black Girl Magic) brought Black and queer house back to the heart of pop, explicitly citing its pioneers and ballroom.","tracks":["not-about-you","break-my-soul"]},"berlin":{"name":"Berlin, Berghain & minimale","name_en":"Berlin, Berghain & minimal","years":"2004–","years_en":"2004–","x":930,"y":690,"label":"right","summary":"Berghain ouvre en 2004 dans une ancienne centrale ; Ostgut Ton, lancé fin 2005, publie en 2006 son premier maxi. Avec la minimale et la microhouse, Berlin devient le pont entre Detroit et l'Europe.","summary_en":"Berghain opened in 2004 in a former power station; Ostgut Ton, launched in late 2005, released its first 12\" in 2006. With minimal and microhouse, Berlin became the bridge between Detroit and Europe.","genres":["techno"],"sources":["rave-on"]},"charthouse":{"name":"House dans les charts","name_en":"Chart house","years":"2013–","years_en":"2013–","x":1100,"y":620,"label":"right","summary":"En 2013, Duke Dumont puis Disclosure placent la house en tête des classements britanniques : le genre sort des sous-sols vers les radios et Ibiza.","summary_en":"In 2013 Duke Dumont, then Disclosure, took house to the top of the UK charts: the genre left the basements for radio and Ibiza.","genres":["chart-house"]}},"transfers":[{"a":"warehouse","b":"paradise","title":"Le Warehouse ↔ Paradise Garage","text":"Frankie Knuckles et Larry Levan sont deux amis new-yorkais, formés ensemble dans la scène disco (notamment aux Continental Baths). En 1977, Knuckles part pour Chicago et le Warehouse, tandis que Levan prend le Paradise Garage. Les deux clubs viennent d'une même école : la house et le garage sont des cousins germains.","title_en":"The Warehouse ↔ Paradise Garage","text_en":"Frankie Knuckles and Larry Levan were two New York friends who came up together in the disco scene (notably at the Continental Baths). In 1977 Knuckles left for Chicago and the Warehouse, while Levan took over the Paradise Garage. Both clubs come from the same school: house and garage are first cousins."},{"a":"chicago","b":"deep","title":"Chicago House ↔ Deep House","text":"La deep house ne vient pas d'ailleurs : elle naît à Chicago en 1986, quand Larry Heard (Mr. Fingers) sort « Can You Feel It » sur Trax, au milieu du jack. On change de ligne sans changer de ville.","title_en":"Chicago House ↔ Deep House","text_en":"Deep house didn't come from elsewhere: it was born in Chicago in 1986, when Larry Heard (Mr. Fingers) released \"Can You Feel It\" on Trax, right in the middle of jack. You change lines without changing cities."},{"a":"acid","b":"shoom","title":"Acid House ↔ Shoom & Haçienda","text":"La TB-303 traverse l'Atlantique en 1987-1988 sous forme de maxis importés et de cassettes. À Londres (Shoom) et à Manchester (Haçienda), « Acid Tracks » devient la bande-son d'une jeunesse britannique, puis A Guy Called Gerald et 808 State en tirent un acid mancunien. Ce transfert a aussi déraciné le son de son public noir et gay d'origine.","title_en":"Acid House ↔ Shoom & Haçienda","text_en":"The TB-303 crossed the Atlantic in 1987–1988 as imported 12\"s and tapes. In London (Shoom) and Manchester (Haçienda), \"Acid Tracks\" became the soundtrack of British youth, and A Guy Called Gerald and 808 State drew a Mancunian acid from it. The transfer also uprooted the sound from its original Black and gay crowd."},{"a":"balearic","b":"shoom","title":"Ibiza ↔ Shoom","text":"En 1987, Paul Oakenfold, Danny Rampling et leurs amis découvrent à Ibiza l'éclectisme d'Alfredo à l'Amnesia. De retour à Londres, ils recréent l'esprit balearic dans de petites soirées (Shoom, Spectrum) qui allument le Second Summer of Love.","title_en":"Ibiza ↔ Shoom","text_en":"In 1987 Paul Oakenfold, Danny Rampling and friends discovered Alfredo's eclecticism at Amnesia in Ibiza. Back in London they recreated the balearic spirit at small parties (Shoom, Spectrum) that lit the fuse of the Second Summer of Love."},{"a":"bleep","b":"detroit","title":"UK Bleep ↔ Detroit","text":"À Sheffield et Leeds, les maxis de Detroit importés rencontrent la culture des sound systems caribéens. Les producteurs britanniques gardent le futurisme des machines et y ajoutent un sub-bass monumental. Matt Anniss raconte ce pont dans « Join the Future ».","title_en":"UK Bleep ↔ Detroit","text_en":"In Sheffield and Leeds, imported Detroit 12\"s met Caribbean sound-system culture. British producers kept the machine futurism and added monumental sub-bass. Matt Anniss tells this story in Join the Future."},{"a":"zanzibar","b":"afro","title":"Deep & gospel ↔ house sud-africaine (influence importée)","title_en":"Deep & gospel ↔ South African house (imported influence)","text":"Une influence, pas une filiation : la deep house new-yorkaise et du New Jersey arrive en Afrique du Sud par les disques et la radio, et s'y mêle au kwaito. Resident Advisor décrit l'amapiano comme un composite de deep house de style new-yorkais, de R&B et de kwaito.","text_en":"An influence, not a lineage: New York and New Jersey deep house reached South Africa through records and radio, and mixed there with kwaito. Resident Advisor describes amapiano as a composite of New York-style deep house, R&B and kwaito."},{"a":"soundfactory","b":"qweenbeat","title":"Sound Factory ↔ ballroom contemporain","title_en":"Sound Factory ↔ contemporary ballroom","text":"« The Ha Dance » de Masters at Work (1991), issu de la même scène house new-yorkaise que le Sound Factory, devient la colonne vertébrale de la musique des balls : MikeQ et Qween Beat en reprennent le « ha » et le crash.","text_en":"Masters at Work's \"The Ha Dance\" (1991), from the same New York house scene as the Sound Factory, became the backbone of ball music: MikeQ and Qween Beat reuse its \"ha\" and crash."}]},"decouvertes":{"_meta":{"note":"Rubrique « En ce moment » : écoutes et lectures du moment, la plus récente en premier à l'affichage.","kinds":"nouveau | redecouverte | lecture | film | mix","fields":"id, date (AAAA-MM-JJ), kind, title, artist ou author, year, label, note, note_en, youtube [ids vérifiés], track (id d'une fiche existante), station (id du métro), source (id de la Bibliothèque), link (URL), verify [points à vérifier]"},"entries":[{"id":"soul-of-hex-jet-set","date":"2026-11-27","kind":"nouveau","title":"Faith Beat 13 - Jet Set","artist":"Soul Of Hex","label":"Faith Beat","note":"De la pure house. Dancefloor banger. Point.","note_en":"Pure house. Dancefloor banger. Period.","bandcamp":{"url":"https://soulofhex.bandcamp.com/album/faith-beat-13-jet-set","type":"album","id":1326135261},"station":"deep","context":"Le projet des frères Gerardo et Emanuel Cedillo, basés à Tijuana (Mexique) : une deep house astrale aux textures jazz. Leur premier disque sur Faith Beat (sorti le 27 mars 2026) : quatre titres de house lourde, tirés vers la techno, taillés pour le dancefloor.","context_en":"The project of Tijuana-based brothers Gerardo and Emanuel Cedillo, crafting deep, astral house with jazz-tinged textures. Their Faith Beat debut (released 27 March 2026): four heavyweight house tracks with a driving techno edge, built for the floor.","highlight":"Feel The Power Of Love","year":2026}]}};
